// index.js — ربات فال تاروت فارسی 🔮
//
// بازسازی سفر مشتریِ یک تاروت‌خوان حرفه‌ای در تلگرام (۵ مرحله):
//  ۱) پیش‌جلسه: پرسشنامه‌ی تمرکز + سؤال کاربر (متن/ویس)
//  ۲) فضاسازی: مدیریت انتظارات + تمرین تنفس
//  ۳) خوانش: بُر زدن با توقفِ کاربر → انتخاب ۳ کارت از گرید ۲۴تایی →
//     پی‌وال دقیقاً قبل از افشا (اوج کنجکاوی) → افشای مرحله‌ای با spoiler →
//     حلقه‌ی بازخورد وسط خوانش (پاسخ منفی = فراخوانی کوچک تصحیح)
//  ۴) پایان‌بندی: روایت پیوندی + سه قدم عملی + جمله‌ی توانمندساز
//  ۵) قلاب بازگشت: مدیاگروپ یادگاری + milestone ۱۴روزه + کد تخفیف اولین خرید + رفرال
//
// مغز فالگیر: google/gemini-2.5-flash (OpenRouter) — تک‌فراخوانی per فال، پیش‌فراخوانی بعد از انتخاب کارت سوم.
// چندزبانه: همه‌ی متن‌ها/پرامپت‌ها از locales/<LOCALE>.js؛ هر زبان بعداً یک اپ pm2 جدا با ENV_FILE خودش.
import dotenv from 'dotenv';
dotenv.config({ path: process.env.ENV_FILE || '.env' });
import { mkdirSync, existsSync } from 'fs';
import { createHash } from 'crypto';
import { Telegraf, Markup } from 'telegraf';
import Database from 'better-sqlite3';
import CARDS, { CARD_BY_KEY } from './cards.js';
import SPREADS, {
  DAILY, SPREAD_BY_ID, SPREADS_V3, spreadsFor, faOf,
  TOPICS_V3, TOPIC_BY_KEY, SIZES_V3, spreadIdOf, topicOf,
} from './spreads.js';
import { log, logErr } from '../../shared/logger.js';
import { registerGlobalErrorHandlers } from '../../shared/errors.js';
import { EVENTS, ensureAnalytics, track, trackOnce, captureStart } from '../../shared/analytics.js';
import { ensureAb, variant } from '../../shared/ab.js';
// پشتیبانی مشترکِ همه‌ی ربات‌ها (حساب + کدِ پیگیری + لینکِ پیامِ آماده) — متن‌ها از locale می‌آیند
import { registerSupport, supportRow, supportReply } from '../../shared/support.js';
import { loadingFrame, pace, LOADERS, ACTIVE } from './loading.js';
// ثبتِ خودکارِ مسیرِ ریزِ کاربر (view/act) — قیفِ ریزِ داشبورد از همین تغذیه می‌شود
import { registerJourney } from '../../shared/journey.js';
import { analyzeReceipt, decideReceipt } from './cardpay.js';
import { scoreSpreads, RECO } from './reco.js';
import { normalizeVerdict, decisiveMode, headlineOk, evasionIn } from './verdict.js';
import { repairDefects } from './repair.js';
import { monthFa, eligibleCards, pickVariant, textOf as ganjinehText, countOf as ganjinehCount, NO_REPEAT_DRAWS } from './ganjineh.js';
// هسته‌ی خالصِ خوانش: کلاینتِ OpenRouter، موتورِ دک، کانتکست و رندرِ متنِ نهایی.
// همان کد را `tools/reading-lab.mjs` هم صدا می‌زند تا تستِ آفلاین دقیقاً همان چیزی را
// اجرا کند که کاربر می‌بیند (کپی نداریم، پس drift ممکن نیست).
import {
  FLASH, FALLBACK_MODEL, OR_TIMEOUT_MS,
  orChatResilient, orTranscribe, parseJsonLoose,
  seedToInt, shuffledDeck, drawCards, tehranToday, GRID_SIZE,
  checkV4Shape, softMissesV4, v4Text,
  buildReadingCtx, renderV4,
} from './reading-core.js';

/* ===== 1) ENV و ثابت‌ها ===== */
const BOT_TOKEN          = process.env.BOT_TOKEN?.trim();
const OPENROUTER_API_KEY = process.env.OPENROUTER_API_KEY?.trim();
if (!BOT_TOKEN)          { logErr('❌ BOT_TOKEN خالی است');          process.exit(1); }
if (!OPENROUTER_API_KEY) { logErr('❌ OPENROUTER_API_KEY خالی است'); process.exit(1); }

const LOCALE = process.env.LOCALE?.trim() || 'fa';
const L = (await import(`./locales/${LOCALE}.js`)).default;
const fmt = L.fmt;
// فال حافظ: دیتای استاتیک (فقط fa؛ زبان‌های دیگر بدون فایل = فیچر خودکار غیرفعال)
const HAFEZ = await import(`./hafez.js`).then(m => m.default.ghazals).catch(() => []);
// کوییز «کدام کارتِ تاروتی؟»: متنِ شخصیتی per کارتِ آرکانای بزرگ (سؤال‌ها/امتیازدهی در locale)
const QUIZ = await import(`./quiz.js`).then(m => m.default.personalities).catch(() => ({}));
// 📚 جدولِ دانشِ کارت (فارسی، تولیدِ آفلاین از منبعِ آموزشی — tools/build-card-knowledge.mjs).
// **RAG نیست و لازم هم نیست:** کلیدِ بازیابی قطعی است (می‌دانیم کدام کارت کشیده شده)، پس یک
// lookup کافی است — بدونِ embedding، بدونِ شبکه، زیر یک میلی‌ثانیه.
// فقط ردیفِ همان کارت‌هایی که کشیده شده‌اند به پرامپت می‌رود، نه کلِ جدول.
// fail-safe: اگر فایل نباشد یا خراب باشد، خوانش دقیقاً مثل قبل کار می‌کند.

const MAX_VOICE_SEC  = 120;              // سقف طول ویسِ سؤال (خودِ فایل به مدل می‌رود، پس سقف = سقفِ توکنِ ورودی)
const MAX_VOICE_BYTES = 3 * 1024 * 1024;

// ⚠️ TEST_PHASE: تا وقتی true است دکمه‌ی «ریست ربات (تست)» برای همه فعال است.
// false = ربات زنده (لانچ ۱۴۰۵/۰۴/۲۰): دکمه کلاً مخفی؛ /reset فقط برای OWNER می‌ماند.
const TEST_PHASE = false;

// نسخه‌ی محصول (کوهورت users.first_version): با هر تغییر «رفتاری» رو-به-کاربر bump کن — بند «قوانین ربات زنده» CLAUDE.md ریشه
// 1.1.0: رسیدِ پرداخت از ایجنتِ کارت‌به‌کارت (auto-approve + برگشت/بی‌اعتمادی) رد می‌شود.
// 1.1.1: فلوی رسید انسانی‌تر شد (پیامِ «فرستاده شد» + تأخیرِ ۳ تا ۱۰ ثانیه، بدونِ لوکنندنِ ایجنت)
//        + گاردِ قطعیِ مبلغِ بیشتر (پرداختِ اضافه → تأیید، نه رد) + تضمینِ اطلاع‌رسانیِ رد به کاربر.
// 1.1.2: فقط دو پیامِ نهاییِ رسید (تأیید/رد یکپارچه با پشتیبانی @Efficient_Support، بدونِ «رسید نیست»/دلیل)
//        + دکمه‌ی «کپی شماره کارت» (copy_text) زیرِ فاکتورهای کارت‌به‌کارت.
// 1.3.0: ناوبری درختی + گاردِ فلوی بازِ پرداخت (قرارداد State Management یکپارچه) — پشتِ NAV_GUARD_ENABLED.
// 1.3.1: پالایشِ کپیِ آنبوردینگ/خوانش — دکمه‌ی سوم «همه فال‌ها»، کارت روز در کاتالوگ،
//        آشکارسازیِ کیبورد بعد از «یه قرار کوچیک»، انتقال جمله‌ی فضای امن به قبلِ نوشتنِ سؤال.
// 1.4.0: استیت‌های ورودی (askQuestion/askTopic) دیگر دکمه ندارند (تمرکز روی نوشتن) + گاردِ «فالِ باز»
//        (blockDuringOpenReading) با دو دکمه‌ی «ادامه/انصراف» — قرارداد State Management بند ۹ب.
// 1.5.0: دکمه‌ی «💬 پشتیبانی» در منوی اصلی (مشترکِ همه‌ی ربات‌ها) — لینکِ چتِ پشتیبانی با
//        پیامِ آماده‌ی حاویِ کدِ پیگیریِ #TRT-<user_id> (shared/support.js).
// 1.6.0: بازطراحیِ پی‌والِ کم‌موجودی (بزرگ‌ترین نقطه‌ی ریزش): پیامِ کوتاهِ شخصی‌شده با تعدادِ
//        کارت و قیمت، تخفیف از پیام حذف و پشتِ دکمه‌ی «تخفیف می‌خوام» رفت، تخفیفِ اولین شارژ
//        ۳۵٪→۵۰٪ و دیگر خودکار نیست (کدِ شخصیِ کپی‌شدنی)، و برای کاربرِ شارژکرده مسیر دعوت دوستان.
// 1.6.1: سه فیکسِ ریلِ پرداخت (از تحلیلِ جرنیِ یک کاربرِ واقعی): کدِ تخفیفِ اشتباه دیگر کاربر را
//        از مرحله‌ی کد بیرون نمی‌اندازد، متنی که خودش یک کدِ تخفیف است دیگر «رسید» حساب نمی‌شود،
//        و شروعِ فالِ جدید وقتی فالِ رزروشده منتظرِ پرداخت است دیگر آن را بی‌صدا یتیم نمی‌کند.
// 1.6.2: کدِ تخفیفِ اولین شارژ دیگر با یک فاکتورِ رهاشده برای همیشه قفل نمی‌شود (فاکتورِ
//        pending بدونِ رسید عملاً غیرقابل‌دسترس است و نباید کد را نگه دارد)، پیامِ «قبلاً
//        استفاده شده» از «نامعتبر» جدا شد، و پیشنهادِ کد با پذیرشِ کد هم‌شرط شد.
// 1.7.0: دکمه‌ی «🎁 تخفیف می‌خوام» در پی‌وال فقط برای کسی که واقعاً تخفیفِ اولین شارژ
//        دارد نشان داده می‌شود، و مسیرِ «دعوت دوستان به‌جای تخفیف» حذف شد (وسطِ فالِ
//        رزروشده کاربر را از خریدش منحرف می‌کرد). تک‌منبعِ شرط: firstDiscountAvailable().
// 2.0.0: بازطراحیِ کاملِ ورود و ریلِ اولین پرداخت — هدیه‌ی خوش‌آمدِ ۳۰k (آنبوردینگ دو پیامی:
//        اول ارزش، بعد اسم)، اولین فالِ سه‌کارتی بدونِ پی‌وال، دکمه‌ی «پرداختِ هزینه‌ی همین فال»
//        به‌جای مرحله‌ی «چقدر شارژ کنم؟»، تخفیفِ اولین پرداخت ۵۰٪→۲۰٪ و فقط روی همان فال
//        (بدونِ کد و بدونِ سقف)، نردبانِ شارژ ۵۰/۱۰۰/۲۰۰k با هدیه فقط از ۲۰۰k، و حذفِ پوشِ
//        دوهفته‌ای به نفعِ تنها قلاب بازگشت: یادآوریِ شبانه‌ی کارت روز با انصرافِ دومرحله‌ای.
// 2.1.0: پیشنهاددهنده‌ی امتیازی جای پیشنهادِ هاردکد را گرفت (کارتِ روز دیگر همان فالی را
//        که کاربر تازه گرفته پیشنهاد نمی‌دهد) + کیبوردِ منو دیگر گم نمی‌شود.
// 2.2.0: صفِ اقدامِ پشتیبانی (تأییدِ دستیِ پرداختِ ردشده، شارژ/کسرِ دستی، بازکردنِ فال) +
//        حداقلِ مبلغ شارژ، بعد از باگی که یک «۸» یک کدِ ۱۰۰٬۰۰۰ تومانی را سوزاند.
// 2.3.0: پرداختِ کمتر از فاکتور دیگر رد نمی‌شود؛ فاکتور به مبلغِ واقعاً پرداخت‌شده اصلاح
//        می‌شود، کاربر دقیقاً همان‌قدر اعتبار می‌گیرد و دلیلِ اصلاح لاگ می‌شود.
// 2.4.0: فال‌های تصمیم‌محور (آری یا نه، دوراهی) با یک «جوابِ قاطع + نشونه» تمام می‌شوند،
//        از فیدبکِ کاربرِ واقعی که گفت جوابِ روشنی که دنبالش بود را نگرفت.
// 2.5.0: کاربری که اعتبارش کافی است دیگر صفحه‌ی قیمت‌دار نمی‌بیند؛ صریح می‌گوید پرداختی
//        لازم نیست. از تحلیل جرنی: کاربرانی با موجودیِ دقیقاً کافی یک تپ تا فالشان مانده
//        بودند و حرکت نمی‌کردند، یعنی مانع پول نبود، صفحه شبیه پی‌وال بود.
// 2.7.0: گیتِ عضویت در کانال برای کاربرِ جدید (معرفی → دعوت به عضویت → هدیه لحظه‌ی تأیید)
//        + «عشق و رابطه» محبوب‌ترین و اولِ کاتالوگ شد، سه‌کارتی و ۳۰٬۰۰۰ تومان یعنی دقیقاً
//        هم‌اندازه‌ی هدیه‌ی خوش‌آمد، تا کاربرِ تازه پرتقاضاترین فال را با اعتبارِ هدیه بگیرد.
// 2.7.1: حذفِ تکرارِ معرفی بعد از گرفتنِ نام (کاربر یک متن را دو بار می‌دید) و جایگزینی‌اش
//        با فکتِ واقعیِ «۸۶٪ گفتن خوانششون با واقعیت خوند» + پررنگ‌کردنِ «هوش مصنوعی» در معرفی.
// 2.7.2: سه فیکس از تستِ دستیِ مالک — یادآوریِ گیت روی آپدیتِ سرویسیِ my_chat_member
//        فرستاده می‌شد، ریستِ ادمین وسطِ گیت بلاک می‌شد، و payloadِ اتریبیوشن از کلمه‌ی
//        دومِ هر متنی خوانده می‌شد (ریستِ ادمین `payload:"ریست"` ثبت می‌کرد). + کپیِ فکت.
// 2.7.3: بازنویسیِ پیامِ اول (بدونِ توضیحِ مکانیک؛ «همون تجربه‌ی تاروت‌خوانِ حرفه‌ای، فقط
//        توی جیبت») + آزمایشِ A/B روی همان پیام: control با بندِ «قدرتش رو از هوش مصنوعی
//        می‌گیره» و no_ai بدونِ آن. تک‌متغیره، تا نتیجه تفسیرپذیر بماند.
// 2.8.0: موضع‌گیریِ «هوش مصنوعی» از فلو برداشته شد (بیرون از ربات، روی بنر تبلیغاتی تست
//        می‌شود) و آزمایشِ gate_intro_ai متوقف شد. به‌جایش آزمایشِ intro_order: همان دو
//        بلوکِ آنبوردینگ، فقط ترتیبشان عوض می‌شود (تجربه اول یا آمار اول).
// 2.9.0: کاتالوگ با هدیه هم‌تراز شد — همه‌ی فال‌های موضوعیِ ۵کارتی/۵۰k به ۳کارتی/۳۰k
//        رفتند (قانونِ ۱۰k per کارت دست‌نخورده؛ قیمت با کم‌کردنِ کارت پایین آمد، نه با
//        تخفیف). از تحلیلِ دور پنجم: فالِ گران‌تر از هدیه ۷٪ تحویل داشت و ارزان‌تر ۷۱٪.
// 2.9.1: اصلاحِ ابهامِ کپیِ «دو مورد اول» در پیشنهادِ فالِ بعدی ← «دو تا پیشنهاد اول»
//        (کاربرِ واقعی فکر کرده بود منظور دو تا کارتِ اوله).
// 3.0.0: دو تغییرِ بنیادین، هر دو **فعلاً فقط روی اکانتِ ادمین** (تصمیمِ صریحِ مالک: اول
//        خودش تست کند، بعد برای همه باز شود):
//        (۱) لحنِ خوانش: صریح، بی‌طفره، و پایانِ **هر** فال یک جوابِ مشخص + نشونه.
//        (۲) اقتصادِ سکه: واحدِ پولِ داخلی + سه بسته‌ی خرید + کاتالوگِ عشق‌محورِ تقابلی.
// 3.0.1: بازنویسیِ صدا از روی خوانش‌های واقعیِ یک تاروت‌خوانِ انسان (bots/tarot/STYLE.md):
//        فارسیِ گفتاری، حذفِ برچسبِ «نشونه‌ات» و شعارِ پایانی، و تصحیحِ مهم‌ترین اشتباهِ
//        نسخه‌ی قبل — زبانِ احتمال ممنوع نیست، جوابِ بی‌جهت ممنوع است.
// 3.1.0: تمرکز فقط روی کیفیتِ خروجی (تصمیمِ مالک). اقتصادِ سکه و کاتالوگِ نسل دوم **پارک**
//        شدند (پرچم خاموش، کد سرِ جایش) و آزمایشِ نامِ واحد منحل شد. پرامپت فشرده شد چون
//        ورودیِ متورم روی Flash هم گران است هم کیفیت را پایین می‌آورد. جمله‌های دلداریِ
//        پراکنده‌ی وسطِ جرنی هم در لحنِ جدید حذف شدند.
// 3.2.0: «سه قدم عملی» از پایانِ خوانش حذف شد (لحنِ کوچینگ می‌ساخت) و جدولِ دانشِ
//        کارت به فارسی **دستی** نوشته شد — کلیدِ OpenRouter فقط برای خودِ محصول است.
// 3.3.0: 🎯 لحنِ جدید برای **همه‌ی کاربران** باز شد (تا اینجا فقط ادمین بود). مالک لحن را
//        دستی تست و تأیید کرد. از این تاریخ هر کاربر این‌ها را می‌گیرد: پرامپتِ v2 (صدای
//        تاروت‌خوانِ انسان، حداکثر یک ایموجی، زبانِ احتمالِ جهت‌دار)، جوابِ قاطع در پایانِ
//        **هر** فال با دلیلِ لنگرخورده به نامِ کارت‌ها، جدولِ دانشِ ۷۸ کارت در پرامپت،
//        حذفِ سه قدمِ عملی و شعارِ پایانی و جمله‌های دلداریِ وسطِ جرنی، و پرسشِ «سؤالت چیه»
//        به‌جای «موضوعت چیه». هدفِ سنجش: **ریتنشن** (بازگشت و فالِ دوم) و کیفیتِ فیدبک.
// 3.4.0: 💸 قاعده‌ی هزینه: هیچ فراخوانیِ پولی قبل از کسرِ اعتبار. دو نشتی بسته شد
//        (رونویسیِ ویس لحظه‌ی ارسال، و پیش‌فراخوانیِ خوانش قبل از پی‌وال). ضمناً سؤالِ
//        صوتی حالا **یک** فراخوانی است: خودِ فایل کنارِ پرامپت به مدل می‌رود.
// 3.5.0: 🔮 بازطراحیِ ساختارِ خوانش (v4، فقط ادمین) از روی تحلیلِ خوانش‌های واقعیِ
//        انسانی + دو تحقیقِ مستقل: افشا = تیزرِ کوتاه، متنِ نهایی با **جواب** شروع
//        می‌شود، و بازخورد به آخرِ کار رفت با مقیاسِ ۱ تا ۵ درباره‌ی **رضایت**.
// 3.5.1: از تستِ میدانیِ سه فال: نقشه‌ی راه قبل از انتظار، کپشنِ ترتیبی (جا افتاده بود)،
//        تیزرِ واقعیِ کارت (نام+تصویر+معنی)، ایموجیِ بخش‌بندی، و سه فیکسِ کیفی —
//        نشتِ جمله‌ی نمونه، لغزشِ «شما»، و نبودِ حافظه/پنجره‌ی زمانی.
// 3.5.2: از دورِ دومِ تست — شماره‌گذاریِ ترتیبیِ کارت‌ها، دکمه‌ی «حالا جوابم رو بگو»
//        زیرِ کارتِ آخر (جمع‌بندی دیگر خودکار نمی‌آید)، فشرده‌سازیِ چیدمانِ بزرگ، و دو
//        باگ: تکرارِ برچسب و نشتِ دومِ مثالِ پرامپت در فیلدِ callback.
// 3.5.3: انضباطِ ورودی و «هرچه کد می‌تواند تضمین کند، در پرامپت نیاید»: شماره‌گذاریِ
//        کارت‌ها قطعی و از کد (strip+prefix)، پاک‌کردنِ خط تیره در کد، و قفلِ CI روی
//        سقفِ بدترین‌حالتِ ورودیِ مدل.
// 3.5.4: دورِ سوم — ریشه‌ی باگِ «پارسال» (فالِ قبلی تاریخ نداشت) با داده حل شد،
//        خوانشِ کارت‌ها یک بلوکِ پیوسته شد (نه ایموجی per کارت)، سؤالِ بازخورد با
//        ادعای ۸۶٪ هم‌راستا شد، و دو تکنیکِ تحقیق ۲ به‌شکلِ لنگرخورده اضافه شدند.
// 3.22.0: دستورِ فقط-ادمینِ /reel — ساختِ ویدیوی ریلز از یک فالِ ناشناس. رفتارِ هیچ
//         کاربرِ واقعی‌ای عوض نمی‌شود، ولی طبق بند ۲ج/۴ فیچرِ فقط-ادمین هم نسخه می‌گیرد.
// 3.24.0: نگارشِ انبوهِ گنجینه تمام شد — ۹۳۶ متن (۱۲ ماه × ۷۸ کارت × ۱ نسخه)،
//         دیگر هیچ کاربری به پیامِ «گنجینه‌ی این ماه آماده نیست» نمی‌خورد.
const PRODUCT_VERSION = '3.26.0';
const FOCUS_REASK_DAYS = 7; // حوزه‌ی تمرکز حداکثر هفته‌ای یک‌بار دوباره پرسیده می‌شود (نه هر فال)

// 🎁 منوی سرگرمی‌های رایگان (کارت روز + فال حافظ؛ قلاب بازگشت روزانه بدون LLM).
// فعلاً خاموش عرضه می‌شود (dark launch): merge روی ربات زنده هیچ تغییرِ رفتاری نمی‌دهد.
// روشن‌کردن = یک‌خط true + bump PRODUCT_VERSION به 1.1.0 در همان PR (تغییرِ رفتاری).
// Rollback فوری: دوباره false کن → دکمه‌ی کیبورد، منو و همه‌ی callbackها محو و رفتار دقیقاً مثل قبل.
const FREE_MENU_ENABLED = false;

// 🌀 فال با موضوع آزاد: به کاربر سیگنال می‌دهد می‌تواند درباره‌ی «هر موضوعی» فال بگیرد (نه فقط کاتالوگ ثابت).
// Rollback فوری: این را false کن → دکمه و کپی‌های موضوع آزاد کاملاً محو می‌شوند و رفتار دقیقاً مثل قبل می‌شود
// (فال‌های open3/open5 که قبلاً ثبت شده‌اند بی‌ضرر در DB می‌مانند؛ پایپ‌لاین افشا از SPREAD_BY_ID می‌خواند).
const OPEN_TOPIC_ENABLED = true;

// 🧭 ناوبری درختی + گاردِ فلوی باز (قرارداد State Management، CLAUDE.md ریشه): هر استیتِ میانیِ فلو دکمه‌ی
// «بازگشت به منو» می‌گیرد، و پرداختِ باز دکمه‌های منو را بلاک می‌کند (پیام «فاکتور باز داری» + انصراف)
// به‌جای یتیم‌کردنِ بی‌صدای فاکتور. Rollback فوری: false کن → دکمه‌های nav و گارد محو، رفتار دقیقاً مثل قبل
// (callbackِ nav:menu ثبت‌شده می‌ماند تا دکمه‌ی کش‌شده هم بی‌خطر باشد).
const NAV_GUARD_ENABLED = true;

// 🪙 UX v2.6 — نقطه‌ی کسرِ اعتبار از **پی‌والِ بعد از انتخابِ کارت‌ها** به **لحظه‌ی انتخابِ
// اندازه** منتقل شد (تصمیمِ صریحِ مالک). یعنی کاربر همان‌جا که «۵ کارتی (➖۵💎)» را می‌زند
// پول می‌دهد، و دیگر جلوتر هیچ پی‌والی نمی‌بیند.
// این پرچم **عمداً از UX_V2 جداست** تا رول‌بکش مستقل باشد: false → دقیقاً مسیرِ قبلی
// (insert در finishPicking + پی‌وال + کسر در unlock:) بدونِ اینکه بقیه‌ی UX v2 خاموش شود.
const PAY_AT_SIZE = true;
const payAtSizeFor = (uid) => PAY_AT_SIZE && uxV2For(uid);

// 🧭 ثبتِ خودکارِ مسیرِ ریزِ کاربر (shared/journey.js): هر پیامِ خروجی (`view`) و هر اکشنِ ورودی
// (`act`) ثبت می‌شود تا در داشبورد بشود دید کاربر دقیقاً پشتِ کدام پیام/دکمه ریخته است.
// کاملاً fail-safe و بدونِ هیچ اثرِ رو-به-کاربر. Rollback فوری: false کن → هیچ رویدادِ ریزی
// ثبت نمی‌شود و هیچ متدی رپ نمی‌شود (رفتار دقیقاً مثل قبل؛ دیتای ثبت‌شده بی‌ضرر می‌ماند).
const JOURNEY_ENABLED = true;

// 🔑 عضویتِ اجباری در کانال برای کاربرِ **جدید** (v2.7.0): قبل از هدیه‌ی خوش‌آمد، کاربر یک
// پیامِ کوتاهِ معرفی می‌بیند و بعد دعوت به عضویت در کانال. هدیه دقیقاً لحظه‌ی تأییدِ عضویت
// واریز می‌شود، پس عضویت یک «هزینه» نیست، کلیدِ گرفتنِ هدیه است.
//
// دامنه‌ی گارد عمداً باریک است (بند ۲ج: کاربرِ زنده وسط فلو نباید بشکند): فقط کسی گیت
// می‌خورد که **هنوز هدیه‌ی خوش‌آمد نگرفته** باشد. هر کاربرِ فعلی، حتی نیمه‌آنبورد، از قبل
// هدیه را گرفته پس هرگز گیت نمی‌بیند و تجربه‌اش ذره‌ای عوض نمی‌شود.
//
// Rollback فوری: false کن → گیت و میدل‌ورش کاملاً محو، فلو دقیقاً مثل قبل (کاربرانی که
// gate را رد کرده‌اند بی‌ضرر می‌مانند؛ callbackِ gate:check ثبت می‌ماند تا دکمه‌ی کش‌شده خطا ندهد).
const JOIN_GATE_ENABLED = true;
const GATE_CHANNEL     = process.env.GATE_CHANNEL?.trim() || '@taroot_fa';
const GATE_CHANNEL_URL = process.env.GATE_CHANNEL_URL?.trim() || 'https://t.me/taroot_fa';
// وضعیت‌هایی که یعنی «عضو است». `restricted` فقط وقتی عضو است که is_member هم true باشد.
const GATE_OK_STATUS = new Set(['member', 'administrator', 'creator']);

// ⚖️ جوابِ قاطع برای فال‌های تصمیم‌محور (spreads.js → decisive؛ فعلاً آری/نه و دوراهی).
// از فیدبکِ کاربرِ واقعی: «اون جوابی که می‌خواستم رو آخر نفهمیدم و نگرفتم... اگه توش
// نشونه‌ای بتونه ببینه توی اون جوابه، می‌تونه خودشو آروم کنه.» منطقِ خالص: verdict.js
// Rollback فوری: false کن → پرامپت و پیامِ جواب کاملاً محو، خوانش دقیقاً مثل قبل
// (فال‌هایی که verdict شان در DB ذخیره شده بی‌ضرر می‌مانند و فقط نمایش داده نمی‌شوند).
const DECISIVE_VERDICT_ENABLED = true;

// 💳 صفحه‌ی «اعتبارت کافیه» به‌جای صفحه‌ی قیمت‌دار، برای کاربری که موجودی‌اش هزینه‌ی فال را
// پوشش می‌دهد. از تحلیل جرنی: چند کاربر با موجودیِ دقیقاً کافی در confirm_pay مانده بودند،
// یعنی مانع پول نبود؛ صفحه شبیه پی‌وال بود و نمی‌فهمیدند پرداختی لازم نیست.
// Rollback فوری: false کن → همان دکمه‌ی قیمت‌دار و متنِ قبلی برمی‌گردد، بدونِ هیچ اثر دیگری.
const COVERED_PAYWALL_ENABLED = true;

// 🎬 ویدیوی ریلز (فقط ادمین): دستورِ /reel یک ورک‌فلوی گیت‌هاب را صدا می‌زند که سوالِ بعدی
// را از Notion برمی‌دارد، یک فالِ **ناشناس** می‌گیرد (بدونِ نام و بدونِ حافظه) و خروجی را
// به‌جای متن، یک ویدیوی عمودیِ بی‌صدا می‌سازد و در همین چت می‌فرستد.
// خودِ ربات هیچ رندری نمی‌کند: نه Chrome می‌خواهد، نه CPU می‌گیرد، نه فلوی کاربرِ واقعی را
// لمس می‌کند. تنها کارش یک ریکوئستِ HTTP است.
// Rollback یک‌خطی: false کن → دستور کاملاً بی‌اثر می‌شود (کاربر عادی هم اصلاً نمی‌بیندش).
const VIDEO_REEL_ENABLED = true;
const VIDEO_DISPATCH_REPO = 'darkgreenblue/Telegram_bots';
// واریانت‌های مجازِ پس‌زمینه. allowlist عمدی است: آرگومانِ کاربر هرگز خام وارد payloadِ
// گیت‌هاب نمی‌شود، حتی وقتی فرستنده ادمین است.
const VIDEO_BACKGROUNDS = ['mystic', 'nature', 'minimal'];

// ادمین‌ها از env (کامای ADMIN_IDS که deploy از OWNER_TELEGRAM_ID می‌سازد) — مشترک با بقیه‌ی ربات‌ها
const ADMIN_IDS = (process.env.ADMIN_IDS || '100257975')
  .split(',').map(s => parseInt(s.trim(), 10)).filter(Number.isFinite);
const OWNER_ID  = ADMIN_IDS[0] || 100257975;
const isAdmin = (uid) => ADMIN_IDS.includes(uid);

// 🧪 **تستر** — کاربری که همه‌ی فیچرهای در-حالِ-تست (که فعلاً `_ADMIN_ONLY` اند) را می‌بیند
// و دکمه‌ی «ریست حساب» دارد، ولی **هیچ اختیارِ ادمینی ندارد**: نه تأیید/ردِ رسید، نه
// `/stats` و `/newcode`، نه هشدارهای مالی، نه هیچ دکمه‌ی ادمینِ دیگری.
//
// ⚠️ عمداً از `ADMIN_IDS` جداست و نباید با آن یکی شود: افزودنِ یک تستر به آن لیست،
// اختیارِ دست‌زدن به **پولِ کاربرانِ واقعی** را هم به او می‌داد (بند ۹ ریشه).
// افزودن/حذفِ تستر = ویرایشِ همین یک آرایه.
const TESTER_IDS = [
  5725984933,   // تسترِ دعوت‌شده‌ی مالک (۱۴۰۵/۰۵/۲۹)
];
// فیچرهای در-حالِ-تست از این می‌خوانند، نه از isAdmin — پس ادمین هم خودکار تستر است.
const isTester = (uid) => isAdmin(uid) || TESTER_IDS.includes(uid);

// ───────────────────────────────────────────────────────────────────────────
// 🎭 نسخه‌ی دومِ لحنِ خوانش (v3.0.0)
// ───────────────────────────────────────────────────────────────────────────
// چرا: ریتنشن پایین بود و فیدبکِ کاربرها و چند تاروت‌خوانِ حرفه‌ای یک حرفِ مشترک داشت —
// خوانش‌های ما محتاط، وسط‌باز و پر از «شاید» بودند و کاربر بدونِ جواب می‌رفت. نسخه‌ی دوم
// صریح می‌نویسد و **هر** فال (نه فقط فال‌های تصمیم‌محور) با یک جوابِ مشخص + نشونه تمام می‌شود.
//
// ✅ از v3.3.0 برای **همه‌ی کاربران** باز است. مسیرِ مرحله‌ای طبق بند ۲ج-۲ ریشه طی شد:
// از v3.0.0 تا v3.2.0 فقط اکانتِ ادمین آن را می‌دید، مالک دستی تست کرد و لحن را تأیید کرد
// (۱۴۰۵/۰۵/۲۵). Rollback فوری و بدونِ فکر: `READING_TONE_V2 = false` → پرامپت، رندرِ جواب،
// جمله‌های حذف‌شده و سه قدمِ عملی همه دقیقاً به حالتِ قبل برمی‌گردند.
// نکته: `_ADMIN_ONLY` عمداً حذف نشد تا اگر خواستیم دوباره فیچری را ادمین-محدود کنیم،
// مسیرِ باریک‌کردن هم یک‌خطی بماند (همان دو-پرچمِ بند ۲ج-۲).
const READING_TONE_V2 = true;
const READING_TONE_V2_ADMIN_ONLY = false;

// 🔮 ساختارِ خوانشِ v4 (v3.5.0) — بازطراحیِ کاملِ شکلِ خروجی بر اساسِ تحلیلِ خوانش‌های
// واقعیِ انسانی + دو تحقیقِ مستقل. جزئیات و وزنِ منابع در bots/tarot/STYLE.md.
// سه تغییرِ ساختاری:
//   ۱) افشا = تیزرِ کوتاه per کارت (چند کلمه، درباره‌ی خودِ کارت) تا تعلیق حفظ شود
//   ۲) متنِ نهایی با **سرخطِ جواب** شروع می‌شود، نه با روایت
//   ۳) بازخورد از وسطِ خوانش به آخرِ کار منتقل شد و مقیاسِ ۱ تا ۵ گرفت
// ✅ از v3.7.0 برای **همه‌ی کاربران** باز است. مسیرِ مرحله‌ای طبق بند ۲ج-۲ ریشه کامل طی شد:
// از v3.5.0 تا v3.6.7 فقط اکانتِ ادمین آن را می‌دید. در این فاصله ۱۶ دورِ آزمایشگاه روی
// ~۳۰۰ فال اجرا شد (جمله‌ی بی‌لنگر ۲۴٪ → ۱۸٪، ایرادِ سخت به ~۱ از ۲۷ رسید و دسته‌ی
// غالبش از بین رفت)، و در آخر مالک دستی تست کرد و تأیید کرد (۱۴۰۵/۰۵/۲۷).
// Rollback فوری و بدونِ فکر: `READING_V4 = false` → دقیقاً به خوانشِ v3 برمی‌گردد
// (پرامپت، افشا، بازخورد، همه). مسیرِ v3 عمداً هنوز پاک نشده — بندِ ۹/۰ ریشه می‌گوید
// کدِ رول‌بک بعد از باز شدن پاک می‌شود، ولی بندِ ۲ج/۸ رول‌بکِ یک‌خطی را واجب می‌داند؛
// پس حذفِ v3 یک PR جداست، بعد از اینکه این لانچ چند روز پایدار ماند.
const READING_V4 = true;
const READING_V4_ADMIN_ONLY = false;
const v4For = (uid) => READING_V4 && (!READING_V4_ADMIN_ONLY || isTester(uid));
// نشانه‌ی ابتدای هر بخشِ متنِ نهایی. عمداً در **کد** است نه در پرامپت: مدل اگر آزاد
// باشد هر بار سلیقه‌ای ایموجی می‌پاشد؛ این‌طوری ثابت، کم و قابلِ‌تغییر از یک نقطه است.
// (خوانش‌های واقعیِ انسانی اصلاً ایموجی ندارند؛ این یک انتخابِ آگاهانه‌ی محصولی است تا
// متنِ بلندِ تلگرام بخش‌بندیِ چشمی داشته باشد و دیوارِ متن نباشد.)
// نشانه‌های بخش (`SECT`)، برداشتنِ برچسبِ کارت (`stripCardLabel`)، فیلترِ خط تیره
// (`noDash`) و فاصله‌ی زمانیِ فارسی (`agoFa`) همگی به `reading-core.js` منتقل شدند تا
// آزمایشگاهِ آفلاین همان‌ها را اجرا کند. رفتارشان ذره‌ای عوض نشده.

// 🎙 سؤالِ صوتی مستقیم به مدل (v3.4.0): تا قبل از این، ویس **دو** فراخوانی می‌شد — یکی
// رونویسی و یکی خوانش. حالا خودِ فایلِ صوتی کنارِ پرامپت به Gemini می‌رود و کلِ کار **یک**
// فراخوانی است. مدل متنِ سؤال را هم در `question_text` برمی‌گرداند تا رکوردِ فال مثل قبل
// سؤال را داشته باشد (پشتیبانی/دیباگ) بدونِ اینکه فراخوانیِ دومی لازم باشد.
// Rollback یک‌خطی: false → برمی‌گردیم به مسیرِ رونویسی، ولی **همچنان بعد از پرداخت**
// (قاعده‌ی هزینه پایین‌تر مستقل از این پرچم است و با آن رول‌بک نمی‌شود).
const AUDIO_DIRECT_ENABLED = true;
const toneV2For = (uid) => READING_TONE_V2 && (!READING_TONE_V2_ADMIN_ONLY || isTester(uid));

// ───────────────────────────────────────────────────────────────────────────
// 🧭 UX v2 (v3.8.0) — بازطراحیِ بنیادیِ سفرِ کاربر
// ───────────────────────────────────────────────────────────────────────────
// یک پرچم برای **کلِ** بازطراحی، نه یکی per تغییر. دلیل: این ده تغییر به هم وابسته‌اند
// (ماهِ تولد ورودیِ کارتِ روز است، الماس واحدِ کاتالوگِ جدید است، حذفِ موضوع یعنی کاتالوگِ
// جدید). اگر هرکدام پرچمِ خودش را داشت، ترکیب‌های نیمه‌روشن ممکن می‌شد که هیچ‌وقت تست
// نشده‌اند. یک پرچم یعنی دقیقاً دو حالتِ ممکن: دنیای قدیم، یا دنیای نو.
//
// چه چیزی عوض می‌شود:
//   ۱) آنبوردینگ: «ذهنت درگیر چیه؟» → «ماه تولدت چیه؟»
//   ۲) کاتالوگ: موضوع‌ها حذف؛ فقط سه فال بر اساسِ **اندازه** (۳/۵/۱۰ کارت)
//   ۳) کاربر **همه‌ی** کارت‌ها را خودش می‌چیند (نه سه‌تا و بقیه خودکار)
//   ۴) کیف پول → الماس‌فروشی با سه بسته
//   ۵) هدیه‌ها و پاداش‌ها به الماس
//   ۶) کارتِ روز: انتخابِ کارت توسط کاربر + متنِ از-پیش-نوشته (بدونِ LLM)
//
// ✅ **از v3.25.0 (۱۴۰۵/۰۵/۳۰) برای همه‌ی کاربران باز است.** مسیرِ بند ۲ج-۲ ریشه کامل طی
// شد: از v3.8.0 تا v3.24.0 فقط ادمین و تسترها، و باز کردنش در همین PR با مهاجرتِ موجودی
// و پیامِ اطلاع‌رسانی همراه بود. پیش‌نیازهایی که **قبل** از این خط اجرا شدند:
//   ۱) `tools/coin-migration-tarot.mjs --apply` — موجودیِ تومانی به الماس تبدیل شد،
//      وگرنه کاربر عددی می‌دید که با کیفش نمی‌خواند.
//   ۲) پنجره‌ی یک‌باره‌ی مهاجرتِ کیبورد (`KB_V2_EPOCH` در `ensureMenu`) — وگرنه کاربرِ
//      فعلی کیبوردِ تومانیِ قدیمی را نگه می‌داشت و «کارت شانس» را اصلاً نمی‌دید.
// Rollback فوری: `UX_V2 = false` → همه‌چیز دقیقاً به سفرِ قبلی برمی‌گردد. ستونِ
// جدیدِ `users.birth_month` و جدولِ `daily_log` می‌مانند ولی خوانده نمی‌شوند، پس
// مهاجرتِ برگشتی لازم نیست (بند ۲ج/۱: فقط افزایشی). ستونِ `coins` عمداً ساخته نشد:
// موجودی همچنان تومان است و الماس فقط واحدِ نمایش (بند ۹ ریشه، منبعِ حقیقتِ پول یکی است).
const UX_V2 = true;
const UX_V2_ADMIN_ONLY = false;
const uxV2For = (uid) => UX_V2 && (!UX_V2_ADMIN_ONLY || isTester(uid));

// ───────────────────────────────────────────────────────────────────────────
// 🪙 اقتصادِ سکه (v3.0.0)
// ───────────────────────────────────────────────────────────────────────────
// موجودیِ داخلی **همچنان تومان** است (منبعِ حقیقتِ پول عوض نمی‌شود؛ بند ۹ ریشه). الماس فقط
// واحدِ نمایش است: هر کارت = ۱ الماس = COIN_VALUE تومان. چون قانونِ قیمت از قبل «هر کارت
// ۱۰٬۰۰۰ تومان» بود، `coins = spread.size` بدونِ هیچ عددِ جدیدی درمی‌آید و هیچ قیمتی دو
// جا نوشته نمی‌شود. هدیه‌ی خوش‌آمدِ ۳۰٬۰۰۰ هم دقیقاً ۳ الماس است، یعنی یک فالِ کامل.
//
// ⚠️ فعلاً فقط ادمین. باز کردن برای همه = `COIN_ECONOMY_ADMIN_ONLY = false`.
// Rollback فوری: `COIN_ECONOMY = false` → کاتالوگ، کیف‌پول و همه‌ی متن‌ها به تومان برمی‌گردند
// (الماس هیچ ستونی در DB ندارد، پس چیزی برای مهاجرتِ برگشتی وجود ندارد).
// ⏸ **پارک‌شده (۱۴۰۵/۰۵/۲۴ — تصمیمِ مالک).** کدش عمداً حذف نشد چون به‌زودی دوباره
// رویش کار می‌کنیم؛ فقط پرچم خاموش است، پس حتی ادمین هم دنیای تومانیِ قبلی را می‌بیند.
// چون کاتالوگِ نسل دوم (عشق‌محورِ تقابلی) هم از همین helper شاخه می‌گیرد، خاموش‌کردنِ
// این یک پرچم **هر دو** را با هم به حالتِ قبل برمی‌گرداند.
// روشن‌کردنِ دوباره: `COIN_ECONOMY = true` (+ bump نسخه). **آن موقع فقط «الماس» می‌ماند و
// «فال‌گیر» کلاً حذف است** — آزمایشِ نامِ واحد منحل شد.
const COIN_ECONOMY = false;
const COIN_ECONOMY_ADMIN_ONLY = true;
const COIN_VALUE = 10_000;   // ارزشِ داخلیِ هر الماس به تومان (= قیمتِ یک کارت)
// UX v2 ذاتاً الماسی است (کاتالوگ و الماس‌فروشی هر دو به الماس حرف می‌زنند)، پس پرچمِ
// جداگانه‌ی الماس را هم روشن می‌کند. پرچمِ قدیم برای دنیای قبل سرِ جایش می‌ماند.
const coinsOn = (uid) => uxV2For(uid) || (COIN_ECONOMY && (!COIN_ECONOMY_ADMIN_ONLY || isTester(uid)));

// آزمایشِ نامِ واحد (الماس در برابر فال‌گیر) **منحل شد**: «فال‌گیر» در عمل بد جا می‌افتاد.
// واحد از این به بعد فقط «الماس 🪙» است. کلید را نگه می‌داریم تا بتوانیم آزمایش را در DB
// صراحتاً stop کنیم (وگرنه در داشبورد «در حال اجرا»ی دروغین می‌ماند).
const AB_COIN_NAME = 'coin_name';
// آبجکتِ ارز که به همه‌ی متن‌های locale پاس داده می‌شود. `on:false` یعنی «دقیقاً مثل قبل، تومان».
const TOMAN_CUR = { on: false, value: 1, name: 'تومان', emoji: '' };
function curOf(uid) {
  if (!coinsOn(uid)) return TOMAN_CUR;
  return { on: true, value: COIN_VALUE, name: L.coinUnit.name, emoji: L.coinUnit.emoji };
}
// سه بسته‌ی خریدِ الماس (تصمیمِ مالک). قیمت‌ها **تومانِ واقعی**اند؛ `coins × COIN_VALUE` همان
// اعتباری است که به موجودیِ کاربر اضافه می‌شود، یعنی هر بسته ذاتاً تخفیف‌دار است و بسته‌ی بزرگ‌تر
// هر الماس را ارزان‌تر می‌کند (نردبانِ ARPU). هیچ مرحله‌ی «چقدر شارژ کنم؟» در کار نیست.
// 🎨 رنگِ بسته‌ها: «بسته ویژه» (وسط) سبز است تا مسیرِ پیشنهادی برجسته شود و «بسته‌ی
// جادویی» آبی، تا هر دو بسته‌ی بالای نردبان از بسته‌ی پایه متمایز باشند (تصمیمِ صریحِ
// مالک). «بسته‌ی معمولی» عمداً بی‌رنگ می‌ماند و رنگِ پیش‌فرضِ کلاینت را می‌گیرد.
// ⚠️ Bot API 9.4 فقط **سه** رنگ دارد: success (سبز)، primary (آبی)،
// danger (قرمز). **بنفش وجود ندارد** — مالک بنفش خواست و نزدیک‌ترین رنگِ متمایزِ
// باقی‌مانده آبی است، چون سبز روی «بسته ویژه» نشسته و قرمز معنیِ خطر می‌دهد.
const PACK_STYLE = { gold: 'success', magic: 'primary' };
const COIN_PACKAGES = [
  // ⚠️ قیمت‌های UX v2 (تصمیمِ مالک ۱۴۰۵/۰۵/۲۷). این یک **کاهشِ قیمتِ واقعی** است، نه
  // فقط تغییرِ بسته‌بندی: هر الماس از ۱۰٬۰۰۰ تومان به ۳٬۰۰۰ / ۲٬۰۰۰ / ۱٬۵۰۰ می‌رسد، یعنی
  // فالِ سه‌کارتی از ۳۰٬۰۰۰ به ۹٬۰۰۰ تا ۴٬۵۰۰ تومان. قبل از باز کردن برای کاربرِ واقعی
  // این عدد باید دوباره دیده شود.
  { key: 'basic',  fa: 'بسته‌ی معمولی', emoji: '🥉', coins: 10,  toman: 30_000 },
  // ایموجیِ بسته‌ی وسط 💠 است و عمداً **خودِ 💎 نیست**: در همان دکمه ایموجیِ واحد هم
  // می‌آید و دو 💎 پشت‌سرهم بد خوانده می‌شود. نامش از «بسته‌ی الماسی» به «بسته ویژه»
  // رفت (تصمیمِ مالک): «الماسی» با واحدِ الماس اشتباه گرفته می‌شد، انگار فقط این یکی
  // بسته الماس می‌دهد. کلیدِ `gold` عوض نشد چون در `payments.package_key` کاربرانِ
  // واقعی نشسته و بند ۲ج/۱ تغییرِ معنیِ داده‌ی موجود را ممنوع کرده.
  { key: 'gold',   fa: 'بسته ویژه', emoji: '💠', coins: 30,  toman: 60_000 },
  { key: 'magic',  fa: 'بسته‌ی جادویی', emoji: '🪄', coins: 100, toman: 150_000 },
];
const PACKAGE_BY_KEY = Object.fromEntries(COIN_PACKAGES.map(p => [p.key, p]));

const CARD_NUMBER = '6219861904145405';
const CARD_OWNER  = 'علیرضا اولیا — بلوبانک';
const CARD_RECIPIENT_NAME = 'علیرضا اولیا';   // نامِ گیرنده (تطبیق در ایجنتِ رسید)
const CARD_DEST_LAST4     = '5405';            // چهار رقمِ آخرِ کارتِ مقصد (تطبیق در ایجنتِ رسید)

// ایجنتِ رسیدِ کارت‌به‌کارت (Gemini Flash از طریق OpenRouter): auto-approve با شبکه‌ی ایمنیِ
// برگشت + بی‌اعتمادی. کلیدِ خاموشیِ سراسری (env RECEIPT_AI_AUTO_APPROVE=false → همه‌ی رسیدها
// دستی به ادمین می‌روند، بدون تصمیمِ خودکار). پیش‌فرض: روشن.
const RECEIPT_AI_AUTO_APPROVE = (process.env.RECEIPT_AI_AUTO_APPROVE ?? 'true').toLowerCase() !== 'false';
const RECEIPT_MODEL = FLASH;
// دکمه‌ی کپیِ شماره کارت (Telegram copy_text — کلیک = کپی به کلیپ‌بورد). قاعده‌ی سراسری:
// هر پیامِ پرداختِ کارت‌به‌کارت که شماره کارت را نشان می‌دهد باید این دکمه را زیرش داشته باشد.
const cardCopyRow = () => [{ text: '📋 کپی شماره کارت', copy_text: { text: CARD_NUMBER } }];

// 🎁 هدیه‌ی خوش‌آمد (v2.0.0): دقیقاً بهای یک فالِ کاملِ سه‌کارتی، تا کاربرِ جدید **قبل از
// هر پی‌والی** ارزشِ واقعیِ محصول را ببیند (بند ۱۰ ریشه: اول ارزش، بعد پول). write-once با
// ستونِ users.welcome_bonus_at — ری‌استارت/چندبار /start دوباره هدیه نمی‌دهد.
const WELCOME_BONUS    = 30_000;
const QUICK_AMOUNTS    = [50_000, 100_000, 200_000];
const MIN_RECHARGE     = 10_000;  // کف‌گیرِ اشتباهِ تایپی (پایین‌تر از ارزان‌ترین فال)
// هدیه‌ی شارژ (ARPU بالاتر): فقط از ۲۰۰k به بالا، تا نردبان قیمت ساده و قابل‌فهم بماند
const RECHARGE_BONUS   = [{ min: 200_000, bonus: 50_000 }];
const bonusFor = (amount) => RECHARGE_BONUS.find(t => amount >= t.min)?.bonus || 0;
const STREAK_EVERY     = 7;       // هر ۷ روز پیاپیِ کارت روز → جایزه
const STREAK_REWARD    = 5_000;
const REFERRAL_BONUS   = 10_000;
// در اقتصادِ سکه هدیه‌ی دعوت **هم‌اندازه‌ی هدیه‌ی خوش‌آمد** است (۳ سکه = یک فالِ کامل):
// یعنی هر دعوتِ موفق دقیقاً یک فال به دعوت‌کننده می‌دهد، که پیامِ ساده‌ای برای گفتن دارد.
// UX v2: پاداشِ دعوت ۱۰ الماس برای **دعوت‌کننده**. دعوت‌شده فقط همان هدیه‌ی خوش‌آمد را
// می‌گیرد و پاداشِ اضافه ندارد (تصمیمِ صریحِ مالک).
const REFERRAL_BONUS_COINS = 3;
const REFERRAL_BONUS_COINS_V2 = 10;
const referralBonusFor = (uid) => (uxV2For(uid) ? REFERRAL_BONUS_COINS_V2 * COIN_VALUE
  : coinsOn(uid) ? REFERRAL_BONUS_COINS * COIN_VALUE : REFERRAL_BONUS);
// هدیه‌ی خوش‌آمد: ۵ الماس در UX v2 (به‌جای ۳۰٬۰۰۰ تومان که ۳ الماس بود)
const WELCOME_BONUS_COINS_V2 = 5;
const welcomeBonusFor = (uid) => (uxV2For(uid) ? WELCOME_BONUS_COINS_V2 * COIN_VALUE : WELCOME_BONUS);
// جایزه‌ی کارتِ روز: ۱ الماس، روزی یک بار. اهرمِ عادتِ روزانه (بند ۱۰ ریشه: قلابِ بازگشت
// باید در خودِ محصول باشد نه فقط در پوش).

// ───────────────────────────────────────────────────────────────────────────
// 🍀 کارت شانس — الماسِ رایگانِ روزانه با امیدِ ریاضیِ **دقیقاً ۱ الماس**
// ───────────────────────────────────────────────────────────────────────────
// چرا این شکل و نه «هر روز یک الماسِ رایگان»: تصمیمِ صریحِ مالک. هزینه‌ی روزانه برای ما
// یکسان می‌ماند ولی تجربه از «دریافتِ خودکار» به یک **آیین** تبدیل می‌شود، و آیین همان
// چیزی است که کاربر را برمی‌گرداند (بند ۱۰ ریشه، قلاب بازگشت).
//
// ریاضیِ انتخاب بدونِ جایگذاری (هندسی/هایپرژئومتریک):
//   امیدِ ریاضی = LUCKY_PICKS × LUCKY_COINS / GRID_SIZE
//   با گریدِ ۲۴تایی و ۳ انتخاب:  E = 3 × K / 24 = K / 8
//   پس برای E = ۱ الماس باید **K = ۸** کارت الماس داشته باشند (هر کدام ۱ الماس).
// توزیعِ نتیجه با همین اعداد: صفر الماس ۲۷.۷٪ · یک ۴۷.۴٪ · دو ۲۲.۱٪ · سه ۲.۸٪.
// یعنی حداکثرِ روزانه ۳ الماس است (خواسته‌ی مالک) و میانگین دقیقاً ۱ الماس.
// تستِ CI همین تساوی را اجرا می‌کند، پس دست‌کاریِ هر عدد بدونِ دیدنِ اثرش ممکن نیست.
const LUCKY_PICKS = 3;                    // چند کارت انتخاب می‌کند
const LUCKY_COINS = 8;                    // پشتِ چند کارت از GRID_SIZE الماس هست
const LUCKY_COIN_VALUE = 1 * COIN_VALUE;  // ارزشِ هر کارتِ الماس‌دار
// 🎁 کفِ الماسِ **دستِ اولِ عمرِ هر کاربر** (تصمیمِ صریحِ مالک). فقط همان یک دست؛ از
// دستِ دوم به بعد هیچ دخالتی نیست. جزئیات و هزینه‌اش کنارِ `forcedHit` پایین.
const LUCKY_FIRST_MIN = 2;
// تخفیفِ اولین پرداخت (v2.0.0): ۲۰٪، **فقط روی فالِ رزروشده‌ی همان لحظه** و بدون سقف.
// دیگر کدی کپی نمی‌شود: دکمه‌ی «تخفیف می‌خوام» یک پیامِ کوتاهِ اطلاع‌رسانی می‌دهد و بلافاصله
// خودِ فاکتورِ تخفیف‌خورده را می‌فرستد. شارژِ کیف‌پول عمداً تخفیف نمی‌گیرد (فرایندِ جداست).
// کدِ `firstCodeFor(uid)` فقط دفترِ حسابداریِ «این کاربر تخفیفش را خرج کرد» است.
const FIRST_RECHARGE_DISCOUNT = { percent: 20 };
const MILESTONE_DAYS   = 14;
const PUSH_COOLDOWN_S  = 7 * 24 * 3600; // حداکثر یک پوش پیشگیرانه در هفته
// REVERSAL_PROB و GRID_SIZE در reading-core.js اند (موتورِ دک آن‌جاست).
const USER_PICKS       = 3;  // حداکثر تعداد انتخاب کاربر از گرید (فال کوچک‌تر = به تعداد خودش)

const PACE_S = 1200, PACE_M = 2500, PACE_REVEAL = 3500;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

/* ===== 2) Database ===== */
mkdirSync('./data', { recursive: true });
const db = new Database(`./data/bot-${LOCALE}.db`);
db.pragma('journal_mode = WAL');
db.pragma('synchronous = NORMAL');
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    telegram_id       INTEGER PRIMARY KEY,
    name              TEXT    NOT NULL DEFAULT '',
    username          TEXT    NOT NULL DEFAULT '',
    state             TEXT    NOT NULL DEFAULT 'new',
    balance           INTEGER NOT NULL DEFAULT 0,
    focus_area        TEXT    NOT NULL DEFAULT '',
    last_daily_date   TEXT    NOT NULL DEFAULT '',
    session_json      TEXT    NOT NULL DEFAULT '',
    next_milestone_at INTEGER,
    last_push_at      INTEGER NOT NULL DEFAULT 0,
    referred_by       INTEGER,
    welcomed          INTEGER NOT NULL DEFAULT 0,
    created_at        INTEGER NOT NULL DEFAULT (unixepoch()),
    last_seen         INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS readings (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id     INTEGER NOT NULL,
    type        TEXT    NOT NULL,
    price       INTEGER NOT NULL,
    focus_area  TEXT    NOT NULL DEFAULT '',
    question    TEXT    NOT NULL DEFAULT '',
    seed        TEXT    NOT NULL DEFAULT '',
    cards_json  TEXT    NOT NULL DEFAULT '',
    llm_json    TEXT    NOT NULL DEFAULT '',
    summary     TEXT    NOT NULL DEFAULT '',
    feedback    TEXT    NOT NULL DEFAULT '',
    status      TEXT    NOT NULL DEFAULT 'pending_payment',
    created_at  INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS payments (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id          INTEGER NOT NULL,
    amount           INTEGER NOT NULL DEFAULT 0,
    status           TEXT    NOT NULL DEFAULT 'pending',
    step             TEXT,
    receipt_file_id  TEXT,
    admin_message_id INTEGER,
    discount_code_id INTEGER,
    original_amount  INTEGER,
    created_at       INTEGER NOT NULL DEFAULT (unixepoch()),
    updated_at       INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS discount_codes (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    code              TEXT    NOT NULL UNIQUE,
    discount_percent  INTEGER NOT NULL,
    expires_at        INTEGER,
    max_uses_per_user INTEGER NOT NULL DEFAULT 1,
    only_user_id      INTEGER,
    is_active         INTEGER NOT NULL DEFAULT 1,
    total_uses        INTEGER NOT NULL DEFAULT 0,
    created_by        INTEGER NOT NULL,
    created_at        INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS discount_uses (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    code_id         INTEGER NOT NULL,
    user_id         INTEGER NOT NULL,
    payment_id      INTEGER,
    discount_amount INTEGER NOT NULL DEFAULT 0,
    used_at         INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS referrals (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    referrer_id INTEGER NOT NULL,
    referee_id  INTEGER NOT NULL UNIQUE,
    rewarded    INTEGER NOT NULL DEFAULT 0,
    created_at  INTEGER NOT NULL DEFAULT (unixepoch())
  );
  CREATE TABLE IF NOT EXISTS card_files (
    card_key   TEXT PRIMARY KEY,
    file_id    TEXT NOT NULL,
    updated_at INTEGER NOT NULL DEFAULT (unixepoch())
  );
  -- 🎴 دفترِ کارتِ روز (UX v2). یک ردیف per کاربر per روز، و همین یک جدول **هر دو**
  -- قاعده‌ی عدم‌تکرار را جواب می‌دهد: کارت‌های ۷ روزِ اخیر (فیلترِ date) و نسخه‌هایی که
  -- کاربر از یک کارتِ مشخص دیده (فیلترِ card_key). کلیدِ اصلی (user_id, date) خودش
  -- گاردِ «روزی یک بار» است، پس دوبار-تپ نمی‌تواند دو ردیف بسازد.
  CREATE TABLE IF NOT EXISTS daily_log (
    user_id    INTEGER NOT NULL,
    date       TEXT    NOT NULL,
    card_key   TEXT    NOT NULL,
    reversed   INTEGER NOT NULL DEFAULT 0,
    variant    INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL DEFAULT (unixepoch()),
    PRIMARY KEY (user_id, date)
  );
  CREATE INDEX IF NOT EXISTS idx_daily_log_user_card ON daily_log(user_id, card_key);
  CREATE TABLE IF NOT EXISTS daily_texts (
    card_key   TEXT    NOT NULL,
    reversed   INTEGER NOT NULL,
    focus      TEXT    NOT NULL,
    text       TEXT    NOT NULL,
    created_at INTEGER NOT NULL DEFAULT (unixepoch()),
    PRIMARY KEY (card_key, reversed, focus)
  );
`);
