// ── UX v2 (v3.8.0) — همه افزایشی، همه با پیش‌فرضی که رفتارِ قدیم را عوض نمی‌کند ──
// ماهِ تولد (۱..۱۲ شمسی، ۰ = نپرسیده). جایگزینِ `focus_area` در آنبوردینگ شد، ولی
