// آنالیتیکس مشترک: جدول events + ستون‌های اتریبیوشن first_source/first_payload روی users
ensureAnalytics(db);
// A/B تست: جدول‌های experiments/ab_exposures (config توسط داشبورد نوشته می‌شود؛ ربات فقط می‌خواند)
ensureAb(db);

// 🅰️/🅱️ آزمایشِ «ترتیبِ دو پیامِ آنبوردینگ» (v2.8.0).
// هر کاربرِ جدید دقیقاً همان دو بلوکِ محتوایی را می‌بیند و تنها متغیر **ترتیب** است:
//   control    → پیامِ اول «تجربه»، پیامِ بعد از نام «آمار»
//   stat_first → برعکس
// سؤال: کاربرِ تازه‌وارد اول باید بداند این‌جا چه چیزی هست، یا اول باید دلیلی برای باور
// کردن داشته باشد؟ چون هر دو بلوک در هر دو نسخه دیده می‌شوند، تفاوتِ نتیجه فقط از ترتیب است.
//
// معمولاً آزمایش را داشبورد می‌سازد و ربات فقط می‌خواند. این‌جا **seedِ یک‌باره** است چون
// کمپین همین حالا در جریان است و ترافیکِ کمپین گران‌ترین ترافیکِ ماست؛ کاربری که قبل از
// روشن‌شدنِ آزمایش بیاید برای همیشه از نمونه بیرون می‌ماند. `INSERT OR IGNORE` است، پس
// داشبورد همچنان تنها مرجعِ کنترل می‌ماند (هر stop/kill/تغییرِ وزن از آن‌جا باقی می‌ماند).
const AB_INTRO_ORDER = 'intro_order';
try {
  db.prepare(`
    INSERT OR IGNORE INTO experiments
      (key, name, hypothesis, mode, metric_kind, variants_json, status,
       primary_metric, guardrails_json, started_at)
    VALUES (?,?,?,'split','rate',?,'running',?,?,unixepoch())
  `).run(
    AB_INTRO_ORDER,
    'ترتیبِ دو پیامِ آنبوردینگ (تجربه یا آمار، کدام اول)',
    'اگر شاهدِ اجتماعی (۸۶٪) را قبل از وعده‌ی تجربه نشان دهیم، کاربرِ بیشتری تا تحویلِ فال جلو می‌رود.',
    JSON.stringify([{ key: 'control', weight: 50 }, { key: 'stat_first', weight: 50 }]),
    EVENTS.PRODUCT_DELIVERED,
    JSON.stringify([]),
  );
  // آزمایشِ نامِ واحدِ پول منحل شد (تصمیمِ مالک: «فال‌گیر» بد جا می‌افتاد). صراحتاً stop
  // می‌شود تا در داشبورد «در حال اجرا»ی دروغین نماند. idempotent است.
  db.prepare(`
    UPDATE experiments SET status='stopped', stopped_at=unixepoch(),
      decision='منحل — واحد فقط «الماس» می‌ماند؛ «فال‌گیر» حذف شد'
    WHERE key=? AND status<>'stopped'
  `).run(AB_COIN_NAME);
  // آزمایشِ قبلی (کلیدواژه‌ی هوش مصنوعی) با تصمیمِ مالک متوقف شد: موضع‌گیریِ هوش مصنوعی
  // بیرون از فلو و روی بنرِ تبلیغاتی تست می‌شود، نه این‌جا. صراحتاً stop می‌کنیم تا در
  // داشبورد «در حال اجرا»ی دروغین نماند. یک‌باره است (شرطِ status آن را idempotent می‌کند).
  db.prepare(`
    UPDATE experiments SET status='stopped', stopped_at=unixepoch(),
      decision='inconclusive — متوقف پیش از نمونه‌ی معنادار؛ فرضیه‌ی هوش مصنوعی بیرون از فلو (بنر تبلیغاتی) تست می‌شود'
    WHERE key='gate_intro_ai' AND status<>'stopped'
  `).run();
} catch (e) { logErr('ab seed:', e.message); } // آزمایش هرگز نباید بوتِ ربات را بشکند

const stmts = {
  upsertUser: db.prepare(`
    INSERT INTO users (telegram_id, name, username) VALUES (?, ?, ?)
    ON CONFLICT(telegram_id) DO UPDATE SET name=excluded.name, username=excluded.username, last_seen=unixepoch()
  `),
  getUser:    db.prepare('SELECT * FROM users WHERE telegram_id=?'),
  setState:   db.prepare('UPDATE users SET state=?, last_seen=unixepoch() WHERE telegram_id=?'),
  setFocus:   db.prepare('UPDATE users SET focus_area=?, focus_asked_at=unixepoch() WHERE telegram_id=?'),
  // UX v2: ماهِ تولد. `focus_asked_at` هم مهر می‌خورد چون همین سؤال جای آن یکی نشسته و
  // تحلیل‌های «آنبوردینگ تمام شد» نباید بشکنند (بند ۲ج/۳: فقط اضافه کن، معنا را عوض نکن).
  setBirthMonth: db.prepare('UPDATE users SET birth_month=?, focus_asked_at=unixepoch() WHERE telegram_id=?'),
  setDisplayName: db.prepare('UPDATE users SET display_name=? WHERE telegram_id=?'),
  setWelcomed: db.prepare('UPDATE users SET welcomed=1 WHERE telegram_id=?'),
  // گاردِ اتمیک داخلِ خودِ UPDATE: فقط وقتی هنوز NULL است می‌نویسد، پس دوبار-تپ اثری ندارد
  claimGate: db.prepare('UPDATE users SET joined_gate_at=unixepoch() WHERE telegram_id=? AND joined_gate_at IS NULL'),
  setSession: db.prepare('UPDATE users SET session_json=? WHERE telegram_id=?'),
  setDaily:   db.prepare('UPDATE users SET last_daily_date=?, daily_streak=? WHERE telegram_id=?'),
  // 🎴 دفترِ کارتِ روز (UX v2). یک جدول، هر دو قاعده‌ی عدم‌تکرار.
  // ⚠️ معیار **«بارِ فال‌گیری»** است نه «روز» (تصمیمِ صریحِ مالک): کاربر هر روز فال
  // نمی‌گیرد، و با معیارِ روز کسی که هفته‌ای یک بار می‌آید عملاً هیچ محافظتی نداشت.
  // یک ردیف per (کاربر، روز) داریم، پس ORDER BY date DESC دقیقاً «آخرین N بار» است.
  recentDailyDraws: db.prepare('SELECT card_key FROM daily_log WHERE user_id=? ORDER BY date DESC LIMIT ?'),
  seenDailyVariants: db.prepare('SELECT variant FROM daily_log WHERE user_id=? AND card_key=?'),
  // OR IGNORE: کلیدِ (user_id, date) گاردِ «روزی یک بار» است، پس دوبار-تپ ردیفِ دوم نمی‌سازد
  logDaily: db.prepare('INSERT OR IGNORE INTO daily_log (user_id, date, card_key, reversed, variant) VALUES (?,?,?,?,?)'),
  setHafez:   db.prepare('UPDATE users SET last_hafez_date=? WHERE telegram_id=?'),
  setEstekhare: db.prepare('UPDATE users SET estekhare_date=?, estekhare_count=? WHERE telegram_id=?'),
  setQuiz:    db.prepare('UPDATE users SET last_quiz_date=? WHERE telegram_id=?'),
  setCoffee:  db.prepare('UPDATE users SET last_coffee_date=? WHERE telegram_id=?'),
  readingsByStatus: db.prepare('SELECT status, COUNT(*) AS c FROM readings GROUP BY status'),
  setMilestone: db.prepare('UPDATE users SET next_milestone_at=? WHERE telegram_id=?'),
  setPush:    db.prepare('UPDATE users SET last_push_at=unixepoch(), next_milestone_at=NULL WHERE telegram_id=?'),
  // هدیه‌ی خوش‌آمد: گاردِ write-once داخل خودِ UPDATE (changes=0 یعنی قبلاً گرفته)
  claimWelcomeBonus: db.prepare('UPDATE users SET welcome_bonus_at=unixepoch() WHERE telegram_id=? AND welcome_bonus_at IS NULL'),
  setDailyReminderOff: db.prepare('UPDATE users SET daily_reminder_off=1 WHERE telegram_id=?'),
  // 🍀 کارت شانس. `claimLucky` گاردِ اتمیکِ «روزی یک بار» است: شرطِ روز داخلِ خودِ UPDATE
  // نشسته، پس دو تپِ هم‌زمان فقط یک بار changes=1 می‌دهد (همان الگوی claimWelcomeBonus).
  claimLucky: db.prepare("UPDATE users SET lucky_date=? WHERE telegram_id=? AND COALESCE(lucky_date,'') <> ?"),
  setLuckyReminder: db.prepare('UPDATE users SET lucky_reminder_on=? WHERE telegram_id=?'),
  setLuckyHand: db.prepare('UPDATE users SET lucky_hand=? WHERE telegram_id=?'),
  bumpLuckyHands: db.prepare('UPDATE users SET lucky_hands = lucky_hands + 1 WHERE telegram_id=?'),
  setLuckyReminded: db.prepare('UPDATE users SET last_lucky_reminder_at=unixepoch() WHERE telegram_id=?'),
  dueLuckyReminder: db.prepare(`
    SELECT telegram_id FROM users
     WHERE welcomed=1 AND lucky_reminder_on=1
       AND COALESCE(lucky_date,'') <> ?
       AND (last_lucky_reminder_at IS NULL OR last_lucky_reminder_at < unixepoch()-64800)
     LIMIT 200`),
  // اصلاحِ فاکتور به مبلغِ واقعاً پرداخت‌شده (پرداختِ کمتر). original_amount هم برابر می‌شود
  // تا اعتبارِ approvePayment دقیقاً همان چیزی باشد که کاربر داده، نه بیشتر.
  adjustPaymentAmount: db.prepare(
    "UPDATE payments SET amount=?, original_amount=?, adjust_note=?, updated_at=unixepoch() WHERE id=? AND status IN ('pending','waiting_review')"),
  // بسته‌ی الماس: original_amount را claimAmount گذاشته (ارزشِ الماس‌ها)، این‌جا فقط مبلغِ
  // پرداختیِ واقعی و کلیدِ بسته می‌نشیند. گاردِ step='receipt' یعنی بعد از نهایی‌شدنِ
  // فاکتور دیگر بسته عوض نمی‌شود.
  // دقیقاً هم‌شکلِ setPaymentDiscount: `original_amount` اعتباری است که داده می‌شود (ارزشِ
  // الماس‌های بسته، که claimAmount در amount گذاشته بود) و `amount` پولی است که کاربر واقعاً
  // می‌پردازد. COALESCE لازم است چون approvePayment از `original_amount || amount` می‌خواند؛
  // بدونِ آن، اعتبارِ بسته برابرِ مبلغِ پرداختی می‌شد و کاربر یک‌سومِ الماس‌هایش را می‌گرفت.
  setPaymentPackage: db.prepare(
    "UPDATE payments SET pkg=?, original_amount=COALESCE(original_amount, amount), amount=?, updated_at=unixepoch() WHERE id=? AND step='receipt' AND status='pending'"),
  setKbShown: db.prepare('UPDATE users SET kb_shown_at=unixepoch() WHERE telegram_id=?'),
  // پیشنهاددهنده: آخرین باری که کاربر هر نوع فال را **تحویل گرفته** (منبعِ جریمه‌ی تازگی)
  lastByType: db.prepare("SELECT type, MAX(created_at) AS last FROM readings WHERE user_id=? AND status='delivered' GROUP BY type"),
  // اقبال عمومی: چند بار هر نوع فال در کلِ ربات تحویل شده
  popByType: db.prepare("SELECT type, COUNT(*) AS c FROM readings WHERE status='delivered' GROUP BY type"),
  setReferredBy: db.prepare('UPDATE users SET referred_by=? WHERE telegram_id=?'),
  credit:     db.prepare('UPDATE users SET balance = balance + ? WHERE telegram_id=?'),
  deduct:     db.prepare('UPDATE users SET balance = balance - ? WHERE telegram_id=? AND balance >= ?'),
  dueMilestones: db.prepare(`
    SELECT telegram_id FROM users
    WHERE next_milestone_at IS NOT NULL AND next_milestone_at <= unixepoch()
      AND last_push_at < unixepoch() - ${PUSH_COOLDOWN_S}
    LIMIT 20
  `),

  insertReading: db.prepare(`INSERT INTO readings (user_id, type, price, focus_area, question, seed, cards_json, question_audio, question_audio_fmt) VALUES (?,?,?,?,?,?,?,?,?)`),
  // متنِ سؤال وقتی ویس بوده و مدل آن را در question_text برگردانده (رکورد برای پشتیبانی/دیباگ)
  setReadingQuestion: db.prepare('UPDATE readings SET question=? WHERE id=? AND question=?'),
  getReading:    db.prepare('SELECT * FROM readings WHERE id=?'),
  setReadingLlm: db.prepare('UPDATE readings SET llm_json=?, summary=? WHERE id=?'),
  setReadingStatus: db.prepare('UPDATE readings SET status=? WHERE id=?'),
  // ادعای اتمیکِ استیت — گاردِ دوبار-تپ روی دکمه‌ی اندازه. `setState` بی‌قید است و
  // دو تپِ سریع هر دو رد می‌شدند؛ این یکی فقط برای **اولین** تپ changes=1 می‌دهد.
  claimState: db.prepare('UPDATE users SET state=? WHERE telegram_id=? AND state<>?'),
  // کارت‌ها فقط **یک بار** روی یک فالِ پرداخت‌شده نوشته می‌شوند (شرطِ cards_json='').
  setReadingCards: db.prepare(`UPDATE readings SET seed=?, cards_json=?, focus_area=?, question=?, question_audio=?, question_audio_fmt=? WHERE id=? AND cards_json=''`),
  // فالِ پرداخت‌شده‌ای که کاربر هرگز کارت‌هایش را نکشید (کهنه‌تر از یک شبانه‌روز).
  setReadingFeedback: db.prepare('UPDATE readings SET feedback=? WHERE id=?'),
  lastDelivered: db.prepare("SELECT * FROM readings WHERE user_id=? AND status='delivered' ORDER BY id DESC LIMIT ?"),
  countReadingsToday: db.prepare('SELECT COUNT(*) AS c FROM readings WHERE user_id=? AND created_at >= unixepoch()-86400'),
  countDelivered: db.prepare("SELECT COUNT(*) AS c FROM readings WHERE user_id=? AND status='delivered'"),
  countPaidDelivered: db.prepare("SELECT COUNT(*) AS c FROM readings WHERE user_id=? AND status='delivered' AND price>0"),
  readingsByType: db.prepare("SELECT type, COUNT(*) AS c, COALESCE(SUM(price),0) AS s FROM readings WHERE status='delivered' GROUP BY type"),

  insertPayment: db.prepare("INSERT INTO payments (user_id, amount, step) VALUES (?, 0, 'amount')"),
  getPayment:    db.prepare('SELECT * FROM payments WHERE id=?'),
  setPaymentAmount:  db.prepare("UPDATE payments SET amount=?, step=?, updated_at=unixepoch() WHERE id=?"),
  // ادعای اتمیک مبلغ: فقط اگر هنوز در مرحله‌ی «amount» است (ضد دابل‌تپِ دو مبلغِ متفاوت — دکمه یا متن)
  claimAmount: db.prepare("UPDATE payments SET amount=?, step='receipt', updated_at=unixepoch() WHERE id=? AND step='amount' AND status='pending'"),
  setPaymentStatus:  db.prepare('UPDATE payments SET status=?, updated_at=unixepoch() WHERE id=?'),
  setPaymentReceipt: db.prepare('UPDATE payments SET receipt_file_id=?, admin_message_id=?, status=?, updated_at=unixepoch() WHERE id=?'),
  // ذخیره‌ی خودِ رسید بدونِ تغییرِ وضعیت (مسیرِ auto-approve/reject؛ waiting_review را sendReceiptToAdmin می‌زند)
  saveReceiptFile: db.prepare('UPDATE payments SET receipt_file_id=?, updated_at=unixepoch() WHERE id=?'),
  // برگشتِ پرداخت — فقط از approved (idempotent، ضدِ دوبار). changes==1 یعنی همین حالا برگشت خورد.
  markPaymentReversed: db.prepare("UPDATE payments SET status='reversed', updated_at=unixepoch() WHERE id=? AND status='approved'"),
  setDistrust: db.prepare('UPDATE users SET pay_distrust=1 WHERE telegram_id=?'),
  // کسرِ اعتبارِ برگشتی، اما هرگز زیرِ صفر (مصرف‌شده تا آن لحظه اشکالی ندارد)
  clawback: db.prepare('UPDATE users SET balance = MAX(0, balance - ?) WHERE telegram_id=?'),
  // پرداختِ منتظرِ رسیدِ همین کاربر (برای بازیابیِ رسید وقتی state گم شده — کاربر بعد از فاکتور /start زده)
  pendingReceiptPayment: db.prepare("SELECT * FROM payments WHERE user_id=? AND status='pending' AND step='receipt' AND created_at > unixepoch()-259200 ORDER BY id DESC LIMIT 1"),
  staleReceipts: db.prepare("SELECT * FROM payments WHERE status='waiting_review' AND updated_at < unixepoch()-7200 AND (reminded_at IS NULL OR reminded_at < unixepoch()-14400) ORDER BY id"),
  setReminded:   db.prepare('UPDATE payments SET reminded_at=unixepoch() WHERE id=?'),
  pendingActions: db.prepare('SELECT * FROM admin_actions WHERE done_at IS NULL ORDER BY id LIMIT 20'),
  markActionDone: db.prepare('UPDATE admin_actions SET done_at=unixepoch() WHERE id=?'),
  setPaymentDiscount: db.prepare('UPDATE payments SET discount_code_id=?, original_amount=COALESCE(original_amount, amount), amount=?, updated_at=unixepoch() WHERE id=?'),
  dailyRevenue:   db.prepare("SELECT COALESCE(SUM(amount),0) AS s FROM payments WHERE status='approved' AND created_at >= unixepoch()-86400"),
  monthlyRevenue: db.prepare("SELECT COALESCE(SUM(amount),0) AS s FROM payments WHERE status='approved' AND created_at >= unixepoch()-2592000"),
  totalRevenue:   db.prepare("SELECT COALESCE(SUM(amount),0) AS s FROM payments WHERE status='approved'"),
  countUsers:     db.prepare('SELECT COUNT(*) AS c FROM users'),

  getDiscountCode:     db.prepare('SELECT * FROM discount_codes WHERE code=? AND is_active=1'),
  getDiscountById:     db.prepare('SELECT * FROM discount_codes WHERE id=?'),
  insertDiscountCode:  db.prepare('INSERT INTO discount_codes (code, discount_percent, max_discount_amount, expires_at, max_uses_per_user, only_user_id, created_by) VALUES (?,?,?,?,?,?,?)'),
  incDiscountUses:     db.prepare('UPDATE discount_codes SET total_uses=total_uses+1 WHERE id=?'),
  countApprovedPayments: db.prepare("SELECT COUNT(*) AS c FROM payments WHERE user_id=? AND status='approved'"),
  insertDiscountUse:   db.prepare('INSERT INTO discount_uses (code_id, user_id, payment_id, discount_amount) VALUES (?,?,?,?)'),
  getUserDiscountUses: db.prepare('SELECT COUNT(*) AS c FROM discount_uses WHERE code_id=? AND user_id=?'),
  // «کد الان دستِ کدام فاکتور است؟» — فقط فاکتورِ رسیدداده‌ی منتظرِ تأیید کد را نگه می‌دارد.
  // فاکتورِ `pending` (بدونِ رسید) عمداً شمرده نمی‌شود: کاربر همیشه فقط با تازه‌ترین فاکتورش
  // کار می‌کند (session.paymentId و بازیابیِ عکس هر دو تازه‌ترین را می‌گیرند)، پس فاکتورِ
  // قدیمیِ رهاشده هیچ راهی ندارد که به waiting_review برسد و کد را خرج کند. شمردنش فقط
  // کدِ یک‌بارمصرفِ خودِ کاربر را برای همیشه قفل می‌کرد (باگِ واقعی: کدی که ربات پیشنهاد
  // می‌داد ولی هرگز پذیرفته نمی‌شد). خودِ فاکتورِ جاری هم کنار گذاشته می‌شود تا واردکردنِ
  // دوباره‌ی کد روی همان فاکتور خودش را بلاک نکند.
  countPendingDiscount: db.prepare("SELECT COUNT(*) AS c FROM payments WHERE discount_code_id=? AND user_id=? AND id<>? AND status='waiting_review'"),

  insertReferral: db.prepare('INSERT OR IGNORE INTO referrals (referrer_id, referee_id) VALUES (?,?)'),
  getReferralByReferee: db.prepare('SELECT * FROM referrals WHERE referee_id=?'),
  setReferralRewarded:  db.prepare('UPDATE referrals SET rewarded=1 WHERE id=?'),

  setMemory: db.prepare('UPDATE users SET memory_json=? WHERE telegram_id=?'),
  getDailyText: db.prepare('SELECT text FROM daily_texts WHERE card_key=? AND reversed=? AND focus=?'),
  setDailyText: db.prepare('INSERT OR REPLACE INTO daily_texts (card_key, reversed, focus, text) VALUES (?,?,?,?)'),
  getCardFile: db.prepare('SELECT file_id FROM card_files WHERE card_key=?'),
  setCardFile: db.prepare('INSERT INTO card_files (card_key, file_id, updated_at) VALUES (?,?,unixepoch()) ON CONFLICT(card_key) DO UPDATE SET file_id=excluded.file_id, updated_at=unixepoch()'),
};

/* ===== 3) هلپرهای کاربر/سشن ===== */
function upsertUser(ctx) {
  const before = stmts.getUser.get(ctx.from.id);
  stmts.upsertUser.run(ctx.from.id, ctx.from.first_name || '', ctx.from.username || '');
  return { isNew: !before };
}
const getUser  = (uid) => stmts.getUser.get(uid);
const getState = (uid) => getUser(uid)?.state || 'new';
const setState = (uid, s) => stmts.setState.run(s, uid);
const getBalance = (uid) => getUser(uid)?.balance || 0;
const hasRecharged = (uid) => stmts.countApprovedPayments.get(uid).c > 0;
// کدِ شخصیِ تخفیفِ اولین شارژ: قطعی و یکتا per کاربر (base36 آی‌دی → بدون احتمالِ برخورد)،
// پس چندبار زدنِ دکمه همان کد را می‌دهد نه کدِ تازه. فقط با only_user_id خودش و یک‌بار مصرف.
const firstCodeFor = (uid) => 'T50' + Number(uid).toString(36).toUpperCase();
function ensureFirstDiscountCode(uid) {
  const code = firstCodeFor(uid);
  if (stmts.getDiscountCode.get(code)) return code;
  try {
    stmts.insertDiscountCode.run(code, FIRST_RECHARGE_DISCOUNT.percent, null,
      null, 1, uid, 0);
  } catch (e) { logErr('first discount code', e.message); }
  return code;
}
// تک‌منبعِ حقیقتِ «این کاربر واقعاً تخفیفِ اولین شارژ دارد؟» — هم دکمه‌ی پی‌وال و هم
// هندلرِ want_discount از همین می‌پرسند، تا هرگز دکمه‌ای دیده نشود که پشتش تخفیفی نیست.
function firstDiscountAvailable(uid) {
  if (hasRecharged(uid)) return false;
  const dc = stmts.getDiscountCode.get(firstCodeFor(uid));
  if (!dc) return true; // کد هنوز ساخته نشده = دست‌نخورده
  const used = stmts.getUserDiscountUses.get(dc.id, uid).c
    + stmts.countPendingDiscount.get(dc.id, uid, 0).c;
  return used < dc.max_uses_per_user;
}

// نامِ فارسیِ چیدمان (برای خطِ «هزینه‌ی فال «...»»). اگر چیدمان پیدا نشد، متنِ عمومی.
const spreadFaOf = (r, uid) => faOf(SPREAD_BY_ID[r?.type], coinsOn(uid)) || L.reading.spreadFallbackFa;
// پیامِ یکسانِ «موجودی کافی نیست» در همه‌ی نقاطِ پی‌وال (شخصی‌شده با نام کاربر).
// موجودی و نامِ فال هم نشان داده می‌شوند تا کاربر کسری را خودش ببیند.
// ⚠️ در دنیای الماس این متن HTML است (باکسِ نقل‌قولِ موجودی)، پس هر مقدارِ کاربرساخته باید
// esc شود. نامِ کاربر تنها ورودیِ کاربرساخته است؛ `spreadFa` از ثابت‌های خودمان می‌آید ولی
// برای اینکه این تابع در آینده هم امن بماند، هر دو esc می‌شوند.
const needBalanceText = (uid, reading) =>
  L.reading.needBalance({
    name: esc(dispName(getUser(uid))),
    balance: getBalance(uid),
    spreadFa: esc(spreadFaOf(reading, uid)),
    price: reading.price,
    cur: curOf(uid),
  });
// هر پیامی که needBalanceText می‌فرستد باید این extra را هم بدهد، وگرنه تگِ نقل‌قول خام دیده می‌شود.
const needBalanceExtra = { parse_mode: 'HTML' };
// ردیفِ ثابتِ زیرِ پیامِ کم‌موجودی: مسیر اصلی (شارژ) اول، تخفیف پشتِ دکمه‌ی دوم.
// دکمه‌ی «🎁 تخفیف می‌خوام» فقط برای کسی که واقعاً تخفیفِ اولین شارژ دارد. کاربری که
// قبلاً شارژ کرده یا تخفیفش خرج شده، این دکمه را اصلاً نمی‌بیند: تا قبل از این، زدنش
// او را به دعوتِ دوستان می‌برد و وسطِ فالِ رزروشده، مسیرِ کاربر را کاملاً منحرف می‌کرد.
// ترتیبِ عمدی (v2.0.0): «پرداختِ هزینه‌ی همین فال» اولِ همه، چون کم‌اصطکاک‌ترین مسیرِ رسیدن
// به همان چیزی است که کاربر همین حالا می‌خواهد؛ «افزایش موجودی» مسیرِ کیف‌پول است و
// «تخفیف می‌خوام» فقط برای کسی که واقعاً تخفیفِ اولین پرداخت را دارد.
// صفحه‌ی «باز کردن کارت‌ها» برای کاربری که اعتبارش کافی است — تک‌منبعِ متن و دکمه.
// چرا وجود دارد: قبلاً این کاربر همان دکمه‌ی قیمت‌دارِ «۳۰٬۰۰۰ تومان از کیف‌پول» را می‌دید و
// هیچ‌جا نمی‌گفتیم «این پول را داری». تحلیل جرنی نشان داد چند کاربر با موجودیِ دقیقاً کافی
// یک تپ تا فالِ کاملشان مانده‌اند و حرکت نمی‌کنند. حالا صریح می‌گوییم پرداختی در کار نیست.
const coveredText = (uid, reading) => L.reading.balanceEnough({
  name: dispName(getUser(uid)),
  balance: getBalance(uid),
  spreadFa: spreadFaOf(reading, uid),
  price: reading.price,
  cur: curOf(uid),
});
const coveredRow = (readingId, price, uid) => [Markup.button.callback(
  COVERED_PAYWALL_ENABLED ? L.buttons.openCardsCovered : L.buttons.openCards(price, curOf(uid)),
  `unlock:${readingId}`,
)];

// برچسبِ دکمه‌ی شارژ به زبانِ اقتصادِ همان کاربر: در دنیای الماس «خرید الماس»،
// در دنیای تومانی همان «افزایش موجودی کیف پول». هر نقطه‌ی جدید باید از همین بخواند.
const rechargeLabel = (uid) => (coinsOn(uid) ? L.buttons.buyCoins(curOf(uid)) : L.buttons.recharge);
// دکمه‌ی «خرید الماس» همیشه **سبز** است (تصمیمِ صریحِ مالک). فقط در دنیای الماس رنگ
// می‌گیرد؛ دکمه‌ی تومانیِ کاربرِ واقعی بیت‌به‌بیت دست‌نخورده می‌ماند.
const rechargeBtn = (uid) => styled(
  Markup.button.callback(rechargeLabel(uid), 'recharge'), coinsOn(uid) ? 'success' : undefined);

const needBalanceRows = (uid, reading) => {
  // اقتصادِ سکه: «پرداختِ هزینه‌ی همین فال» و «تخفیف می‌خوام» هر دو مفهومِ دنیای تومانی‌اند
  // (فاکتورِ تک‌فال با قیمتِ همان فال)؛ در دنیای بسته‌ای نگه‌داشتنشان دو ریلِ قیمتِ موازی
  // می‌ساخت. خودِ بسته‌ها تخفیف‌اند.
  // UX v2.3 (تصمیمِ صریحِ مالک): زیرِ پیامِ کم‌موجودی **دقیقاً همان سه راهِ صفحه‌ی کیف** بیاید
  // (خرید، دعوت، و کارت شانس اگر سهمیه‌ی امروز باز است) — یک تک‌منبع، نه دو لیستِ موازی.
  if (coinsOn(uid)) return walletRows(uid);
  const rows = [];
  if (reading) rows.push([Markup.button.callback(L.buttons.payThisReading(reading.price), `payr:${reading.id}`)]);
  rows.push([rechargeBtn(uid)]);
  if (reading && firstDiscountAvailable(uid)) rows.push([Markup.button.callback(L.buttons.wantDiscount, `wdisc:${reading.id}`)]);
  return rows;
};

// پیامِ «شارژ تأیید شد» به زبانِ اقتصادِ همان کاربر: تومانی همان متنِ همیشگی، الماسی تعدادِ
// الماسِ اضافه‌شده و موجودیِ جدید به الماس.
const approvedMsg = (uid, creditAmount, bonus) => {
  const cur = curOf(uid);
  if (!cur.on) return L.wallet.approved(creditAmount, getBalance(uid), bonus);
  return L.wallet.coinsApproved(
    Math.round((creditAmount + bonus) / COIN_VALUE),
    Math.round(getBalance(uid) / COIN_VALUE),
    cur,
  );
};

// فاکتورِ مستقیمِ یک فالِ رزروشده: بدونِ مرحله‌ی «چقدر شارژ کنم؟». مبلغِ پرداخت = قیمتِ فال
// (یا ۲۰٪ کمتر با تخفیفِ اولین پرداخت)، ولی اعتبارِ داده‌شده هنگام تأیید همان قیمتِ کاملِ فال
// است (`original_amount`) تا فال دقیقاً باز شود — همان ریاضیِ جاافتاده‌ی تخفیف، بدونِ منطقِ نو.
async function invoiceForReading(ctx, uid, readingId, withDiscount) {
  const r = stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid || r.status !== 'pending_payment') {
    return ctx.reply(L.errors.stateLost, mainKeyboard(uid));
  }
  const price = r.price;
  let payAmount = price;
  let dc = null;
  if (withDiscount && firstDiscountAvailable(uid)) {
    ensureFirstDiscountCode(uid);
    dc = stmts.getDiscountCode.get(firstCodeFor(uid));
    if (dc) payAmount = Math.max(0, price - Math.round(price * dc.discount_percent / 100));
  }
  const paymentId = Number(stmts.insertPayment.run(uid).lastInsertRowid);
  track(db, uid, EVENTS.RECHARGE_STARTED, { payment_id: paymentId, kind: 'reading', reading_id: readingId });
  stmts.claimAmount.run(price, paymentId);            // اصل = قیمتِ فال، step → receipt
  if (dc) stmts.setPaymentDiscount.run(dc.id, payAmount, paymentId); // original_amount=price، amount=تخفیف‌خورده
  patchSession(uid, { paymentId, readingId });
  setState(uid, 'pay_receipt');
  // پیامِ اطلاع‌رسانیِ تخفیف، بلافاصله قبل از فاکتور (بدونِ هیچ دکمه‌ای وسطِ راه)
  if (dc) await ctx.reply(L.wallet.discountApplied(price, payAmount, dc.discount_percent), { parse_mode: 'Markdown' });
  await ctx.reply(L.wallet.invoice(payAmount, CARD_NUMBER, CARD_OWNER), {
    parse_mode: 'Markdown',
    reply_markup: Markup.inlineKeyboard([
      cardCopyRow(),
      [Markup.button.callback(L.buttons.cancel, `pay_cancel:${paymentId}`)],
    ]).reply_markup,
  });
}
// کاربرِ بی‌اعتماد (بعد از برگشتِ رسیدِ فیک): ایجنت دیگر برایش خودکار تصمیم نمی‌گیرد
const isDistrusted = (uid) => !!getUser(uid)?.pay_distrust;
// نامِ نمایشیِ کاربر: نام فارسیِ خودش (اگر در آنبوردینگ داده) — نه first_name تلگرام که ممکن است انگلیسی/نامفهوم باشد.
// در متن‌های رو-به-کاربر با fallback خالی؛ به LLM هرگز نام تلگرام نمی‌رود (تا مدل نام نامفهوم را تکرار نکند).
const dispName = (u) => (u?.display_name || '').trim();

function getSession(uid) {
  const raw = getUser(uid)?.session_json;
  if (!raw) return {};
  try { return JSON.parse(raw); } catch { return {}; }
}
function setSession(uid, s) { stmts.setSession.run(s ? JSON.stringify(s) : '', uid); }
function patchSession(uid, patch) { const s = getSession(uid); Object.assign(s, patch); setSession(uid, s); return s; }

// پاک‌سازی کامل یک کاربر — /reset مالک (شامل کیف‌پول)
function wipeUser(uid) {
  // صف اکشن رسیدها به payment_id وصل است نه user_id → قبل از حذف payments با subquery پاک شود
  try { db.prepare('DELETE FROM admin_actions WHERE payment_id IN (SELECT id FROM payments WHERE user_id=?)').run(uid); } catch (e) { logErr('wipe admin_actions', e.message); }
  try { db.prepare('DELETE FROM referrals WHERE referee_id=? OR referrer_id=?').run(uid, uid); } catch (e) { logErr('wipe referrals', e.message); }
  // `daily_log` هم باید پاک شود، وگرنه ادمینی که ریست کرده هفت روز نمی‌تواند
  // کارت‌هایی را که قبلاً دیده دوباره بگیرد و تستِ کارتِ روز عملاً قفل می‌شود.
  for (const [t, col] of [['users','telegram_id'],['readings','user_id'],['payments','user_id'],['discount_uses','user_id'],['events','user_id'],['ab_exposures','user_id'],['daily_log','user_id']]) {
    try { db.prepare(`DELETE FROM ${t} WHERE ${col}=?`).run(uid); } catch (e) { logErr('wipe', t, e.message); }
  }
  try { db.prepare('DELETE FROM discount_codes WHERE only_user_id=?').run(uid); } catch (e) { logErr('wipe personal code', e.message); }
}

function normalizeDigits(s) {
  return String(s).replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
}
// tehranToday در reading-core.js است (کانتکستِ خوانش هم از آن استفاده می‌کند).
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/* ===== 4) OpenRouter و موتور دک ===== */
// کلاینتِ OpenRouter (orRequest/orChat/orChatResilient/orTranscribe/parseJsonLoose) و
// موتورِ دک (mulberry32/seedToInt/shuffledDeck/drawCards) به reading-core.js منتقل شدند.
// دلیل: `tools/reading-lab.mjs` باید **همان** ریکوئست را با همان temperature و همان
// برنامه‌ی فالبک بفرستد؛ اگر کپی می‌شد، تستِ آفلاین چیزی را می‌سنجید که با پروداکشن
// یکی نیست. رفتارِ ربات ذره‌ای عوض نشده.

/* ===== 6) هلپرهای تلگرام ===== */
const TG_LIMIT = 3800;
async function replyLong(ctx, text, extra) {
  for (let i = 0; i < text.length; i += TG_LIMIT) {
    const isLast = i + TG_LIMIT >= text.length;
    await ctx.reply(text.slice(i, i + TG_LIMIT), isLast ? extra : undefined);
  }
}
// ارسال عکس کارت با کش file_id (اولین بار از فایل، بعد از آن از file_id تلگرام)
async function sendCardPhoto(ctx, cardKey, caption, { spoiler = true } = {}) {
  const cached = stmts.getCardFile.get(cardKey)?.file_id;
  const media = cached || { source: `./assets/cards/${cardKey === 'back' ? 'back.jpg' : CARD_BY_KEY[cardKey].file}` };
  const msg = await ctx.replyWithPhoto(media, { caption, has_spoiler: spoiler });
  if (!cached) {
    const fid = msg.photo?.[msg.photo.length - 1]?.file_id;
    if (fid) stmts.setCardFile.run(cardKey, fid);
  }
  return msg;
}
async function typing(ctx, ms, action = 'typing') {
  try { await ctx.sendChatAction(action); } catch {}
  await sleep(ms);
}

// uid اختیاری: فقط ادمین‌ها (دو آی‌دیِ ADMIN_IDS) دکمه‌ی «ریست حساب (ادمین)» را می‌بینند — همیشه،
// حتی خارج از فاز تست. این تنها تمایزِ رو-به-کاربرِ ادمین است (ابزار مدیریتی؛ فلوی محصول یکسان می‌ماند).
// 🎨 رنگِ دکمه — Bot API 9.4 (۹ فوریه ۲۰۲۶): فیلدِ `style` روی KeyboardButton و
// InlineKeyboardButton، یکی از 'success' (سبز)، 'primary' (آبی) یا 'danger' (قرمز).
// نبودش = رنگِ پیش‌فرضِ خودِ کلاینت، پس روی کلاینت‌های قدیمی‌تر بی‌اثر و بی‌خطر است
// (فیلدِ ناشناخته را نادیده می‌گیرند). telegraf آن را دست‌نخورده سریالایز می‌کند.
const styled = (btn, style) => (style ? { ...btn, style } : btn);

function mainKeyboard(uid) {
  // UX v2.1: کارتِ روزِ رایگان نامِ صریح‌تری گرفت («فال تک کارت امروز») و **تنها** نقطه‌ی
  // دسترسی‌اش همین کیبورد است — از منوی فال‌ها برداشته شد تا آن‌جا فقط فالِ واقعی باشد.
  // «کارت شانس» ردیفِ خودش را دارد چون مسیرِ متفاوتی است: الماس می‌گیرد، فال نمی‌دهد.
  const rows = uxV2For(uid)
    ? [
      // تصمیمِ صریحِ مالک: «فال بگیر» بالای بقیه و تمام‌عرض — نه دو دکمه‌ی نصفه کنارِ هم.
      // فالِ پولی محصولِ اصلی است و باید بزرگ‌ترین و اولین چیزِ کیبورد باشد.
      [L.buttons.reading],
      // v3.25.0 (تصمیمِ صریحِ مالک): «کارت شانس» یک پله بالا آمد و «فال تک کارت» یک پله
      // پایین رفت. منطقش: کارت شانس الماس **می‌دهد** و قلابِ بازگشتِ روزانه است، پس باید
      // زودتر از مصرف‌کننده‌ی رایگان دیده شود.
      [L.buttons.luckyMain],
      [L.buttons.dailyOneCard],
      [L.buttons.coinShop, L.buttons.inviteMain],
    ]
    : [
      [L.buttons.daily, L.buttons.reading],
      [L.buttons.wallet, L.buttons.inviteMain],
    ];
  if (FREE_MENU_ENABLED && HAFEZ.length) rows.splice(1, 0, [L.buttons.freeMenu]);
  rows.push(...supportRow(L.support)); // 💬 پشتیبانی — برای همه، همیشه (خالی می‌شود اگر SUPPORT.enabled=false)
  if (isTester(uid)) rows.push([L.buttons.resetTest]); // دکمه‌ی ریست: ادمین‌ها و تسترها، همیشه
  return Markup.keyboard(rows).resize();
}

// تا پایان آنبوردینگ (نوشتن نام + پاسخ به حوزه‌ی تمرکز)، کاربر نباید بتواند با دکمه‌ها مرحله را رد کند.
const ONBOARDING_STATES = ['onboard_name', 'onboard_focus', 'onboard_month'];
// اگر کاربر وسط آنبوردینگ روی یک دکمه‌ی اصلی زد (کیبوردِ کش‌شده یا تایپِ دستی)، به‌جای اجرا،
// همان قدمِ فعلیِ آنبوردینگ دوباره یادآوری می‌شود. خروجی true = بلاک شد.
async function blockDuringOnboarding(ctx) {
  const st = getState(ctx.from.id);
  if (!ONBOARDING_STATES.includes(st)) return false;
  if (st === 'onboard_name') {
    await ctx.reply(L.onboarding.askNameRetry, Markup.removeKeyboard());
  } else if (st === 'onboard_month') {
    await askBirthMonth(ctx);
  } else {
    await ctx.reply(L.onboarding.askFocus, Markup.inlineKeyboard(
      L.buttons.focusOptions.map(([key, label]) => [Markup.button.callback(label, `focus:${key}`)])
    ));
  }
  return true;
}

// 🗓 سؤالِ ماهِ تولد. **چهار ستون × سه ردیف** (تصمیمِ صریحِ مالک): چیدمانِ دو ستونیِ قبلی
// شش ردیف می‌شد و تقریباً یک صفحه‌ی موبایل را می‌گرفت. نامِ ماه‌های فارسی کوتاه‌اند
// (بلندترین «اردیبهشت» با ۸ حرف) پس در چهار ستون هم کامل جا می‌شوند.
const BMONTH_COLS = 4;
async function askBirthMonth(ctx) {
  const rows = [];
  for (let i = 0; i < 12; i += BMONTH_COLS) {
    rows.push(Array.from({ length: BMONTH_COLS }, (_, d) => i + d)
      .map((k) => Markup.button.callback(L.buttons.birthMonths[k], `bmonth:${k + 1}`)));
  }
  await ctx.reply(L.onboarding.askBirthMonth, Markup.inlineKeyboard(rows));
}

// 🧭 ردیفِ «بازگشت به منو» برای استیت‌های میانیِ فلو (خالی وقتی گارد خاموش است تا رفتار عیناً قبلی شود).
const navMenuRow = () => (NAV_GUARD_ENABLED ? [[Markup.button.callback(L.buttons.backToMenu, 'nav:menu')]] : []);
// نکته‌ی UX (بند ۹ب ریشه): در استیت‌هایی که از کاربر «تایپ/ویس» می‌خواهیم (askQuestion/askTopic) هیچ
// دکمه‌ای نمی‌گذاریم تا حواسش پرت نشود؛ راهِ خروجِ آن‌جا گاردِ «فالِ باز» است، نه دکمه‌ی درون-پیام.
// (`navMenuKb` با حذفِ پیامِ `useButtons` در v3.17.0 بی‌مصرف شد و طبق بند ۹/۰ ریشه پاک شد.)

/* ═══════════ 🎯 نیتِ معلق (pending intent) ═══════════
   قاعده‌ی صریحِ مالک: «وقتی بابتِ رسیدن به چیزی، فلوی موجود رو انصراف می‌زنیم، بعد از
   انصراف همون چیزی باید بیاد که می‌خواستیم بهش برسیم.»
   باگِ واقعی که این را ساخت: کاربر وسطِ فاکتور دکمه‌ی پشتیبانی را زد، گارد گفت «فاکتور
   باز داری، انصراف بده»، انصراف داد، و به‌جای پشتیبانی پیامِ عمومیِ «همیشه اینجام» گرفت.

   چهار تصمیمِ عمدی:
   ۱) **فقط وقتی یک گارد واقعاً بلاک می‌کند** نیت ثبت می‌شود. مسیرِ عادی هیچ‌چیز
      نمی‌نویسد، پس هیچ نیتِ کهنه‌ای در سشن جا نمی‌ماند.
   ۲) **opt-in per call site**: گاردها آرگومانِ دومِ اختیاری می‌گیرند. هر فراخوانی که
      نیت ندهد دقیقاً مثل قبل رفتار می‌کند — یعنی رول‌بکِ این فیچر «ندادنِ آرگومان» است.
   ۳) **در سشن (یعنی DB) ذخیره می‌شود، نه حافظه** (بند ۹ب/۵): بینِ بلاک شدن و انصراف
      دادن ممکن است دیپلوی بیفتد، و آن‌وقت کاربر همان قولی را که بهش دادیم گم می‌کند.
   ۴) **یک‌بارمصرف و تاریخ‌دار**: `takeIntent` می‌خواند و پاک می‌کند، و نیتِ کهنه‌تر از
      `INTENT_TTL_S` نادیده گرفته می‌شود تا یک انصرافِ ساعت‌ها بعد صفحه‌ی بی‌ربط نیاورد.
*/
const INTENT_TTL_S = 30 * 60;
const INTENT = {
  DAILY:   'daily',
  SUPPORT: 'support',
  WALLET:  'wallet',
  INVITE:  'invite',
  LUCKY:   'lucky',
  READING: 'reading',
};
function setIntent(uid, key) {
  try { patchSession(uid, { intent: key, intentAt: Math.floor(Date.now() / 1000) }); } catch {}
}
function takeIntent(uid) {
  try {
    const s = getSession(uid) || {};
    const k = s.intent;
    if (!k) return null;
    patchSession(uid, { intent: '', intentAt: 0 });
    if (!s.intentAt || Math.floor(Date.now() / 1000) - s.intentAt > INTENT_TTL_S) return null;
    return k;
  } catch { return null; }
}
// جدولِ بازپخش عمداً **صریح** است، نه بازفرستادنِ آپدیتِ خام: بازفرستادن یعنی گاردها
// دوباره اجرا شوند و کاربر در همان حلقه بیفتد.
const INTENT_REPLAY = {
  [INTENT.DAILY]:   (ctx) => dailyCard(ctx),
  [INTENT.SUPPORT]: (ctx) => replySupport(ctx),
  [INTENT.WALLET]:  (ctx) => showWallet(ctx),
  [INTENT.INVITE]:  (ctx) => showInvite(ctx),
  [INTENT.LUCKY]:   (ctx) => luckyCard(ctx),
  [INTENT.READING]: (ctx) => showCatalog(ctx),
};
// صفحه‌ی پشتیبانی از **همان** سازنده‌ی shared می‌آید که خودِ دکمه استفاده می‌کند، تا
// بازپخشِ نیت هیچ‌وقت با تپِ واقعیِ دکمه واگرا نشود (بند ۶ج: تک‌منبع).
async function replySupport(ctx) {
  const r = supportReply('TRT', ctx.from.id, L.support);
  return ctx.reply(r.text, r.extra);
}

// خروجی true = نیت بازپخش شد، پس صدازننده نباید پیامِ عمومیِ خودش را هم بفرستد.
async function replayIntent(ctx, uid) {
  const k = takeIntent(uid);
  const fn = k && INTENT_REPLAY[k];
  if (!fn) return false;
  try { await fn(ctx); return true; } catch (e) { logErr('replayIntent:', e.message); return false; }
}

// گاردِ «پرداختِ باز» — دوقلوی blockDuringOnboarding برای ریلِ پرداخت (الگوی voice2text):
// اگر کاربر فاکتورِ باز دارد، دکمه‌های منو نباید آن را بی‌صدا یتیم کنند؛ به‌جای اجرا «فاکتور باز داری»
// + دکمه‌ی انصراف نشان بده و اکشن را متوقف کن. خروجی true = بلاک شد.
const PAY_STATES = ['pay_amount', 'pay_receipt', 'pay_discount'];
async function blockDuringOpenPay(ctx, intent) {
  if (!NAV_GUARD_ENABLED) return false;
  const uid = ctx.from.id;
  if (!PAY_STATES.includes(getState(uid))) return false;
  const pid = getSession(uid)?.paymentId;
  if (!pid) return false; // بدون paymentId نمی‌توان انصراف را وصل کرد → بگذار رد شود (مسیر بازیابیِ رسید)
  if (intent) setIntent(uid, intent);   // بعد از انصراف، همین برمی‌گردد
  await ctx.reply(L.errors.openInvoice, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.cancel, `pay_cancel:${pid}`)],
  ]));
  return true;
}

// گاردِ «فالِ باز» — وقتی کاربر وسط فلوی خوانش (بعد از انتخاب فال) است و به‌جای ادامه دکمه‌ی منو می‌زند:
// به‌جای رهاکردنِ بی‌صدای فال، می‌پرسیم «ادامه بدم یا انصراف». مخصوصاً برای استیتِ ورودی (await_question)
// که عمداً دکمه‌ی درون-پیام ندارد؛ این گارد راهِ خروجِ آن است (قرارداد State Management بند ۹ب ریشه).
const READING_INPROGRESS = ['confirm_focus', 'await_question', 'breathing', 'shuffling', 'picking'];

// دکمه‌ی «ادامه» برای فالی که وسطِ **افشا**ست. عمداً همان `callback_data`ِ قدمِ فعلی
// دوباره ساخته می‌شود، نه یک مسیرِ تازه: پس گاردهای ضدِ دوبار-تپِ `next:`/`final:`
// (که شماره‌ی کارتِ منتظر را با سشن می‌سنجند) عیناً کار می‌کنند و هیچ کارتی پرش یا
// تکرار نمی‌شود. `null` = چیزی برای ادامه نیست، پس گارد اصلاً نباید فعال شود.
function revealResumeRow(uid) {
  const s = getSession(uid) || {};
  const rid = s.readingId;
  if (!rid) return null;
  const r = stmts.getReading.get(rid);
  if (!r || r.user_id !== uid || !r.cards_json) return null;   // مالکیتِ رکورد (بند ۹)
  let n;
  try { n = JSON.parse(r.cards_json).length; } catch { return null; }
  const idx = s.revealIdx || 0;
  if (idx < n) return [Markup.button.callback(L.buttons.nextCard, `next:${rid}:${idx}`)];
  if (v4For(uid)) return [Markup.button.callback(L.buttons.finalAnswer, `final:${rid}`)];
  return null;   // نسل قدیم بعد از کارتِ آخر خودکار جمع‌بندی می‌کند؛ چیزی برای ادامه نمانده
}

// 🔒 فالِ **در حالِ تحویل** (پول داده شده، `status='started'`) هرگز با یک تپ از سشن پاک
// نمی‌شود. `cancelReading` خودش درست عمل می‌کند و پولی برنمی‌گرداند (محصول دارد تحویل
// می‌شود)، ولی `setSession(uid, null)`ِ بعدش `readingId` و `revealIdx` را می‌برد و کاربر
// دیگر هیچ راهی به بقیه‌ی فالی که خریده ندارد — بی‌صدا، بدونِ ریفاند، بدونِ هیچ پیامی.
// مسیرِ واقعیِ رسیدن به این حالت: یک دکمه‌ی **کهنه‌ی** `nav:menu` یا `reading:cancel` که
// بالای چت مانده و کاربر وسطِ افشا اسکرول می‌کند و می‌زند.
async function blockDuringDelivering(ctx) {
  const uid = ctx.from.id;
  if (getState(uid) !== 'revealing') return false;
  const rid = getSession(uid)?.readingId;
  const r = rid && stmts.getReading.get(rid);
  if (!r || r.user_id !== uid || r.status !== 'started') return false;
  const row = revealResumeRow(uid);
  if (!row) return false;   // چیزی برای ادامه نمانده → بگذار مسیرِ عادی برود
  await ctx.reply(L.reading.openReadingGuard, Markup.inlineKeyboard([row]));
  return true;
}

async function blockDuringOpenReading(ctx, intent) {
  if (!NAV_GUARD_ENABLED) return false;
  const uid = ctx.from.id;
  const state = getState(uid);
  // فالِ در حالِ **تحویل** (`revealing`): همان پیامِ استاندارد، ولی **بدونِ انصراف**.
  // این‌جا پول داده شده و محصول دارد می‌رسد؛ «انصراف» یعنی پس‌گرفتنِ چیزی که کاربر
  // همین حالا دارد می‌گیرد. تا قبل از v3.17.0 این استیت اصلاً گارد نداشت، یعنی تپِ
  // «فال بگیر» وسطِ افشا یک فالِ **پول‌داده‌شده** را بی‌صدا یتیم می‌کرد.
  if (state === 'revealing') {
    const row = revealResumeRow(uid);
    if (!row) return false;
    await ctx.reply(L.reading.openReadingGuard, Markup.inlineKeyboard([row]));
    return true;
  }
  if (!READING_INPROGRESS.includes(state)) return false;
  if (intent) setIntent(uid, intent);   // بعد از انصراف، همین برمی‌گردد
  await ctx.reply(L.reading.openReadingGuard, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.resumeReading, 'reading:resume')],
    [Markup.button.callback(L.buttons.cancel, 'reading:cancel')],
  ]));
  return true;
}

// گاردِ «فالِ رزروشده» — کاربر فالی دارد که کارت‌هایش انتخاب شده و منتظرِ پرداخت است
// (state=confirm_pay، بعد از انصراف از فاکتور یا بعد از فرستادنِ رسید) و به‌جای ادامه/انصراف،
// فالِ جدید شروع می‌کند. تا قبل از این، فالِ قبلی بی‌صدا یتیم می‌شد و کاربر بدونِ هیچ پیامی
// فالِ رزروشده‌اش را از دست می‌داد. حالا همان پی‌وال («باز کردن کارت‌ها» = ادامه) + «انصراف»
// دوباره نشان داده می‌شود (قرارداد State Management بند ۹ب). خروجی true = بلاک شد.
async function blockDuringPendingReading(ctx) {
  if (!NAV_GUARD_ENABLED) return false;
  if (getState(ctx.from.id) !== 'confirm_pay') return false;
  return await offerPendingReading(ctx, ctx.from.id);
}

// «اونو ادامه می‌دم» → همان پیامِ آخرِ فلو (مطابقِ استیتِ فعلی) دوباره نشان داده می‌شود.
async function resendCurrentStep(ctx, uid) {
  const state = getState(uid);
  const s = getSession(uid);
  if (state === 'await_question') {
    return ctx.reply(s?.focusKey === 'open' ? L.reading.askTopic(toneV2For(uid)) : L.reading.askQuestion(toneV2For(uid)), { parse_mode: 'Markdown' });
  }
  if (state === 'confirm_focus') {
    return ctx.reply(L.reading.askFocusAgain, Markup.inlineKeyboard(
      L.buttons.focusOptions.map(([key, label]) => [Markup.button.callback(label, `focus:${key}`)])
    ));
  }
  if (state === 'breathing') {
    return ctx.reply(L.reading.breathing, Markup.inlineKeyboard([[Markup.button.callback(L.buttons.ready, 'ready_breath')]]));
  }
  if (state === 'picking') {
    return ctx.reply(L.reading.pickPrompt(s?.need || USER_PICKS), pickGridKb(s?.picks || []));
  }
  if (state === 'shuffling') {
    const m = await ctx.reply(L.reading.shuffleFrames[0], Markup.inlineKeyboard([[Markup.button.callback(L.buttons.stopShuffle, 'shuffle_stop')]]));
    patchSession(uid, { shuffleMsgId: m.message_id });
    return;
  }
  // دکمه‌ی کهنه‌ی «ادامه» در استیتی که دیگر فلوی بازی ندارد: به‌جای پیامِ حذف‌شده‌ی
  // `useButtons`، همان کاتالوگ نشان داده می‌شود (بن‌بست نیست و استانداردِ دومی نمی‌سازد).
  return showCatalog(ctx);
}

/* ===== 7) LLM خوانش — پیش‌فراخوانی و ساخت کانتکست ===== */

// کانتکستِ خوانش در `reading-core.js` ساخته می‌شود (تابعِ خالص). این‌جا فقط چیزهایی که
// از دیتابیس و استیت می‌آیند جمع و به آن پاس داده می‌شوند — همان الگویی که
// `tools/reading-lab.mjs` برای شبیه‌سازیِ آفلاینِ همین مسیر استفاده می‌کند.
function readingCtxFor(user, spread, question, cards, focusKey) {
  return buildReadingCtx({
    user, spread, question, cards, focusKey, L,
    name: dispName(user), // فقط نام فارسیِ خودِ کاربر؛ نام تلگرام هرگز به مدل نمی‌رود
    kbOn: toneV2For(user.telegram_id),
    hideName: uxV2For(user.telegram_id),
    // ریکال کامل ارزان: در مقیاس ما کل تاریخچه‌ی مفید در کانتکست جا می‌شود — RAG لازم نیست
    prev: stmts.lastDelivered.all(user.telegram_id, 4),
  });
}

// 💸 دانلودِ فایلِ صوتیِ سؤال. **رایگان است** (Bot API تلگرام، نه OpenRouter) پس قاعده‌ی
// هزینه را نمی‌شکند؛ ولی چون بعد از کسرِ اعتبار اجرا می‌شود، شکستش باید به مسیرِ ریفاند
// برود نه به خوانشِ بی‌سؤال. برای همین در شکست null می‌دهد و صداکننده تصمیم می‌گیرد.
async function fetchQuestionAudio(r) {
  try {
    const link = await bot.telegram.getFileLink(r.question_audio);
    const res = await fetch(link.href);
    if (!res.ok) throw new Error(`telegram file ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    if (!buf.length || buf.length > MAX_VOICE_BYTES) throw new Error(`bad size ${buf.length}`);
    return { data: buf.toString('base64'), format: r.question_audio_fmt || 'mp3' };
  } catch (e) {
    logErr(`reading#${r.id} دانلودِ ویسِ سؤال شکست خورد:`, e.message);
    return null;
  }
}

// ═══ قاعده‌ی آهنینِ هزینه (بند ۹ ریشه) ═══
// هیچ فراخوانیِ پولیِ OpenRouter برای یک فال قبل از اینکه اعتبارِ کاربر کسر شده باشد.
// تنها نقطه‌ی کسر `unlock:`/`retryr:` است و هر دو بلافاصله status را 'started' می‌کنند،
// پس همین یک شرط کلِ قاعده را قفل می‌کند — و چون داخلِ خودِ تابعِ فراخوانی است، هر مسیرِ
// **آینده‌ای** هم که یادش برود، اینجا متوقف می‌شود (درسِ بند ۸ ریشه: گاردِ پراکنده دیر یا
// زود یک مسیر را جا می‌گذارد). فالِ رایگان (price=0) استثناست چون چیزی برای کسر ندارد.
/* ═══ 🪙 پرداخت در لحظه‌ی انتخابِ اندازه (UX v2.6) ═══
   وضعیتِ تازه‌ی `paid` = پول کم شده ولی کارت‌ها هنوز کشیده نشده‌اند. عمداً `started`
   نیست: `recoverOrphanReadings` هر فالِ `started` با `llm_json` خالی را در بوت ریفاند
   می‌کند، و چون حالا فاصله‌ی «پرداخت تا کشیدنِ کارت» شاملِ نوشتنِ سؤال و بُر و انتخاب
   است (چند دقیقه)، هر دیپلوی کاربرانِ وسطِ کار را ریفاند می‌کرد و دکمه‌ی `retryr:`
   دستشان می‌داد که روی `cards_json` خالی کرش می‌کند.

   کسر و ساختِ رکورد **در یک تراکنش**: یا هر دو یا هیچ‌کدام. اگر فقط کسر انجام می‌شد و
   insert می‌افتاد، پولِ کاربر بی‌ردپا می‌رفت (بند ۹ ریشه: هر ریال ردپای DB دارد). */
const payForSpread = db.transaction((uid, spread, focusKey) => {
  if (spread.price > 0 && stmts.deduct.run(spread.price, uid, spread.price).changes === 0) return 0;
  const id = Number(stmts.insertReading.run(
    uid, spread.id, spread.price, focusKey || '', '', '', '', '', '',
  ).lastInsertRowid);
  stmts.setReadingStatus.run('paid', id);
  return id;
});

/** لغوِ یک فالِ نیمه‌کاره. اگر پول داده شده، **کامل** برمی‌گردد. فالِ started/delivered
 *  هرگز دست نمی‌خورد. خروجی: مبلغی که برگشت (۰ یعنی چیزی برنگشت). */
function cancelReading(uid, readingId) {
  const r = readingId && stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid) return 0;
  if (r.status === 'pending_payment') { stmts.setReadingStatus.run('canceled', readingId); return 0; }
  if (r.status !== 'paid') return 0;
  if (r.price > 0) stmts.credit.run(r.price, uid);
  stmts.setReadingStatus.run('refunded', readingId);
  track(db, uid, EVENTS.REFUND, { reading_id: readingId, amount: r.price, reason: 'cancel' });
  return r.price;
}

function paidForReading(r) {
  return r.price === 0 || r.status === 'started';
}

async function callReadingLLM(readingId) {
  const r = stmts.getReading.get(readingId);
  if (!r) return null;
  if (!paidForReading(r)) {
    logErr(`❌ COST_GUARD reading#${readingId} status=${r.status} — فراخوانیِ LLM قبل از کسرِ اعتبار متوقف شد`);
    return null;
  }
  const user = getUser(r.user_id);
  const spread = SPREAD_BY_ID[r.type];
  const cards = JSON.parse(r.cards_json);

  // ── سؤالِ صوتی: یک فراخوانی، نه دو تا ──────────────────────────────────────
  // اگر سؤال ویس بوده، خودِ فایل کنارِ پرامپت می‌رود و مدل هم‌زمان می‌شنود و خوانش
  // می‌نویسد. اگر به هر دلیلی نشد (پرچم خاموش، دانلود خراب)، به مسیرِ رونویسی برمی‌گردیم
  // که **باز هم بعد از پرداخت** است؛ یعنی قاعده‌ی هزینه در هیچ شاخه‌ای نمی‌شکند.
  let audio = null;
  if (r.question_audio && !r.question) {
    const fetched = await fetchQuestionAudio(r); // یک دانلود، نه بیشتر
    if (fetched && AUDIO_DIRECT_ENABLED) {
      audio = fetched;                           // مسیرِ اصلی: یک فراخوانی برای کلِ کار
    } else if (fetched) {
      // پرچم خاموش: به مسیرِ رونویسی برمی‌گردیم. دو فراخوانی می‌شود ولی هر دو **بعد از**
      // پرداخت‌اند، پس قاعده‌ی هزینه نمی‌شکند (رول‌بک نباید قاعده را هم برگرداند).
      const txt = await orTranscribe(Buffer.from(fetched.data, 'base64'), fetched.format)
        .catch(e => { logErr(`reading#${readingId} رونویسیِ فالبک شکست خورد:`, e.message); return null; });
      if (txt?.trim()) {
        r.question = txt.trim().slice(0, 1500);
        stmts.setReadingQuestion.run(r.question, readingId, '');
      }
    }
  }
  // اگر ویس نه شنیده شد و نه رونویسی، **نباید** به مدل بگوییم «به فایلِ پیوست گوش کن»
  // (فایلی در کار نیست و مدل گیج می‌شود). به‌جایش صریح می‌گوییم سؤالِ مشخصی نداریم و
  // خوانش روی حوزه‌ی تمرکز بنا می‌شود — این خیلی بهتر از ریفاندِ کاربری است که پول داده.
  const questionText = r.question || (audio ? L.prompts.questionInAudio : L.prompts.questionMissing);
  const ctx = readingCtxFor(user, spread, questionText, cards, r.focus_area);
  // پرچمِ خاموش باید پرامپت را هم دقیقاً به حالتِ قبل برگرداند، نه فقط پیام را پنهان کند
  // (وگرنه رول‌بک نصفه است: هزینه‌ی توکنِ اضافه می‌ماند بدونِ هیچ فایده‌ای).
  const toneV2 = toneV2For(r.user_id);
  // در نسخه‌ی دومِ لحن **هر** فال جواب می‌دهد (حالتِ direct برای فال‌های تفسیری)، نه فقط
  // فال‌های تصمیم‌محور. پرچمِ DECISIVE_VERDICT_ENABLED همچنان کلیدِ خاموشیِ کلِ این بخش است.
  const v4 = v4For(r.user_id);
  // در v4 سرخط جای verdict را می‌گیرد: هر خوانش یک جوابِ صریح دارد و اعتبارسنجی‌اش
  // (`headlineOk`) همان قانونِ نشکستنی است — جوابِ بی‌جهت نمایش داده نمی‌شود.
  const wantVerdict = v4 ? null : (DECISIVE_VERDICT_ENABLED ? decisiveMode(spread, toneV2) : null);
  const labels = L.prompts.cardLabels(cards.length);
  const system = v4
    ? L.prompts.readerSystemV4(spread, labels)
    : toneV2
      ? L.prompts.readerSystemV2(spread, wantVerdict)
      : L.prompts.readerSystem(wantVerdict ? spread : { ...spread, decisive: null });
  // وقتی صدا همراه است، سؤال از خودِ فایل شنیده می‌شود؛ یک بلوکِ کوتاه به پرامپت اضافه
  // می‌شود که می‌گوید صدا **داده است نه دستور** (گاردِ prompt-injection، بند ۹ ریشه) و
  // متنِ سؤال را در `question_text` برگردان تا رکوردِ فال بدونِ فراخوانیِ دوم کامل شود.
  const systemFinal = audio ? `${system}\n${L.prompts.audioQuestionNote}` : system;
  const textPart = L.prompts.readingContext(ctx);
  const userMsg = audio
    ? [{ type: 'text', text: textPart }, { type: 'input_audio', input_audio: { data: audio.data, format: audio.format } }]
    : textPart;
  // DeepSeek صدا نمی‌فهمد، پس وقتی ورودی صوتی است فقط مدل‌های شنوا در برنامه می‌مانند.
  const plan = audio ? [FLASH, FLASH, FLASH] : undefined;
  // ۳ تلاش Flash → ۲ تلاش DeepSeek؛ خروجی فقط با JSON معتبر و کامل پذیرفته می‌شود.
  // برای فال‌های تصمیم‌محور یک شرطِ اضافه هم هست: جوابِ قاطعِ قابلِ اتکا (verdict).
  // ولی این شرط عمداً **کیفیِ** است نه حیاتی: اگر همه‌ی تلاش‌ها جوابِ مبهم دادند،
  // خوانشِ سالمِ آخر پذیرفته می‌شود و فقط بخشِ جواب نمایش داده نمی‌شود. وگرنه یک
  // «شاید»ِ مدل، کاربر را به مسیر ریفاند می‌انداخت که خیلی بدتر از نداشتنِ آن بخش است.
  //
  // 💸 بودجه‌ی retry فقط خرجِ چیزی می‌شود که کاربر واقعاً از نبودش ناراضی می‌شود.
  // باگِ اقتصادیِ نسخه‌ی قبل: سرخطِ بی‌فرمول **۵ بار** کلِ خروجی را بازتولید می‌کرد و
  // در آخر همان سرخط را نشان می‌داد؛ یعنی تا ۴ ریکوئستِ کامل برای صفر تغییر در چیزی
  // که کاربر می‌بیند. حالا سرخط یک تلاشِ اضافه می‌گیرد، بعد پذیرفته می‌شود.
  const HEADLINE_EXTRA_TRIES = 1;
  let parsed = null;      // خروجیِ کاملاً معتبر (شاملِ جوابِ قاطع، اگر لازم باشد)
  let fallback = null;    // آخرین خروجیِ سالم بدونِ جوابِ قاطع — شبکه‌ی ایمنیِ ضدِ ریفاند
  let headlineTries = 0;
  const res = await orChatResilient(systemFinal, userMsg, {
    maxTokens: spread.maxTokens,
    validate: (out) => {
      const obj = parseJsonLoose(out);
      if (v4) {
        // ساختارِ v4: تیزرِ هر کارت + سرخط + الگو + خوانشِ هر کارت + جمع‌بندی
        if (!checkV4Shape(obj, cards.length)) return false;
        // سرخطِ بی‌جهت یا بدونِ «ولی» پذیرفته نمی‌شود؛ ولی مثل verdict، شکستِ نهاییِ آن
        // هرگز به ریفاند نمی‌رسد — آخرین خروجیِ سالم بدونِ سرخط تحویل می‌شود.
        // فرمولِ سرخط «نرم» است: یک تلاشِ اضافه می‌دهیم، بعد همان را می‌پذیریم.
        if (!headlineOk(obj.headline) && headlineTries++ < HEADLINE_EXTRA_TRIES) { fallback = obj; return false; }
        // طفره‌رفتن اینجا **رد نمی‌شود**: بازتولیدِ کلِ فال برای یک جمله هم گران است
        // هم کند هم بی‌تضمین (همان پرامپت، همان احتمالِ خطا). به‌جایش بعد از پذیرش،
        // یک تعمیرِ نقطه‌ای روی همان فیلد اجرا می‌شود (`repair.js`).
        parsed = obj;
        return true;
      }
      const usable = obj && Array.isArray(obj.cards) && obj.cards.length >= cards.length && obj.narrative;
      if (!usable) return false;
      if (wantVerdict && !normalizeVerdict(obj.verdict, wantVerdict, { choiceLabels: spread?.choiceLabels })) { fallback = obj; return false; }
      parsed = obj;
      return true;
    },
  }, plan);
  if (!parsed && fallback) {
    logErr(`reading#${readingId} جوابِ قاطع بعد از همه‌ی تلاش‌ها مبهم ماند — خوانش بدونِ بخشِ جواب تحویل می‌شود`);
    parsed = fallback;
  }
  if (!parsed) { logErr(`reading#${readingId} همه‌ی تلاش‌ها شکست خورد (REFUND path)`); return null; }
  // فیلدهای اختیاریِ جامانده فقط شمرده می‌شوند (نه retry): اگر نرخشان بالا رفت باید
  // بفهمیم، وگرنه «اختیاری» بی‌صدا به «همیشه غایب» تبدیل می‌شود.
  if (v4) {
    const soft = softMissesV4(parsed);
    if (soft.length) log(`reading#${readingId} فیلدِ اختیاریِ جامانده: ${soft.join(', ')}`);
    if (!headlineOk(parsed.headline)) log(`reading#${readingId} سرخط فرمول را ندارد (پذیرفته شد)`);
    // تعمیرِ نقطه‌ای: فقط اگر تشخیصِ هاردکد چیزی پیدا کند، و فقط یک فراخوانیِ کوچک.
    const rep = await repairDefects(parsed, orChatResilient, { tag: `reading#${readingId}` });
    parsed = rep.llm;
    const evLeft = evasionIn(v4Text(parsed));
    if (evLeft) logErr(`reading#${readingId} طفره‌رفتن «${evLeft}» بعد از تعمیر هم ماند (پذیرفته شد)`);
  }
  log(`reading#${readingId} آماده شد با ${res?.model || 'fallback'}${audio ? ' (ورودی صوتی، تک‌فراخوانی)' : ''}`);
  // متنِ سؤالِ ویس از همان خروجی برداشته می‌شود (نه یک فراخوانیِ دوم). شرطِ `question=''`
  // در خودِ UPDATE است تا اگر قبلاً متنی ثبت شده بود بازنویسی نشود.
  if (audio && parsed.question_text) {
    stmts.setReadingQuestion.run(String(parsed.question_text).slice(0, 1500), readingId, '');
  }
  stmts.setReadingLlm.run(JSON.stringify(parsed), String(parsed.summary || '').slice(0, 300), readingId);
  return parsed;
}

// ⛔️ `startPrefetch` حذف شد (v3.4.0). پیش‌فراخوانی خوانش را **قبل** از پی‌وال شروع می‌کرد،
// یعنی برای هر کاربری که موجودی داشت ولی سرِ پی‌وال منصرف می‌شد، هزینه‌ی یک فالِ کامل را
// می‌دادیم و هیچ درآمدی نمی‌گرفتیم. «توانِ پرداخت» با «تصمیمِ پرداخت» یکی نیست.
// جایش: خوانش در `awaitReadingLLM` صدا زده می‌شود که فقط از مسیرِ بعد از کسرِ اعتبار
// می‌آید، و انتظارِ کاربر با همان لودینگِ زنده‌ی `waitLLMWithLoading` پوشانده می‌شود.
// نتیجه‌ی LLM (منبع حقیقت readings.llm_json؛ اگر ری‌استارت شده بود دوباره صدا می‌زند)
async function awaitReadingLLM(uid, readingId) {
  const r = stmts.getReading.get(readingId);
  if (r?.llm_json) { try { return JSON.parse(r.llm_json); } catch {} }
  const result = await callReadingLLM(readingId);
  if (result) return result;
  const r2 = stmts.getReading.get(readingId);
  if (r2?.llm_json) { try { return JSON.parse(r2.llm_json); } catch {} }
  return null;
}

// بازیابیِ بوت: فال‌هایی که وسط فراخوانی LLM با ری‌استارت یتیم شدند (status=started ولی llm_json خالی)
// → برگشت کامل مبلغ + پیام + دکمه‌ی تلاش مجدد. در لحظه‌ی بوت هیچ فراخوانی LLM در جریان نیست پس امن است
// (پول کاربر هرگز در حالت نامعلوم نمی‌ماند — بند ۹ CLAUDE.md).
function recoverOrphanReadings() {
  let orphans = [];
  try { orphans = db.prepare("SELECT id, user_id, price FROM readings WHERE status='started' AND llm_json=''").all(); }
  catch (e) { logErr('recoverOrphan query:', e.message); return; }
  for (const r of orphans) {
    try {
      if (r.price > 0) stmts.credit.run(r.price, r.user_id);
      stmts.setReadingStatus.run('refunded', r.id);
      track(db, r.user_id, EVENTS.REFUND, { reading_id: r.id, amount: r.price, reason: 'restart' });
      const kb = Markup.inlineKeyboard([[Markup.button.callback(L.buttons.retry, `retryr:${r.id}`)]]);
      bot.telegram.sendMessage(r.user_id, L.reading.refunded(curOf(r.user_id)), { reply_markup: kb.reply_markup }).catch(() => {});
    } catch (e) { logErr('recoverOrphan reading#' + r.id, e.message); }
  }
  if (orphans.length) log(`♻️ بازیابی بوت: ${orphans.length} فالِ یتیمِ پرداخت‌شده refund شد`);
}

// 🪙 فالِ **پرداخت‌شده‌ای که هرگز کارت نکشید** (UX v2.6). از وقتی کسر به لحظه‌ی انتخابِ
// اندازه آمده، بینِ «پول داده شد» و «کارت‌ها کشیده شد» چند دقیقه فاصله است و کاربر ممکن
// است وسطش برای همیشه برود. آن رکورد `paid` می‌ماند: پول رفته، محصولی نرسیده.
// عمداً **فقط رکوردهای کهنه‌تر از یک شبانه‌روز** ریفاند می‌شوند — نه در بوت و نه زودتر —
// چون استیت و سشن در DB اند و کاربرِ وسطِ نوشتنِ سؤال بعد از ری‌استارت ادامه می‌دهد؛
// ریفاندِ زودهنگام فالش را از زیرِ پایش می‌کشید و بعد فالِ مجانی تحویل می‌داد.
function refundAbandonedPaidReadings() {
  let rows = [];
  try {
    rows = db.prepare(
      "SELECT id, user_id, price FROM readings WHERE status='paid' AND created_at < unixepoch()-86400",
    ).all();
  } catch (e) { logErr('refundAbandoned query:', e.message); return; }
  for (const r of rows) {
    try {
      if (r.price > 0) stmts.credit.run(r.price, r.user_id);
      stmts.setReadingStatus.run('refunded', r.id);
      track(db, r.user_id, EVENTS.REFUND, { reading_id: r.id, amount: r.price, reason: 'abandoned' });
      bot.telegram.sendMessage(r.user_id, L.reading.refundedOnCancel(r.price, curOf(r.user_id))).catch(() => {});
    } catch (e) { logErr('refundAbandoned reading#' + r.id, e.message); }
  }
  if (rows.length) log(`♻️ ${rows.length} فالِ پرداخت‌شده‌ی رهاشده ریفاند شد`);
}

/* ===== 8) Bot ===== */
const bot = new Telegraf(BOT_TOKEN, { handlerTimeout: OR_TIMEOUT_MS });
let BOT_USERNAME = '';

// گارد خطای سراسری: هیچ خطایی نباید بی‌صدا فلو را بکشد — لاگ کامل + پیام عذرخواهی به کاربر
bot.catch(async (err, ctx) => {
  logErr(`global error [${ctx.updateType}] uid=${ctx.from?.id} state=${ctx.from ? getState(ctx.from.id) : '-'}:`, err.stack || err.message);
  try { await ctx.reply(L.errors.generic); } catch {}
});

// ثبتِ مسیرِ ریز — **باید قبل از همه‌ی هندلرها** ثبت شود (میدل‌ورِ تلگراف ترتیبی اجرا می‌شود).
// برچسبِ دکمه‌های کیبوردِ ماندگار را می‌دهیم تا «زدنِ دکمه» از «تایپِ آزاد» تفکیک شود، و
// نامِ نمایشیِ کاربر را می‌دهیم تا از متنِ پیام حذف شود و کلیدِ صفحه برای همه یکی بماند.
const KB_LABELS = new Set([
  L.buttons.daily, L.buttons.reading, L.buttons.wallet, L.buttons.coinShop, L.buttons.inviteMain,
  L.buttons.freeMenu, L.buttons.resetTest, L.support?.button, '🔄 ریست ربات (تست)',
  // برچسب‌های کهنه‌ی کیبورد — تا تپِ کیبوردهای کش‌شده هم «دکمه» شمرده شود، نه «تایپِ آزاد»
  '📤 معرفی دوستان', '🍀 کارت شانس (استخراج الماس)', '🍀 کارت شانس (الماس رایگان)',
  '💎 کیف الماس', '💎 الماس فروشی',
  L.buttons.dailyOneCard, L.buttons.luckyMain,   // UX v2.1
].filter(Boolean));
registerJourney(bot, {
  db,
  enabled: JOURNEY_ENABLED,
  // تپ‌های **تستر** هم مثل ادمین از قیف‌های محصولی بیرون می‌مانند: او دارد فیچر را
  // می‌آزماید، نه رفتارِ واقعیِ کاربر را نشان می‌دهد. (این «اختیار» نیست، بهداشتِ دیتاست.)
  isAdmin: isTester,
  isButtonLabel: (t) => KB_LABELS.has(t),
  redact: (ctx) => { try { return [dispName(getUser(ctx.from?.id))]; } catch { return []; } },
});

/* ---------- آنبوردینگ و /start ---------- */
// هدیه‌ی خوش‌آمد — write-once با ستونِ welcome_bonus_at (گاردِ اتمیک: فقط وقتی هنوز NULL
// است هم اعتبار می‌دهد هم مهر می‌زند، پس چندبار /start یا ری‌استارت دوباره پول نمی‌دهد).
function grantWelcomeBonus(uid) {
  try {
    const done = stmts.claimWelcomeBonus.run(uid).changes;
    if (!done) return false;
    const wb = welcomeBonusFor(uid);
    stmts.credit.run(wb, uid);
    track(db, uid, 'credit_granted', { amount: wb, kind: 'welcome' });
    return true;
  } catch (e) { logErr('welcome bonus:', e.message); return false; }
}

/* ---------- 🔑 گیتِ عضویت در کانال (v2.7.0) ---------- */
// needsGate: **باریک‌ترین شرطِ ممکن** تا هیچ کاربرِ فعلی گیت نبیند (بند ۲ج/۲). ملاک را
// «هدیه‌ی خوش‌آمد را گرفته یا نه» گذاشتیم، نه welcomed: کاربری که وسط آنبوردینگ رها کرده
// هم هدیه‌اش را گرفته، پس نباید حالا بابتِ هدیه‌ای که دارد دوباره شرط بگذاریم.
function needsGate(user) {
  if (!JOIN_GATE_ENABLED) return false;
  if (!user) return false;
  return !user.joined_gate_at && !user.welcome_bonus_at && !user.welcomed;
}

const gateKeyboard = () => Markup.inlineKeyboard([
  [Markup.button.url(L.buttons.gateOpenChannel, GATE_CHANNEL_URL)],
  [Markup.button.callback(L.buttons.gateCheck, 'gate:check')],
]);

// isChannelMember: تنها منبعِ حقیقتِ عضویت. **fail-open عمدی**: اگر تلگرام خطا داد (ربات از
// ادمینیِ کانال افتاد، کانال عوض شد، شبکه قطع بود) کاربر را رد می‌کنیم تا جلو برود. اگر
// fail-closed بود، یک خطای سمتِ ما کلِ ثبت‌نامِ کاربرهای جدید را بی‌صدا می‌خشکاند و تا
// وقتی کسی شکایت نکند نمی‌فهمیدیم. خطا با پیشوندِ قابلِ grep لاگ می‌شود.
async function isChannelMember(ctx, uid) {
  try {
    const m = await ctx.telegram.getChatMember(GATE_CHANNEL, uid);
    if (GATE_OK_STATUS.has(m?.status)) return true;
    if (m?.status === 'restricted') return m.is_member === true;
    return false; // left / kicked
  } catch (e) {
    logErr(`❌ GATE_CHECK ${GATE_CHANNEL}:`, e.message);
    return true; // fail-open: خطای ما نباید راهِ کاربر را ببندد
  }
}

// آیا این کاربر در شاخه‌ی «اول آمار» است؟ (آزمایشِ intro_order)
// variant() به‌خاطرِ ab_exposures چسبنده است، پس صدا زدنش در دو نقطه‌ی فلو همیشه یک جواب
// می‌دهد و کاربر هرگز یک بلوک را دو بار یا هیچ‌کدام را نمی‌بیند.
const statFirstFor = (uid) => variant(db, uid, AB_INTRO_ORDER) === 'stat_first';

// نمایشِ گیت: پیامِ معرفی (کاهشِ dropِ لحظه‌ی ورود) و بعد دعوت به عضویت.
async function showGate(ctx, uid) {
  setState(uid, 'gate_join');
  setSession(uid, null); // چیزی از فلوی قبلی نباید وارد آنبوردینگ شود
  await ctx.reply(L.onboarding.gateIntro(statFirstFor(uid)), Markup.removeKeyboard());
  await typing(ctx, PACE_S);
  await ctx.reply(L.onboarding.gateJoin(welcomeBonusFor(uid), curOf(uid), uxV2For(uid)), gateKeyboard());
}

// بعد از تأییدِ عضویت: دقیقاً همان آنبوردینگِ قبلی (هدیه → پرسیدنِ نام). تک‌منبع، تا مسیرِ
// گیت‌دار و مسیرِ بدونِ گیت هرگز از هم واگرا نشوند.
async function startOnboarding(ctx, uid) {
  grantWelcomeBonus(uid);
  await ctx.reply(L.onboarding.welcomeGift(welcomeBonusFor(uid), curOf(uid), uxV2For(uid)), Markup.removeKeyboard());
  await typing(ctx, PACE_S);
  // قدم صفر آنبوردینگ: نام فارسیِ خودِ کاربر (نام تلگرام ممکن است انگلیسی/نامفهوم باشد و
  // مدل تکرارش کند). استیتِ ورودی است، پس عمداً هیچ دکمه‌ای ندارد (قرارداد ۹ب).
  setState(uid, 'onboard_name');
  setSession(uid, null);
  await ctx.reply(L.onboarding.askName(uxV2For(uid)), { parse_mode: 'Markdown', ...Markup.removeKeyboard() });
}

async function handleStart(ctx) {
  const uid = ctx.from.id;
  const { isNew } = upsertUser(ctx);
  const user = getUser(uid);

  // اتریبیوشن: رویداد start برای هر /start (کمپین برگشتی هم دیده شود) + first_source/first_version فقط کاربر جدید.
  //
  // ⚠️ payload فقط از یک پیامِ واقعیِ `/start` خوانده می‌شود. `handleStart` از دو جای دیگر هم
  // صدا زده می‌شود (دکمه‌ی ریستِ ادمین، و کاربرِ ناتمامی که متن می‌فرستد) و آن‌جا `ctx.message.text`
  // اصلاً /start نیست. فالبکِ قبلی «کلمه‌ی دومِ هر متنی» را payload می‌گرفت: ریستِ ادمین
  // `payload:"ریست"` ثبت می‌کرد و کاربرِ ناتمام کلمه‌ی دومِ حرفش را. یعنی اتریبیوشن با متنِ
  // تصادفی آلوده می‌شد (باگِ دیده‌شده در لاگ ۱۴۰۵/۰۵/۱۳).
  const isStartCmd = /^\/start(?:@\S+)?(?:\s|$)/.test(ctx.message?.text || '');
  const payload = (ctx.startPayload ?? (isStartCmd ? ctx.message.text.split(/\s+/)[1] : '') ?? '').trim();
  captureStart(db, uid, payload, isNew, PRODUCT_VERSION);

  // رفرال: /start ref_<id>
  const refMatch = payload.match(/^ref_(\d+)$/);
  if (refMatch && isNew) {
    const refId = parseInt(refMatch[1], 10);
    if (refId !== uid && getUser(refId)) {
      stmts.insertReferral.run(refId, uid);
      stmts.setReferredBy.run(refId, uid);
    }
  }

  if (!user.welcomed) {
    // 🔑 گیتِ عضویت مقدم بر هدیه است: هدیه لحظه‌ی تأییدِ عضویت واریز می‌شود، پس عضویت
    // «شرطِ گرفتنِ هدیه» است نه هزینه‌ای اضافه. کاربرِ فعلی هرگز این شاخه را نمی‌بیند
    // (needsGate روی هدیه‌ی گرفته‌نشده شرط دارد).
    if (needsGate(user)) {
      track(db, uid, 'gate_shown', { ch: GATE_CHANNEL });
      return showGate(ctx, uid);
    }
    // v2.0.0 — اول ارزش، بعد اسم: پیامِ اول خوش‌آمد + هدیه‌ی اعتبار (دقیقاً بهای یک فالِ
    // کامل) را می‌دهد، پیامِ دوم تازه نام را می‌پرسد. قبلاً اولین چیزی که کاربر می‌دید یک
    // درخواست بود، نه یک ارزش.
    return startOnboarding(ctx, uid);
  }

  // کاربر برگشتی
  setState(uid, 'idle');
  setSession(uid, null);
  // UX v2: موجودی از پیامِ بازگشت حذف شد — عددِ پول اولین چیزی نباشد که کاربر می‌بیند.
  let msg = uxV2For(uid)
    ? L.returning.greetingV2(dispName(user))
    : L.returning.greeting(dispName(user), getBalance(uid), curOf(uid));
  const last = stmts.lastDelivered.all(uid, 1)[0];
  if (user.next_milestone_at && user.next_milestone_at <= Date.now() / 1000 && last?.summary) {
    try { msg += L.returning.milestoneHook(JSON.parse(last.llm_json)?.next_milestone?.text || last.summary); } catch {}
  } else if (user.last_daily_date !== tehranToday()) {
    msg += L.returning.dailyReminder;
  }
  stmts.setKbShown.run(uid);
  await ctx.reply(msg, mainKeyboard(ctx.from.id));
}
bot.start(handleStart);

// دکمه‌ی «عضو شدم، بررسی کن». دو نتیجه بیشتر ندارد: یا عضو است و بلافاصله هدیه و ادامه‌ی
// فلو را می‌گیرد، یا پاپ‌آپِ «تایید نشده» می‌بیند و روی همان صفحه می‌ماند (بدونِ پیامِ جدید،
// تا چت شلوغ نشود). دوبار-تپ بی‌خطر است چون claimGate اتمیک است و grantWelcomeBonus write-once.
bot.action('gate:check', async (ctx) => {
  const uid = ctx.from.id;
  const user = getUser(uid);
  // دکمه‌ی کهنه یا کاربری که قبلاً رد شده: فقط پاسخِ خالی، بدونِ هیچ رفتارِ عجیب
  if (!user || !needsGate(user)) return ctx.answerCbQuery().catch(() => {});
  const okMember = await isChannelMember(ctx, uid);
  track(db, uid, 'gate_check', { ok: okMember ? 1 : 0 });
  if (!okMember) {
    return ctx.answerCbQuery(L.onboarding.gateNotJoined, { show_alert: true }).catch(() => {});
  }
  await ctx.answerCbQuery().catch(() => {});
  if (!stmts.claimGate.run(uid).changes) return; // ضدِ دوبار-تپ (یکی از دو تپ برنده است)
  track(db, uid, 'gate_passed', { ch: GATE_CHANNEL });
  try { await ctx.editMessageReplyMarkup(undefined); } catch {} // دکمه‌ها بعد از عبور می‌روند
  return startOnboarding(ctx, uid);
});

/* 🔑 میدل‌ورِ گیت — عمداً یک نقطه، نه گارد روی تک‌تکِ هندلرها.
   درسِ بند ۸ ریشه: هر جایی که باید دستی به ده‌ها هندلر اضافه شود، دیر یا زود یکی جا می‌ماند
   (و مسیرهای سرد را CI نمی‌بیند). این‌جا یک میدل‌ورِ واحد قبل از همه‌ی هندلرها می‌نشیند، پس
   هیچ مسیری، حتی مسیرهایی که در آینده اضافه می‌شوند، از قلم نمی‌افتد.
   عبورِ آزاد: /start (تا خودِ گیت دوباره نشان داده شود)، خودِ دکمه‌ی gate، پشتیبانی
   (بند ۶ج: راهِ فرارِ کاربرِ گیرکرده هرگز بسته نمی‌شود)، و **ریستِ ادمین**.
   چرا ریست: `bot.hears(resetTest)` و `/reset` بعد از این میدل‌ور ثبت می‌شوند، پس بدونِ
   این استثنا ادمینی که وسطِ گیت است نمی‌تواند ریست کند و گیت را دوباره تست کند — دقیقاً
   همان چیزی که مالک دید (به‌جای ریست، پیامِ یادآوریِ گیت گرفت). بند ۶ب می‌گوید این دکمه
   «همیشه» در دسترسِ ادمین است. برای کاربرِ عادی بی‌خطر است چون `doReset` خودش `isAdmin` را چک می‌کند. */
if (JOIN_GATE_ENABLED) {
  // دستورهای همیشه-آزاد. تلگرام `/cmd@botname` هم می‌فرستد، پس با فرمانِ خالص مقایسه می‌کنیم.
  const GATE_FREE_CMD = new Set(['/start', '/support', '/reset']);
  const GATE_FREE_TEXT = new Set(
    [L.support?.button, L.buttons.resetTest, '🔄 ریست ربات (تست)'].filter(Boolean));
  bot.use(async (ctx, next) => {
    try {
      const uid = ctx.from?.id;
      if (!uid) return next();
      // فقط **اقدامِ واقعیِ کاربر** گیت می‌شود. آپدیت‌های سرویسیِ تلگرام (my_chat_member وقتی
      // کاربر کانال را ترک/عضو می‌کند یا ربات را بلاک/آنبلاک می‌کند، edited_message، …) پیام
      // ندارند و قبلاً به‌اشتباه «اقدام» حساب می‌شدند: کاربر بدونِ اینکه کاری کرده باشد یادآوریِ
      // گیت می‌گرفت. باگِ واقعی و دیده‌شده — در لاگ سه بار پشت‌سرهم روی my_chat_member تکرار شد.
      if (!ctx.message && !ctx.callbackQuery) return next();
      const data = ctx.callbackQuery?.data || '';
      if (data.startsWith('gate:')) return next();
      const text = ctx.message?.text?.trim() || '';
      const cmd = text.split(/[\s@]/)[0];
      if (GATE_FREE_CMD.has(cmd) || GATE_FREE_TEXT.has(text)) return next();
      if (!needsGate(getUser(uid))) return next();
      // گیت‌شده: روی دکمه پاپ‌آپ، روی پیام یادآوریِ کوتاه + همان دو دکمه (هیچ صفحه‌ای بن‌بست نیست)
      if (ctx.callbackQuery) {
        return ctx.answerCbQuery(L.onboarding.gateNotJoined, { show_alert: true }).catch(() => {});
      }
      return ctx.reply(L.onboarding.gateReminder, gateKeyboard()).catch(() => {});
    } catch (e) {
      logErr('gate middleware:', e.message);
      return next(); // هیچ خطایی در گیت نباید ربات را قفل کند
    }
  });
}

// پاک‌سازیِ سبکِ نامِ ورودی: خط اول، بدون ایموجی/کاراکترهای کنترلی، حداکثر ۳۲ کاراکتر
function cleanName(raw) {
  return String(raw || '')
    .split('\n')[0]
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}\u{200D}]/gu, '')
    .replace(/[<>]/g, '')
    .trim()
    .slice(0, 32)
    .trim();
}

// تکمیل آنبوردینگ بعد از گرفتن نام: ذخیره‌ی نام، خوش‌آمدِ شخصی‌شده، سپس پرسش حوزه‌ی تمرکز.
async function finishNameOnboarding(ctx, rawName) {
  const uid = ctx.from.id;
  const name = cleanName(rawName);
  if (!name) return ctx.reply(L.onboarding.askNameRetry);
  stmts.setDisplayName.run(name, uid);
  stmts.setWelcomed.run(uid);
  setSession(uid, null);
  // همان شاخه‌ی intro_order: بلوکی که در پیامِ اول نیامده این‌جا می‌آید (مکملِ هم، نه تکرار)
  // ⚠️ این پیام عمداً **هیچ reply_markup ای ندارد**، به دو دلیلِ جدا:
  //   ۱) منوی پایین صادر نمی‌شود، چون قراردادِ مالک فقط دو نقطه دارد و آنبوردینگ هیچ‌کدام
  //      نیست (پایینِ همین فایل مستند شده).
  //   ۲) removeKeyboard هم فرستاده نمی‌شود، چون مستنداتِ Bot API می‌گوید کلاینت با آن
  //      «کیبوردِ سفارشی را برمی‌دارد و letter-keyboard پیش‌فرض را نشان می‌دهد» — یعنی
  //      کیبوردِ تایپِ گوشی را باز نگه می‌داشت و نصفِ صفحه را می‌گرفت. کیبوردِ سفارشی از
  //      قبل در `askName` برداشته شده، پس این تکرار بی‌اثر ولی پرعارضه بود.
  await ctx.reply(L.onboarding.welcome(name, statFirstFor(uid), uxV2For(uid)));
  // ⚠️ این‌جا قبلاً به دعوت‌شده وعده‌ی «هدیه‌ی دعوت» داده می‌شد. آن وعده از پایه غلط بود:
  // پاداشِ دعوت فقط مالِ دعوت‌کننده است. حالا که چیزی برای گفتن نیست، پیام هم حذف شد؛
  // یک پیامِ کمتر در آنبوردینگ، و هیچ وعده‌ای که بعداً عمل نشود.
  await typing(ctx, PACE_S);
  // UX v2: ماهِ تولد جای حوزه‌ی تمرکز را گرفت. حوزه‌ی تمرکز کاربر را از همان اول به یک
  // موضوع بایاس می‌کرد؛ ماهِ تولد عوض نمی‌شود و کارتِ روز را برای همیشه شخصی می‌کند.
  if (uxV2For(uid)) {
    setState(uid, 'onboard_month');
    return askBirthMonth(ctx);
  }
  setState(uid, 'onboard_focus');
  await ctx.reply(L.onboarding.askFocus, Markup.inlineKeyboard(
    L.buttons.focusOptions.map(([key, label]) => [Markup.button.callback(label, `focus:${key}`)])
  ));
}

// همان مسیرِ پایانیِ آنبوردینگ برای هر دو نسل (حوزه‌ی تمرکز و ماهِ تولد): استیت، رویداد،
// و دو دکمه‌ی ورود. عمداً یک تابع است تا اگر فردا این پایان عوض شد، یک جا عوض شود.
async function finishOnboarding(ctx, uid, props) {
  await typing(ctx, PACE_M);
  setState(uid, 'idle');
  track(db, uid, EVENTS.ONBOARD_DONE, props);
  // UX v2.1: بلافاصله بعد از ماهِ تولد، «از کجا شروع کنیم؟» با **همان** منوی فال.
  // عمداً بدونِ فالِ رایگان (تصمیمِ مالک): فالِ رایگان فقط از کیبوردِ اصلی گرفته می‌شود،
  // وگرنه اولین انتخابِ کاربرِ تازه همیشه رایگان می‌شود و هیچ‌وقت فالِ واقعی را نمی‌بیند.
  if (uxV2For(uid)) {
    setState(uid, 'choose_spread');
    // UX v2.5: دوباره **یک پیام** — چهار دکمه زیرِ خودِ «از کجا شروع کنیم؟ 📌» می‌نشینند و
    // «کدوم فال رو انتخاب می‌کنی؟» این‌جا (و فقط این‌جا) نمی‌آید. کیبوردِ ماندگار جلوتر، روی
    // پیامِ «خوش اومدی»، تحویل شده است.
    return ctx.reply(L.reading.startWhere, Markup.inlineKeyboard(falMenuKb(uid)));
  }
  const ctaRows = [
    [Markup.button.callback(L.buttons.dailyAfterOnboard, 'daily_go')],
    [Markup.button.callback(L.buttons.startPopular(), 'spread:love')],
  ];
  if (variant(db, uid, 'onboard_cta_order') === 'reading_first') ctaRows.reverse();
  ctaRows.push([Markup.button.callback(L.buttons.allSpreads, 'onboard_allspreads')]);
  await ctx.reply(L.onboarding.expectations(toneV2For(uid)), Markup.inlineKeyboard(ctaRows));
}

bot.action(/^bmonth:(\d{1,2})$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const m = parseInt(ctx.match[1], 10);
  if (!(m >= 1 && m <= 12)) return;
  stmts.setBirthMonth.run(m, uid);
  const inOnboarding = getState(uid) === 'onboard_month';
  // تأیید **روی همان پیامِ سؤال** ادیت می‌شود، نه یک پیامِ جدید (تصمیمِ مالک): دوازده
  // دکمه محو می‌شوند و جایشان یک خطِ کوتاه می‌نشیند، پس چت شلوغ نمی‌ماند.
  // اگر ادیت نشد (پیامِ خیلی قدیمی یا حذف‌شده) به پیامِ جدا برمی‌گردیم تا کاربر بی‌جواب نماند.
  const saved = L.onboarding.birthMonthSaved(monthFa(m));
  try { await ctx.editMessageText(saved); }
  catch { await ctx.reply(saved).catch(() => {}); }
  // 🎯 خارج از آنبوردینگ، ماهِ تولد فقط یک قدمِ میانی بوده که جلوی نیتِ کاربر را گرفت.
  // پس همان نیت ادامه داده می‌شود، نه اینکه بی‌صدا return کنیم (باگِ v3.9.0 تا v3.17.0).
  if (!inOnboarding) { await replayIntent(ctx, uid); return; }
  // UX v2.2 (تصمیمِ صریحِ مالک): پیامِ جداگانه‌ی «از دکمه‌های پایین شروع کن» اینجا حذف
  // شد — لزومی ندارد، چون `finishOnboarding` همین‌جا کاربر را مستقیم توی منوی فال
  // می‌گذارد (دکمه‌های اینلاین)، و کیبوردِ اصلی خودش اولین بار که `ensureMenu` صدا زده
  // می‌شود (پایانِ اولین فال/کارتِ روز/کارتِ شانس) بی‌سروصدا ظاهر می‌شود.
  await finishOnboarding(ctx, uid, { birth_month: m });
});

bot.action(/^focus:(\w+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const key = ctx.match[1];
  stmts.setFocus.run(key, uid);
  const inOnboarding = getState(uid) === 'onboard_focus';
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.onboarding.focusSaved(L.focusFa[key] || key));
  if (inOnboarding) {
    await typing(ctx, PACE_M);
    setState(uid, 'idle');
    track(db, uid, EVENTS.ONBOARD_DONE, { focus: key });
    // دو مسیر ورود: مزه‌ی سریع (کارت روز) یا تجربه‌ی کامل — آزمایش onboard_cta_order ترتیب را تست می‌کند
    // (تا وقتی آزمایش از داشبورد running نشود، variant() همیشه control برمی‌گرداند = رفتار فعلی)
    const ctaRows = [
      [Markup.button.callback(L.buttons.dailyAfterOnboard, 'daily_go')],
      [Markup.button.callback(L.buttons.startPopular(), 'spread:love')],
    ];
    if (variant(db, uid, 'onboard_cta_order') === 'reading_first') ctaRows.reverse();
    // دکمه‌ی سوم: مشاهده‌ی همه‌ی فال‌ها (زیرِ دو دکمه‌ی اصلی؛ همان پیام به کاتالوگ ادیت می‌شود)
    ctaRows.push([Markup.button.callback(L.buttons.allSpreads, 'onboard_allspreads')]);
    await ctx.reply(L.onboarding.expectations(toneV2For(uid)), Markup.inlineKeyboard(ctaRows));
    // کیبورد اصلی *بعد* از پیام «یه قرار کوچیک» آشکار می‌شود (نه قبلش) — تلگرام اجازه‌ی
    // یک reply_markup در هر پیام را می‌دهد، پس آشکارسازی کیبورد یک پیام کوتاه جدا لازم دارد.
    await typing(ctx, PACE_S);
    stmts.setKbShown.run(uid);
    await ctx.reply(L.onboarding.keyboardReveal, mainKeyboard(uid));
  } else {
    // تغییر تمرکز وسط فلوی فال
    patchSession(uid, { focusKey: key });
    setState(uid, 'await_question');
    const s = getSession(uid);
    const spread = SPREAD_BY_ID[s.spreadId];
    if (spread) await ctx.reply(L.reading.askQuestion(toneV2For(uid)), { parse_mode: 'Markdown' });
  }
});

/* ═══════════ کارتِ روز — نسل دوم (UX v2) ═══════════
   سه تفاوتِ بنیادی با نسل اول:
     ۱) کارت را **کاربر** انتخاب می‌کند، نه کد. حسِ «خودم کشیدم» بخشِ اصلیِ این آیین است.
     ۲) متن از **گنجینه** می‌آید، نه LLM. کارتِ روز رایگان است و روزی یک بار برای هر
        کاربر اجرا می‌شود، یعنی تنها مسیری که هزینه‌اش با تعدادِ کاربر خطی بالا می‌رود.
     ۳) متن به **ماهِ تولد** گره خورده، نه به «حوزه‌ی تمرکز» که دیگر پرسیده نمی‌شود.
   عدم‌تکرار در دو لایه: کارت (۷ روز) و نسخه‌ی تفسیر (۳ نسخه per کارت per ماه). */

// روزِ تهران، n روز قبل. برای پنجره‌ی «۷ روزِ اخیر».
const tehranDaysAgo = (n) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran' })
  .format(new Date(Date.now() - n * 86400_000));

// گریدِ رو-به-پشتِ کارتِ روز. اندازه‌اش به اندازه‌ی حوضچه‌ی واجدِ شرایط است (سقفِ ۲۴)،
// چون دکمه‌ای که به هیچ کارتی نمی‌رسد یعنی دروغ گفتن به کاربر.
function dailyGridKb(n, picked = -1) {
  const rows = [];
  for (let i = 0; i < n; i += 4) {
    rows.push(Array.from({ length: Math.min(4, n - i) }, (_, c) =>
      Markup.button.callback(i + c === picked ? '✨' : '🂠', `dpick:${i + c}`)));
  }
  return Markup.inlineKeyboard(rows);
}

async function dailyCardV2(ctx, uid, user, today) {
  // ماهِ تولد لازم است و کاربرانِ قدیمی ندارندش؛ همان‌جا پرسیده می‌شود.
  // 🐛 تا v3.17.0 این‌جا نیتِ کاربر **بی‌صدا دور ریخته می‌شد**: ماه را می‌پرسیدیم، کاربر
  // جواب می‌داد، و هندلرِ `bmonth:` چون `inOnboarding` نبود همان‌جا return می‌کرد. یعنی
  // کارتی که کاربر برایش دکمه زده بود هرگز نمی‌آمد و هیچ‌کس هم نمی‌گفت دوباره بزن.
  // قاعده‌ی مالک: «وقتی بابتِ رسیدن به چیزی یک قدمِ میانی می‌خوریم، بعد از آن قدم باید
  // همان چیزی بیاید که می‌خواستیم». پس نیت ثبت می‌شود و `bmonth:` ادامه‌اش می‌دهد.
  if (!user.birth_month) {
    setIntent(uid, INTENT.DAILY);
    await ctx.reply(L.daily.needBirthMonth);
    return askBirthMonth(ctx);
  }
  // اگر کاربر تا حالا فقط ۲ یا ۳ بار فال گرفته، همان ۲ یا ۳ کارت حذف می‌شوند: LIMIT
  // خودش کمتر بودنِ ردیف‌ها را درست هندل می‌کند.
  const recent = stmts.recentDailyDraws.all(uid, NO_REPEAT_DRAWS).map(r => r.card_key);
  const pool = eligibleCards(Object.keys(CARD_BY_KEY), user.birth_month, recent);
  if (!pool.length) {
    // گنجینه‌ی این ماه هنوز نوشته نشده. صادق و بدونِ فالبکِ LLM (قاعده‌ی آهنین).
    // ⚠️ ولی **بی‌دکمه نه**: امروز فقط دو ماه از دوازده ماه گنجینه دارند، یعنی این شاخه
    // پرتکرارترین پایانِ مسیرِ رایگان است. `ensureMenu` در دنیای الماس no-op است، پس
    // نسخه‌ی قبلی این‌جا یک صفحه‌ی بدونِ هیچ قدمِ بعدی می‌ساخت (بند ۹ب/۱). حالا همان
    // پیشنهادهایی می‌آید که شاخه‌ی خواهرش («امروز گرفتی») از قبل داشت.
    track(db, uid, 'daily_ganjineh_empty', { month: user.birth_month });
    return ctx.reply(L.daily.ganjinehEmpty(monthFa(user.birth_month)),
      Markup.inlineKeyboard(recoRows(uid, null)));
  }
  // seed قطعی per کاربر per روز: بعد از این لحظه ترتیبِ حوضچه ثابت است، حتی بعد از
  // ری‌استارت. یعنی «کارتی که انتخاب کردم» با دوباره‌بازکردنِ چت عوض نمی‌شود.
  const seed = `daily:${uid}:${today}`;
  const order = pool.slice().sort((a, b) => seedToInt(seed + a) - seedToInt(seed + b));
  const n = Math.min(GRID_SIZE, order.length);
  patchSession(uid, { dailyOrder: order.slice(0, n), dailyDate: today });
  setState(uid, 'daily_pick');
  await ctx.reply(L.daily.pickPrompt);
  await ctx.reply(L.daily.pickHint, dailyGridKb(n));
}

bot.action(/^dpick:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  if (getState(uid) !== 'daily_pick') return ctx.answerCbQuery().catch(() => {});
  const s = getSession(uid) || {};
  const order = s.dailyOrder || [];
  const i = parseInt(ctx.match[1], 10);
  const key = order[i];
  const today = tehranToday();
  // گاردِ دوبار-تپ **قبل** از اولین await، و گاردِ روزِ کهنه (سشنِ دیروز در چت مانده).
  // پاسخ عمداً **صریح** است نه سکوت: تپِ بی‌جواب روی یک دکمه، کاربر را وادار می‌کند
  // چند بار دیگر هم بزند و فکر کند ربات خراب است (بند ۹ب/۱).
  if (!key || s.dailyDate !== today) return ctx.answerCbQuery(L.daily.expiredGrid, { show_alert: true }).catch(() => {});
  setState(uid, 'idle');
  await ctx.answerCbQuery('✨').catch(() => {});
  try { await ctx.editMessageReplyMarkup(dailyGridKb(order.length, i).reply_markup); } catch {}

  const user = getUser(uid);
  const month = user.birth_month;
  // نسخه‌ای که ندیده. اگر هر سه را دیده، شانسی — چرخه بسته شده.
  const seen = stmts.seenDailyVariants.all(uid, key).map(r => r.variant);
  const variant = pickVariant(seen, ganjinehCount(month, key));
  const text = ganjinehText(month, key, variant);
  const info = CARD_BY_KEY[key];

  const yesterday = tehranDaysAgo(1);
  const streak = user.last_daily_date === yesterday ? (user.daily_streak || 0) + 1 : 1;

  // 🐛 تا v3.17.0 روز **قبل از** تحویل مهر می‌خورد و بینِ مهر تا رسیدنِ عکس حدود ۶ ثانیه
  // مکث و آپلود بود. هر دیپلوی یعنی ری‌استارت (بند ۲ج/۲) و هر خطای آپلود یعنی همان
  // نتیجه: کاربر هیچ کارتی ندید ولی تپِ بعدی‌اش «کارت امروزت رو گرفتی» می‌گیرد و روزش
  // سوخته. حالا مهر **بعد از رسیدنِ واقعیِ عکس** زده می‌شود — همان منطقِ کارت شانس که
  // الماس را لحظه‌ی برگشتنِ هر کارت واریز می‌کند، نه آخرِ بازی.
  // اگر ارسال شکست بخورد، استیت به `daily_pick` برمی‌گردد تا کاربر بتواند دوباره بزند.
  await typing(ctx, PACE_M, 'upload_photo');
  try {
    await sendCardPhoto(ctx, key, L.daily.captionV2(info, monthFa(month)));
  } catch (e) {
    logErr('dailyCardV2 photo:', e.message);
    setState(uid, 'daily_pick');   // روز نسوخت؛ همان گرید هنوز معتبر است
    return ctx.reply(L.daily.retry, Markup.inlineKeyboard([[
      Markup.button.callback(L.buttons.dailyRetry, 'daily_go'),
    ]]));
  }
  stmts.setDaily.run(today, streak, uid);
  // ⚠️ کارتِ روزِ نسل دوم **همیشه ایستاده** است: هیچ قرعه‌ی معکوسی زده نمی‌شود و
  // `CARD_BY_KEY` اصلاً فیلدِ `reversed` ندارد (صفر از ۷۸ کارت). شرطِ قبلی
  // (`info?.reversed ? 1 : 0`) همیشه صفر می‌داد ولی طوری خوانده می‌شد که انگار
  // کاری می‌کند. ستون طبق بند ۲ج/۱ سرِ جایش می‌ماند (اگر روزی معکوس اضافه شد).
  stmts.logDaily.run(uid, today, key, 0, variant);

  await typing(ctx, PACE_REVEAL);
  if (text) await replyLong(ctx, text);

  // ⚠️ این‌جا عمداً **هیچ الماسی** داده نمی‌شود. نسخه‌ی اولِ UX v2 یک الماس بابتِ کارتِ
  // روز می‌داد؛ مالک تصمیمش را عوض کرد و آن الماس به **کارت شانس** منتقل شد. اگر هر دو
  // بمانند نرخِ رایگان دو برابرِ چیزی می‌شود که طراحی شده (۲ الماس در روز به‌جای ۱)، و
  // کلِ محاسبه‌ی امیدِ ریاضیِ کارت شانس بی‌معنی می‌شود. چکِ CI همین را قفل کرده.
  track(db, uid, 'daily_card', { streak, card: key, variant, month });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'daily' });
  if (streak >= 2) {
    await sleep(PACE_S);
    await ctx.reply(L.daily.streak(streak));
  }
  await sleep(PACE_M);
  await ctx.reply(uxV2For(uid) ? L.daily.upsellV3 : L.daily.upsell, Markup.inlineKeyboard(recoRows(uid, null)));
  await ensureMenu(ctx, uid);
});

/* ---------- کارت روز (رایگان، روزی یک‌بار) ---------- */
async function dailyCard(ctx) {
  const uid = ctx.from.id;
  upsertUser(ctx);
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx, INTENT.DAILY)) return;
  if (await blockDuringOpenReading(ctx, INTENT.DAILY)) return;
  if (await blockDuringOpenLucky(ctx, INTENT.DAILY)) return;
  const user = getUser(uid);
  const today = tehranToday();
  if (user.last_daily_date === today) {
    await ctx.reply(L.daily.alreadyUsed, Markup.inlineKeyboard(recoRows(uid, null)));
    return ensureMenu(ctx, uid);
  }
  if (uxV2For(uid)) return dailyCardV2(ctx, uid, user, today);
  // استریک: اگر دیروزِ تهران هم کارت گرفته → +۱، وگرنه از ۱ شروع
  const yesterday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran' }).format(new Date(Date.now() - 86400_000));
  const streak = user.last_daily_date === yesterday ? (user.daily_streak || 0) + 1 : 1;
  stmts.setDaily.run(today, streak, uid);
  const [card] = shuffledDeck(`daily:${uid}:${today}`);
  const info = CARD_BY_KEY[card.key];

  // کش دائمی تفسیر روزانه بر اساس (کارت × جهت × حوزه‌ی تمرکز):
  // حداکثر ۷۸×۲×۵ ترکیب در کل عمر ربات → هزینه‌ی LLM کارت روز در هر مقیاسی تقریباً صفر می‌ماند.
  const focusKey = user.focus_area || '-';
  const cached = stmts.getDailyText.get(card.key, card.reversed ? 1 : 0, focusKey)?.text;
  const llmP = cached
    ? Promise.resolve(cached)
    : orChatResilient(L.prompts.dailySystem, L.prompts.dailyContext({
        focusFa: L.focusFa[user.focus_area] || '-', card: info, reversed: card.reversed,
      }), { maxTokens: DAILY.maxTokens }, [FLASH, FLASH, FALLBACK_MODEL])
        .then(r => {
          if (r?.out) stmts.setDailyText.run(card.key, card.reversed ? 1 : 0, focusKey, r.out);
          return r?.out || null;
        }).catch(e => { logErr('daily LLM:', e.message); return null; });

  await typing(ctx, PACE_M);
  await ctx.reply(L.daily.drawing);
  await typing(ctx, PACE_M, 'upload_photo');
  await sendCardPhoto(ctx, card.key, L.daily.caption(info, card.reversed));
  await typing(ctx, PACE_REVEAL);
  const text = await llmP;
  if (text) await ctx.reply(text);
  track(db, uid, 'daily_card', { streak, cached: !!cached });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'daily' });
  // موتور عادت: نمایش استریک از روز دوم + جایزه‌ی هر ۷ روز پیاپی (اعتبار داخل ربات)
  if (streak >= 2) {
    await sleep(PACE_S);
    await ctx.reply(L.daily.streak(streak));
    if (streak % STREAK_EVERY === 0) {
      stmts.credit.run(STREAK_REWARD, uid);
      track(db, uid, 'credit_granted', { amount: STREAK_REWARD, kind: 'streak' });
      await ctx.reply(L.daily.streakReward(STREAK_REWARD));
    }
  }
  await sleep(PACE_M);
  await ctx.reply(uxV2For(uid) ? L.daily.upsellV3 : L.daily.upsell, Markup.inlineKeyboard(recoRows(uid, null)));
  await ensureMenu(ctx, uid);
}
// ⚠️ **همه‌ی** برچسب‌هایی که کیبورد در طولِ عمرش زده است، نه فقط برچسبِ امروز — همان
// الگوی LUCKY_LABELS / WALLET_LABELS / INVITE_LABELS (بند ۲ج/۶).
// 🐛 باگِ v3.9.0 تا v3.16.0 که مالک با چتِ واقعی گرفت: کیبوردِ دنیای الماس برچسبِ
// `dailyOneCard` («فال تک کارت امروز») را می‌زد ولی تنها هندلر روی `daily` («کارت روز»)
// بود. یعنی دکمه **مرده** بود: هر تپ از همه‌ی bot.hears ها رد می‌شد و به bot.on('text')
// می‌رسید، که در استیتِ idle پیامِ «خوش اومدی» می‌داد و در استیتِ منو پیامِ «فالت هنوز
// بازه». برچسب در `KB_LABELS` بود (پس در قیف ثبت می‌شد) ولی هیچ‌جا اجرا نمی‌شد، و
// همین شکافِ بینِ «ثبت می‌شود» و «اجرا می‌شود» بود که باگ را ماه‌ها پنهان نگه داشت.
// حالا یک چکِ CI هر برچسبِ کیبورد را با هندلرش تطبیق می‌دهد.
const DAILY_LABELS = [L.buttons.dailyOneCard, L.buttons.daily];
bot.hears(DAILY_LABELS, dailyCard);
bot.action('daily_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return dailyCard(ctx); });

/* ═══════════ 🍀 کارت شانس — الماسِ رایگانِ روزانه (بدونِ هیچ LLM) ═══════════
   UX عمداً **همان** آیینِ کشیدنِ کارت است (بُر → توقفِ خودِ کاربر → گریدِ ۲۴تایی → انتخاب)
   چون کاربر این آیین را از فال بلد است و چیزِ تازه‌ای برای یادگرفتن ندارد.
   سه تصمیمِ طراحی که عمدی‌اند:
     ۱) **الماس لحظه‌ی برگشتنِ هر کارت واریز می‌شود، نه آخرِ کار.** هر deploy یعنی restart
        (بند ۲ج/۲)؛ اگر جایزه را آخر می‌دادیم، ری‌استارتِ وسطِ بازی پولِ کاربر را می‌خورد.
     ۲) **روز با اولین انتخاب سوخته می‌شود، نه با دیدنِ گرید.** کسی که فقط نگاه کرد و
        بست، روزش را از دست نمی‌دهد.
     ۳) چیدمانِ الماس‌ها از seedِ قطعیِ (کاربر × روز) می‌آید، پس بستن و بازکردنِ چت
        نتیجه را عوض نمی‌کند و «تا الماس بیاد دوباره امتحان می‌کنم» ممکن نیست. */

/** موقعیتِ کارت‌های الماس‌دار برای **یک دستِ مشخص** — قطعی و تکرارپذیر داخلِ همان دست.
 *
 * ⚠️ باگِ واقعی (۱۴۰۵/۰۵/۲۹، گزارشِ مالک: «۴ بار بازی کردم، ۲ بارش هر سه کارت الماس بود»):
 * تا قبل از این، seed فقط `(uid, today)` بود، یعنی چیدمانِ الماس‌ها برای یک کاربر در یک روز
 * **همیشه یکی** بود. ریستِ ادمین کلِ ردیفِ کاربر را پاک می‌کند (پس `lucky_date` هم می‌رود) و
 * بازی در همان روز دوباره باز می‌شود — این بار روی **همان تخته‌ای که کاربر قبلاً بخشی‌اش را
 * دیده**. یعنی هر دستِ بعدی در همان روز عملاً با ورق‌های رو انجام می‌شد و امیدِ ریاضیِ
 * ۱ الماس در روز از بین می‌رفت. خودِ ریاضی درست بود (۳ × ۸/۲۴ = ۱ و شبیه‌سازی هم تأییدش
 * می‌کند)؛ نشتی از تکرارِ چیدمان می‌آمد، نه از توزیع.
 *
 * حالا یک nonce per **دست** داخلِ seed می‌آید که لحظه‌ی باز شدنِ گرید ساخته و در session
 * ذخیره می‌شود. سه خاصیت با هم حفظ می‌شوند:
 *   ۱) داخلِ یک دست ثابت است → بستن و باز کردنِ چت نتیجه را عوض نمی‌کند (تصمیمِ طراحیِ ۳).
 *   ۲) هر دستِ تازه چیدمانِ تازه دارد → دانشِ دستِ قبلی بی‌ارزش می‌شود.
 *   ۳) در session است نه حافظه → ری‌استارتِ وسطِ بازی چیدمان را عوض نمی‌کند (بند ۹ب/۵).
 * دست‌های در جریانِ لحظه‌ی دیپلوی nonce ندارند؛ برای آن‌ها عمداً به seedِ قدیمی برمی‌گردیم
 * تا کارتی که کاربر همین الان 💎 دیده وسطِ بازی به 🍂 تبدیل نشود (بند ۲ج/۱).
 */
function luckyCoinSlots(uid, today, nonce = '') {
  const seed = nonce ? `lucky:${uid}:${today}:${nonce}` : `lucky:${uid}:${today}`;
  return Array.from({ length: GRID_SIZE }, (_, i) => i)
    .sort((a, b) => seedToInt(seed + ':' + a) - seedToInt(seed + ':' + b))
    .slice(0, LUCKY_COINS);
}

function luckyGridKb(picked = [], coins = []) {
  const rows = [];
  for (let r = 0; r < GRID_SIZE / 4; r++) {
    rows.push(Array.from({ length: 4 }, (_, c) => {
      const i = r * 4 + c;
      const face = !picked.includes(i) ? '🂠' : (coins.includes(i) ? '💎' : '🍂');
      return Markup.button.callback(face, `lpick:${i}`);
    }));
  }
  return Markup.inlineKeyboard(rows);
}

/** پیامِ **واحدِ** وضعیتِ کارت شانس: بارِ اول ساخته می‌شود، از آن به بعد فقط همان ادیت
 *  می‌شود. تصمیمِ صریحِ مالک: شمارنده و نتیجه نباید سه پیامِ مستقل در چت بگذارند.
 *  اگر ادیت نشد (پیامِ پاک‌شده) بی‌سروصدا پیامِ تازه می‌سازد و از آن به بعد همان را ادیت می‌کند. */
async function showLuckyStatus(ctx, uid, text, extra) {
  const id = getSession(uid)?.luckyStatusMsgId;
  if (id) {
    try {
      await ctx.telegram.editMessageText(ctx.chat.id, id, undefined, text,
        extra ? { reply_markup: extra.reply_markup } : undefined);
      return;
    } catch {}
  }
  const m = await ctx.reply(text, extra).catch(() => null);
  if (m) patchSession(uid, { luckyStatusMsgId: m.message_id });
}

const luckyReminderRow = (on) => [Markup.button.callback(
  on ? L.buttons.luckyRemindOff : L.buttons.luckyRemindOn, on ? 'lremind:0' : 'lremind:1')];

/* دستِ در جریان: `{ d: روز, n: nonce, p: [انتخاب‌ها], f: تعدادِ الماسِ پیداشده }`.
   خواندن fail-safe است: هر JSON خرابی مثل «دستی وجود ندارد» رفتار می‌کند، نه کرش. */
function readLuckyHand(uid) {
  try {
    const raw = getUser(uid)?.lucky_hand;
    if (!raw) return null;
    const h = JSON.parse(raw);
    if (!h || typeof h.d !== 'string' || !Array.isArray(h.p)) return null;
    return {
      d: h.d, n: String(h.n || ''),
      p: h.p.map(Number).filter(Number.isInteger),
      f: Number(h.f) || 0,
      fst: h.fst ? 1 : 0,                                   // دستِ اولِ عمرِ کاربر؟
      x: Array.isArray(h.x) ? h.x.map(Number).filter(Number.isInteger) : [],  // خانه‌های الماس‌شده‌ی دستی
    };
  } catch { return null; }
}
const writeLuckyHand = (uid, h) => { try { stmts.setLuckyHand.run(JSON.stringify(h), uid); } catch {} };
/* 🎁 **کفِ دستِ اول** (تصمیمِ صریحِ مالک): اولین باری که هر کاربر کارت شانس می‌کشد
   باید دستِ خالی نرود؛ کف **دو الماس**. از دستِ دوم به بعد هیچ دخالتی نیست.

   چرا: اولین تجربه اگر «سه پوچ» باشد (احتمالش ۲۷.۷٪ است، یعنی از هر چهار کاربرِ تازه
   بیشتر از یکی) کاربر همان‌جا حکم می‌دهد که این بازی چیزی نمی‌دهد و دیگر برنمی‌گردد.
   قلابِ روزانه‌ی رایگان با همان یک تجربه می‌میرد.

   ⚠️ قاعده‌ی نامرئی بودن: هیچ چیزی در فلو، متن، دکمه یا ترتیب عوض نمی‌شود. تنها کاری
   که می‌کنیم این است که خانه‌ی **همان کارتی که خودِ کاربر زد** به مجموعه‌ی الماس‌ها
   اضافه شود. چون گرید فقط کارت‌های **انتخاب‌شده** را رو می‌کند، کاربر هیچ‌وقت نمی‌تواند
   تعدادِ الماسِ تخته را بشمارد و تناقضی ببیند. برای همین خانه‌های اضافه‌شده در خودِ
   دست ذخیره می‌شوند (`x`) و **هم قضاوتِ برد و هم رندرِ گرید** از همان یک مجموعه
   می‌خوانند — وگرنه کارتی که 💎 حساب شده بود روی صفحه 🍂 نشان داده می‌شد.

   **کمینه‌ترین دخالتِ ممکن:** فقط وقتی که بدونِ دخالت، حتی با بردنِ همه‌ی انتخاب‌های
   باقی‌مانده هم به کف نمی‌رسیدیم. یعنی:
     • انتخابِ اول: هرگز دستکاری نمی‌شود (کاملاً شانسی).
     • انتخابِ دوم: فقط اگر اولی پوچ بود.
     • انتخابِ سوم: فقط اگر تا این‌جا یک الماس داریم.
   نتیجه: دستِ اول همیشه ۲ الماس، و با احتمالِ ~۲.۸٪ سه‌تا (وقتی کاربر خودش هر سه را
   طبیعی برده باشد). امیدِ ریاضیِ دستِ اول ~۲.۰۳ به‌جای ۱.۰۰ — یعنی هزینه‌ی این تصمیم
   حدودِ **یک الماسِ اضافه، یک‌بار در عمرِ هر کاربر**. */
const luckySlotsFor = (uid, h) => {
  const base = luckyCoinSlots(uid, h.d, h.n);
  return h.x.length ? [...new Set([...base, ...h.x])] : base;
};
/** آیا این انتخاب باید به‌زور الماس شود؟ `idx` = چندمین انتخاب (۰-پایه). */
function forcedHit(h, idx, naturalHit) {
  if (!h.fst || naturalHit) return false;
  const remainingAfterThis = LUCKY_PICKS - 1 - idx;
  // بدترین حالت اگر این یکی پوچ بماند: همه‌ی باقی‌مانده‌ها ببرند. اگر باز هم به کف
  // نرسیم، همین یکی باید ببرد.
  return h.f + remainingAfterThis < LUCKY_FIRST_MIN;
}

/** دستی که **همین امروز** باز است و هنوز انتخابِ نکشیده دارد. */
function openLuckyHand(uid) {
  const h = readLuckyHand(uid);
  return h && h.d === tehranToday() && h.n && h.p.length < LUCKY_PICKS ? h : null;
}
/** گریدِ همان دست را دوباره جلوی کاربر می‌گذارد (ادامه‌ی بازی). */
async function resumeLuckyHand(ctx, uid, h) {
  setState(uid, 'lucky_pick');
  await ctx.reply(L.lucky.pickPrompt(LUCKY_PICKS - h.p.length), luckyGridKb(h.p, luckySlotsFor(uid, h)));
}

// 🎲 گاردِ «دستِ بازِ کارت شانس» — دوقلوی `blockDuringOpenReading`. با اینکه دست دیگر
// از بین نمی‌رود (روی ردیفِ کاربر است)، تپِ یک دکمه‌ی منو وسطِ بازی نباید **بی‌صدا**
// گرید را رها کند (بند ۹ب/۲): یا ادامه، یا کنارگذاشتنِ آگاهانه.
async function blockDuringOpenLucky(ctx, intent) {
  if (!NAV_GUARD_ENABLED) return false;
  const uid = ctx.from.id;
  if (!['lucky_shuffle', 'lucky_pick'].includes(getState(uid))) return false;
  const h = openLuckyHand(uid);
  if (!h) return false;                    // دستی برای ادامه نیست → مسیرِ عادی برود
  if (intent) setIntent(uid, intent);
  await ctx.reply(L.lucky.openGuard, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.luckyResume, 'lucky:resume')],
    [Markup.button.callback(L.buttons.cancel, 'lucky:cancel')],
  ]));
  return true;
}

bot.action('lucky:resume', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  const uid = ctx.from.id;
  const h = openLuckyHand(uid);
  if (!h) return ctx.reply(L.lucky.expired).catch(() => {});
  await resumeLuckyHand(ctx, uid, h);
});

// «بی‌خیال» دستِ کاربر را **نمی‌کُشد**: انتخاب‌های باقی‌مانده حقِ اوست و تا آخرِ همان روز
// با دکمه‌ی کارت شانس برمی‌گردد. فقط از حالتِ گیر درمی‌آید.
bot.action('lucky:cancel', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  const uid = ctx.from.id;
  setState(uid, 'idle');
  await replyCanceled(ctx, uid);
});

async function luckyCard(ctx) {
  const uid = ctx.from.id;
  upsertUser(ctx);
  if (!uxV2For(uid)) return;
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx, INTENT.LUCKY)) return;
  if (await blockDuringOpenReading(ctx, INTENT.LUCKY)) return;
  if (await blockDuringPendingReading(ctx)) return;
  const user = getUser(uid);
  const today = tehranToday();
  // 🔁 دستِ نیمه‌تمامِ همین امروز **ادامه** داده می‌شود. تا قبل از این، کاربری که کارتِ
  // اولش را کشیده بود و بعد بیرون رفته بود، پیامِ «امروز استفاده کردی» می‌گرفت در حالی
  // که هنوز دو انتخاب طلبکار بود.
  const open = openLuckyHand(uid);
  if (open) return resumeLuckyHand(ctx, uid, open);
  if (user.lucky_date === today) {
    return ctx.reply(L.lucky.already, Markup.inlineKeyboard([luckyReminderRow(!!user.lucky_reminder_on)]));
  }
  setState(uid, 'lucky_shuffle');
  await ctx.reply(L.lucky.intro(LUCKY_PICKS, LUCKY_COINS, GRID_SIZE));
  await typing(ctx, PACE_S, 'upload_photo');
  await sendCardPhoto(ctx, 'back', L.lucky.shuffleCaption, { spoiler: false });
  const m = await ctx.reply(L.reading.shuffleFrames[0], Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.stopShuffle, 'lucky_stop')],
  ]));
  patchSession(uid, { luckyMsgId: m.message_id });
  (async () => {
    for (let i = 1; i < 90; i++) {
      await sleep(1300);
      if (getState(uid) !== 'lucky_shuffle' || getSession(uid).luckyMsgId !== m.message_id) return;
      const frame = L.reading.shuffleFrames[i % L.reading.shuffleFrames.length];
      try {
        await ctx.telegram.editMessageText(ctx.chat.id, m.message_id, undefined, frame, {
          reply_markup: Markup.inlineKeyboard([[Markup.button.callback(L.buttons.stopShuffle, 'lucky_stop')]]).reply_markup,
        });
      } catch {}
    }
  })().catch(e => logErr('lucky anim:', e.message));
}
// برچسبِ این دکمه در v3.10.2 از 🍀 به 🎲 رفت. کیبوردِ reply روی گوشیِ کاربر تا اولین
// جایگزینی می‌ماند، پس برچسبِ قبلی هم باید match شود وگرنه دکمه‌ی کش‌شده می‌میرد (بند ۲ج/۶).
const LUCKY_LABELS = [L.buttons.luckyMain, '🍀 کارت شانس (استخراج الماس)', '🍀 کارت شانس (الماس رایگان)'];
bot.hears(LUCKY_LABELS, luckyCard);
bot.action('lucky_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return luckyCard(ctx); });
// دو نقطه‌ی ورودِ اینلاین که خواهرِ `lucky_go` اند. لازم شدند چون پیامِ اطلاع‌رسانیِ آپدیت
// (v3.25.0) سه دکمه دارد و دو تای دیگرش تا امروز فقط از کیبوردِ ماندگار قابلِ رسیدن بودند.
// عمداً فقط delegate می‌کنند: هر دو تابعِ مقصد **همه‌ی** گاردهای فلوی باز را دارند
// (آنبوردینگ، فاکتور، فالِ باز، کارتِ شانسِ نیمه‌تمام)، پس این دکمه‌ها هیچ مسیرِ دور زدنی
// باز نمی‌کنند. اسمشان هم مثل `lucky_go` عمومی است تا دکمه‌ی کش‌شده سال‌ها بعد هم
// معنیِ همین را بدهد (بند ۲ج/۶).
bot.action('reading_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return showCatalog(ctx); });
bot.action('wallet_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return showWallet(ctx); });

bot.action('lucky_stop', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery('✋').catch(() => {});
  if (getState(uid) !== 'lucky_shuffle') return;
  const today = tehranToday();
  setState(uid, 'lucky_pick'); // قبل از هر await — گاردِ دوبار-تپ
  // nonceِ همین دست: از این لحظه تا آخرِ دست ثابت می‌ماند و در session (یعنی DB) می‌نشیند.
  const luckyNonce = `${Date.now()}:${Math.floor(Math.random() * 1e9)}`;
  writeLuckyHand(uid, { d: today, n: luckyNonce, p: [], f: 0, fst: 0, x: [] });
  // فقط شناسه‌ی پیامِ وضعیت در سشن می‌ماند (جزئیاتِ نمایشی؛ گم شدنش فقط یک پیامِ تازه می‌سازد)
  patchSession(uid, { luckyStatusMsgId: 0 });
  const msgId = getSession(uid).luckyMsgId;
  if (msgId) { try { await ctx.telegram.editMessageText(ctx.chat.id, msgId, undefined, '🂠 ✋'); } catch {} }
  await ctx.reply(L.lucky.pickPrompt(LUCKY_PICKS), luckyGridKb());
});

bot.action(/^lpick:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  const i = parseInt(ctx.match[1], 10);
  const today = tehranToday();
  // ⚠️ دست از **ردیفِ کاربر** خوانده می‌شود، نه از سشن و نه از استیت. یعنی نه
  // `setSession(uid, null)` هیچ‌کدام از شش نقطه‌اش، و نه یک `setState` در مسیرِ دیگر،
  // نمی‌تواند انتخاب‌های باقی‌ماندهٔ کاربر را از بین ببرد. استیت فقط برای UX ست می‌شود.
  const hand = readLuckyHand(uid);
  // گاردهای سینکرون **قبل از** اولین await: دستِ نبود/کهنه، تکراری، سهمیه‌ی تمام‌شده
  if (!hand || hand.d !== today || !hand.n) {
    return ctx.answerCbQuery(L.lucky.expired, { show_alert: true }).catch(() => {});
  }
  const picks = hand.p.slice();
  if (picks.includes(i) || picks.length >= LUCKY_PICKS) {
    return ctx.answerCbQuery().catch(() => {});
  }
  // روز فقط با **اولین** انتخاب سوخته می‌شود، و آن هم اتمیک (شرطِ روز داخلِ UPDATE).
  let fst = hand.fst;
  if (!picks.length) {
    if (stmts.claimLucky.run(today, uid, today).changes === 0) {
      setState(uid, 'idle');
      return ctx.answerCbQuery().catch(() => {});
    }
    // 🎁 «دستِ اولِ عمرِ کاربر» دقیقاً همین‌جا تعیین و در خودِ دست فریز می‌شود: بعد از
    // claimLucky (که اتمیک است و روزی یک بار رد می‌شود) و قبل از اولین await. شمارنده
    // با **اولین انتخاب** بالا می‌رود نه با دیدنِ گرید، پس کسی که فقط نگاه کرد و بست
    // دستِ اولش را از دست نمی‌دهد.
    fst = (getUser(uid)?.lucky_hands || 0) === 0 ? 1 : 0;
    stmts.bumpLuckyHands.run(uid);
  }

  const h = { ...hand, fst };
  const slots = luckySlotsFor(uid, h);
  const natural = slots.includes(i);
  const forced = forcedHit(h, picks.length, natural);
  const hit = natural || forced;
  // خانه‌ی اجباری در خودِ دست ثبت می‌شود تا **رندرِ گرید** هم همان را 💎 ببیند،
  // وگرنه کارتی که الماس حساب شده روی صفحه 🍂 نشان داده می‌شد.
  const x = forced ? [...hand.x, i] : hand.x;
  const coinSlots = forced ? [...slots, i] : slots;
  picks.push(i);
  const found = hand.f + (hit ? 1 : 0);
  const done = picks.length >= LUCKY_PICKS;
  setState(uid, done ? 'idle' : 'lucky_pick');
  writeLuckyHand(uid, { d: today, n: hand.n, p: picks, f: found, fst, x });

  // واریزِ همان لحظه (نه آخرِ بازی): ری‌استارتِ وسطِ کار نباید الماسِ برده‌شده را بخورد.
  if (hit) {
    stmts.credit.run(LUCKY_COIN_VALUE, uid);
    track(db, uid, 'credit_granted', { amount: LUCKY_COIN_VALUE, kind: 'lucky' });
  }
  await ctx.answerCbQuery(hit ? L.lucky.hitToast : L.lucky.missToast).catch(() => {});
  try { await ctx.editMessageReplyMarkup(luckyGridKb(picks, coinSlots).reply_markup); } catch {}
  // شمارنده حالا کارتِ **سوم** را هم نشان می‌دهد؛ قبلاً تپِ آخر از رویش می‌پرید و کاربر
  // «۳ از ۳» را هرگز نمی‌دید (ایرادِ صریحِ مالک).
  const counter = L.lucky.progress(picks.length, LUCKY_PICKS, found);
  await showLuckyStatus(ctx, uid, counter);
  if (!done) return;

  track(db, uid, 'lucky_card', { coins: found, picks: LUCKY_PICKS, first: fst });
  await sleep(PACE_S);
  const reminderOn = !!getUser(uid)?.lucky_reminder_on;
  // نتیجه روی **همان** پیامِ وضعیت می‌نشیند (خطِ شمارنده بالایش می‌ماند تا «۳ از ۳» دیده شود).
  await showLuckyStatus(ctx, uid, `${counter}\n\n${found ? L.lucky.won(found) : L.lucky.lost}`,
    Markup.inlineKeyboard([luckyReminderRow(reminderOn)]));
  // UX v2.1 (تصمیمِ صریحِ مالک): بعد از کشیدنِ کارتِ شانس، کاربر دعوت می‌شود سؤالِ
  // بعدی‌اش را از تاروت بپرسد — چه سکه برده باشد چه نه، همیشه یک قدمِ بعدیِ روشن دارد.
  await sleep(PACE_S);
  // (ensureMenu حالا داخلِ خودِ sendContinuePrompt است — تک‌نقطه، بدونِ تکرار)
  await sendContinuePrompt(ctx, uid);
});

bot.action(/^lremind:([01])$/, async (ctx) => {
  const uid = ctx.from.id;
  const on = ctx.match[1] === '1';
  await ctx.answerCbQuery().catch(() => {});
  stmts.setLuckyReminder.run(on ? 1 : 0, uid);
  track(db, uid, 'lucky_reminder', { on: on ? 1 : 0 });
  try { await ctx.editMessageReplyMarkup(Markup.inlineKeyboard([luckyReminderRow(on)]).reply_markup); } catch {}
  await ctx.reply(on ? L.lucky.remindOn : L.lucky.remindOff);
});

/* ---------- 🎁 منوی سرگرمی‌های رایگان + 📜 فال حافظ (رایگان، روزی یک‌بار، بدون LLM) ----------
   کل این بخش پشت FREE_MENU_ENABLED است؛ خاموش = دکمه/منو/callbackها بی‌اثر (رفتار عیناً قبلی). */
async function showFreeMenu(ctx) {
  if (!FREE_MENU_ENABLED) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx)) return;
  if (await blockDuringOpenReading(ctx)) return;
  const rows = [[Markup.button.callback(L.buttons.freeDaily, 'daily_go')]];
  if (HAFEZ.length) rows.push([Markup.button.callback(L.buttons.freeHafez, 'hafez_go')]);
  rows.push([Markup.button.callback(L.buttons.freeEstekhare, 'estekhare_go')]);
  if (Object.keys(QUIZ).length) rows.push([Markup.button.callback(L.buttons.freeQuiz, 'quiz_go')]);
  rows.push([Markup.button.callback(L.buttons.freeCoffee, 'coffee_go')]);
  rows.push([Markup.button.callback(L.buttons.freeLibrary, 'lib_go')]);
  await ctx.reply(L.freeMenu.title, Markup.inlineKeyboard(rows));
  track(db, uid, 'free_menu_opened', {});
}
bot.hears(L.buttons.freeMenu, showFreeMenu);
bot.action('freemenu', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return showFreeMenu(ctx); });
// ردیفِ «به‌جای ترک، رایگان بازی کن» برای پی‌وال (خالی وقتی فیچر خاموش است)
const freeMenuRow = () => (FREE_MENU_ENABLED && HAFEZ.length)
  ? [[Markup.button.callback(L.buttons.freeMenu, 'freemenu')]] : [];

async function hafezFaal(ctx, via) {
  if (!FREE_MENU_ENABLED || !HAFEZ.length) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  const user = getUser(uid);
  const today = tehranToday();
  const ctaKb = Markup.inlineKeyboard([[Markup.button.callback(L.buttons.hafezCta, 'opentopic')]]);
  if (user.last_hafez_date === today) return ctx.reply(L.hafez.alreadyUsed, ctaKb);
  stmts.setHafez.run(today, uid);
  // انتخابِ قطعیِ روزانه از هش (بعد از ری‌استارت هم همان غزلِ همان روز برای همان کاربر)
  const g = HAFEZ[seedToInt(`hafez:${uid}:${today}`) % HAFEZ.length];
  await typing(ctx, PACE_M);
  await ctx.reply(L.hafez.intent);
  await typing(ctx, PACE_REVEAL);
  await ctx.reply(L.hafez.ghazal(g));
  await typing(ctx, PACE_M);
  await ctx.reply(L.hafez.faal(g.faal));
  track(db, uid, 'hafez_taken', { n: g.n, via: via || 'menu' });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'hafez' });
  await sleep(PACE_S);
  await ctx.reply(L.hafez.cta, ctaKb);
}
bot.action('hafez_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return hafezFaal(ctx, 'menu'); });

/* ---------- 📿 استخاره با تسبیح (رایگان، سقفِ نرمِ ۳/روز، بدون LLM) ---------- */
const ESTEKHARE_CAP = 3;
async function estekhareFaal(ctx, via) {
  if (!FREE_MENU_ENABLED) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  const user = getUser(uid);
  const today = tehranToday();
  const ctaKb = Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.estekhareYesno, 'spread:yesno')],
    [Markup.button.callback(L.buttons.estekhareChoice, 'spread:choice')],
  ]);
  const count = user.estekhare_date === today ? (user.estekhare_count || 0) : 0;
  if (count >= ESTEKHARE_CAP) return ctx.reply(L.estekhare.cap, ctaKb);
  stmts.setEstekhare.run(today, count + 1, uid);
  // نتیجه‌ی قطعی از هش؛ count داخلِ seed است تا سه استخاره‌ی یک روز سه جوابِ متفاوت بدهند
  const buckets = ['good', 'mid', 'bad'];
  const h = seedToInt(`estekhare:${uid}:${today}:${count}`);
  const outcome = buckets[h % 3];
  const variants = L.estekhare.outcomes[outcome];
  const text = variants[(h >>> 2) % variants.length];
  // فضاسازی + انیمیشنِ شمردنِ دانه‌ها (ادیتِ پیاپیِ یک پیام)
  await ctx.reply(L.estekhare.intent);
  await typing(ctx, PACE_M);
  const frames = L.estekhare.beadFrames;
  const msg = await ctx.reply(frames[0]);
  for (let i = 1; i < frames.length; i++) {
    await sleep(PACE_M);
    try { await ctx.telegram.editMessageText(msg.chat.id, msg.message_id, undefined, frames[i]); } catch {}
  }
  await sleep(PACE_REVEAL);
  await ctx.reply(L.estekhare.result(text));
  track(db, uid, 'estekhare_taken', { outcome, via: via || 'menu' });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'estekhare' });
  await sleep(PACE_S);
  await ctx.reply(L.estekhare.cta, ctaKb);
}
bot.action('estekhare_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return estekhareFaal(ctx, 'menu'); });

/* ---------- 🃏 کوییز «کدام کارتِ تاروتی؟» (رایگان، ماهی‌یک‌بار، بدون LLM؛ موتور رفرال) ----------
   حالتِ بدونِ state: کلِ مسیرِ پاسخ‌ها در callback_data کدگذاری می‌شود (`quiz:<answers>`)،
   پس ری‌استارتِ وسطِ کوییز هم بی‌خطر است. */
const QUIZ_COOLDOWN_DAYS = 30;
function quizQuestionView(answers) {
  const step = answers.length;
  const q = L.quiz.questions[step];
  const text = `${L.quiz.progress(step + 1, L.quiz.questions.length)}\n\n${q.q}`;
  const rows = q.options.map((o, i) => [Markup.button.callback(o.t, `quiz:${answers}${i}`)]);
  return { text, rows };
}
async function quizStart(ctx) {
  if (!FREE_MENU_ENABLED || !Object.keys(QUIZ).length) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  const user = getUser(uid);
  const today = tehranToday();
  if (user.last_quiz_date) {
    const days = Math.floor((new Date(today) - new Date(user.last_quiz_date)) / 86400000);
    if (days >= 0 && days < QUIZ_COOLDOWN_DAYS) {
      return ctx.reply(L.quiz.cap, Markup.inlineKeyboard([[Markup.button.callback(L.buttons.quizCta, 'opentopic')]]));
    }
  }
  track(db, uid, 'quiz_started', {});
  const { text, rows } = quizQuestionView('');
  await ctx.reply(L.quiz.intro);
  await ctx.reply(text, Markup.inlineKeyboard(rows));
}
bot.action('quiz_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return quizStart(ctx); });

bot.action(/^quiz:(\d+)$/, async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (!FREE_MENU_ENABLED || !Object.keys(QUIZ).length) return;
  const answers = ctx.match[1];
  const total = L.quiz.questions.length;
  if (answers.length < total) {              // سؤالِ بعدی روی همان پیام
    const { text, rows } = quizQuestionView(answers);
    try { await ctx.editMessageText(text, Markup.inlineKeyboard(rows)); } catch {}
    return;
  }
  // نگاشتِ قطعی: جمعِ رأی‌ها → argmax (tie-break: ترتیبِ m00..m21 در QUIZ)
  const uid = ctx.from.id;
  upsertUser(ctx);
  const votes = {};
  for (let s = 0; s < total; s++) {
    const opt = L.quiz.questions[s].options[Number(answers[s])];
    if (opt) for (const k of opt.c) votes[k] = (votes[k] || 0) + 1;
  }
  // بیشینه‌ی رأی؛ در صورتِ تساوی، انتخابِ قطعی با هش (تا کارت‌های هم‌رأی همه قابل‌دسترس بمانند)
  const keys = Object.keys(QUIZ);
  const maxV = Math.max(...keys.map(k => votes[k] || 0));
  const tied = keys.filter(k => (votes[k] || 0) === maxV);
  const best = tied[seedToInt(`quiz:${answers}`) % tied.length];
  const card = CARD_BY_KEY[best];
  stmts.setQuiz.run(tehranToday(), uid);
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await typing(ctx, PACE_M, 'upload_photo');
  await sendCardPhoto(ctx, best, L.quiz.resultHead(card), { spoiler: false });
  await typing(ctx, PACE_M);
  await ctx.reply(QUIZ[best]);
  track(db, uid, 'quiz_done', { card: best });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'quiz' });
  if (!BOT_USERNAME) { try { BOT_USERNAME = (await bot.telegram.getMe()).username; } catch {} }
  await sleep(PACE_S);
  const refLink = `https://t.me/${BOT_USERNAME}?start=ref_${uid}`;
  const shareUrl = `https://t.me/share/url?url=${encodeURIComponent(refLink)}&text=${encodeURIComponent(L.quiz.shareText(card))}`;
  await ctx.reply(L.quiz.cta, Markup.inlineKeyboard([
    [Markup.button.url(L.buttons.quizShare, shareUrl)],
    [Markup.button.callback(L.buttons.quizCta, 'opentopic')],
  ]));
});

/* ---------- ☕ فال قهوه‌ی سؤال‌محور (رایگان، روزی‌یک‌بار، بدون LLM) ----------
   حالتِ بدونِ state: پاسخ‌ها در callback_data (`coffee:<answers>`). خوانش = چیدنِ سه نقشِ فنجان. */
function coffeeQuestionView(answers) {
  const step = answers.length;
  const q = L.coffee.questions[step];
  const text = `${L.coffee.progress(step + 1, L.coffee.questions.length)}\n\n${q.q}`;
  const rows = q.options.map((o, i) => [Markup.button.callback(o.t, `coffee:${answers}${i}`)]);
  return { text, rows };
}
async function coffeeStart(ctx) {
  if (!FREE_MENU_ENABLED) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  const ctaKb = Markup.inlineKeyboard([[Markup.button.callback(L.buttons.coffeeCta, 'opentopic')]]);
  if (getUser(uid).last_coffee_date === tehranToday()) return ctx.reply(L.coffee.alreadyUsed, ctaKb);
  const { text, rows } = coffeeQuestionView('');
  await ctx.reply(L.coffee.intro);
  await ctx.reply(text, Markup.inlineKeyboard(rows));
}
bot.action('coffee_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return coffeeStart(ctx); });

bot.action(/^coffee:(\d+)$/, async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (!FREE_MENU_ENABLED) return;
  const answers = ctx.match[1];
  const total = L.coffee.questions.length;
  if (answers.length < total) {
    const { text, rows } = coffeeQuestionView(answers);
    try { await ctx.editMessageText(text, Markup.inlineKeyboard(rows)); } catch {}
    return;
  }
  const uid = ctx.from.id;
  upsertUser(ctx);
  const today = tehranToday();
  // اگر همین امروز خوانده، دوباره نده (گاردِ روزی‌یک‌بار روی خودِ نتیجه هم)
  if (getUser(uid).last_coffee_date === today) {
    try { await ctx.editMessageReplyMarkup(undefined); } catch {}
    return ctx.reply(L.coffee.alreadyUsed, Markup.inlineKeyboard([[Markup.button.callback(L.buttons.coffeeCta, 'opentopic')]]));
  }
  stmts.setCoffee.run(today, uid);
  const parts = [];
  for (let s = 0; s < total; s++) {
    const opt = L.coffee.questions[s].options[Number(answers[s])];
    if (opt) parts.push(opt.s);
  }
  const closing = L.coffee.closings[seedToInt(`coffee:${uid}:${today}`) % L.coffee.closings.length];
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.coffee.turn);
  await typing(ctx, PACE_REVEAL);
  await ctx.reply(L.coffee.compose(parts, closing));
  track(db, uid, 'coffee_taken', { combo: answers });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'coffee' });
  await sleep(PACE_S);
  await ctx.reply(L.coffee.cta, Markup.inlineKeyboard([[Markup.button.callback(L.buttons.coffeeCta, 'opentopic')]]));
});

/* ---------- 📖 کتابخانه‌ی معنیِ ۷۸ کارت (رایگان، مرور؛ دیتا از cards.js، بدون LLM) ---------- */
const LIB_PAGE = 8;
const libCards = (g) => CARDS.filter(c => g === 'major' ? c.arcana === 'major' : c.key[0] === g);
async function libraryMenu(ctx, edit) {
  if (!FREE_MENU_ENABLED) return;
  upsertUser(ctx);
  const rows = L.library.groups.map((grp, gi) => [Markup.button.callback(grp.t, `lib:l:${gi}:0`)]);
  const kb = Markup.inlineKeyboard(rows);
  if (edit) { try { await ctx.editMessageText(L.library.menu, kb); } catch {} }
  else await ctx.reply(L.library.menu, kb);
}
bot.action('lib_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return libraryMenu(ctx, false); });
bot.action('lib:home', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return libraryMenu(ctx, true); });

bot.action(/^lib:l:(\d+):(\d+)$/, async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (!FREE_MENU_ENABLED) return;
  const gi = Number(ctx.match[1]);
  const grp = L.library.groups[gi];
  if (!grp) return;
  const cards = libCards(grp.g);
  const pages = Math.max(1, Math.ceil(cards.length / LIB_PAGE));
  const p = Math.max(0, Math.min(Number(ctx.match[2]), pages - 1));
  const rows = cards.slice(p * LIB_PAGE, (p + 1) * LIB_PAGE).map(c => [Markup.button.callback(c.fa, `lib:c:${c.key}`)]);
  const nav = [];
  if (p > 0) nav.push(Markup.button.callback(L.library.btnPrev, `lib:l:${gi}:${p - 1}`));
  if (p < pages - 1) nav.push(Markup.button.callback(L.library.btnNext, `lib:l:${gi}:${p + 1}`));
  if (nav.length) rows.push(nav);
  rows.push([Markup.button.callback(L.library.btnCats, 'lib:home')]);
  try { await ctx.editMessageText(L.library.listHeader(grp.t, p + 1, pages), Markup.inlineKeyboard(rows)); } catch {}
});

bot.action(/^lib:c:([a-z]\d{2})$/, async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (!FREE_MENU_ENABLED) return;
  const key = ctx.match[1];
  const c = CARD_BY_KEY[key];
  if (!c) return;
  const uid = ctx.from.id;
  upsertUser(ctx);
  await typing(ctx, PACE_M, 'upload_photo');
  await sendCardPhoto(ctx, key, L.library.card(c), { spoiler: false });
  track(db, uid, 'card_meaning_viewed', { card: key });
  const gi = L.library.groups.findIndex(grp => grp.g === (c.arcana === 'major' ? 'major' : key[0]));
  await ctx.reply(L.library.cta, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.libCta, 'opentopic')],
    [Markup.button.callback(L.library.btnCats, gi >= 0 ? `lib:l:${gi}:0` : 'lib:home')],
  ]));
});

/* ---------- فال پولی: کاتالوگ → تمرکز → سؤال ---------- */
// کیبورد کاتالوگ: [موضوع آزاد؟] + دکمه‌های فال + دکمه‌ی «راهنمای انتخاب» ته لیست.
// کاتالوگ per کاربر: نسلِ دومِ کاتالوگ (عشق‌محورِ تقابلی) فقط به کسی نشان داده می‌شود که
// اقتصادِ سکه برایش روشن است، چون قیمت‌های کنارِ گزینه‌ها هم به سکه‌اند و این دو یک بسته‌اند.
// ═══ منوی فال (UX v2.1) ═══
// ساختارِ ثابتِ چهارتایی (تصمیمِ صریحِ مالک):
//   ۱) «سؤال شخصی خودم» — **همیشه** اول و همیشه همین یکی. نقطه‌ی ورودِ بدونِ محدودیت.
//   ۲و۳) دو جایگاهِ چرخشی که با A/B تعیین می‌شوند.
//   ۴) «مشاهده همه فال‌ها» — لیستِ کامل.
// چرا جایگاه ۲و۳ آزمایشی‌اند: کدام موضوع بیشترین کلیک را می‌گیرد یک **فرضیه** است نه
// دانسته، و بند ۲ج/۴ ریشه می‌گوید فرضیه از مسیرِ A/B برود نه سوییچِ سخت. تا وقتی
// آزمایش از داشبورد running نشود، `variant()` همیشه control می‌دهد = همین جفتِ پیش‌فرض.
const MENU_PIN = 'personal';                 // جایگاهِ اولِ ثابت
const MENU_SLOTS_DEFAULT = ['yesno', 'love'];
// نسخه‌های آزمایشِ `menu_slots`. control عمداً اولین ردیف است تا خاموش‌بودنِ آزمایش
// دقیقاً یعنی «همان چیزی که مالک برای شروع خواست».
const MENU_SLOT_VARIANTS = {
  control: MENU_SLOTS_DEFAULT,
  love_first: ['love', 'yesno'],
  crush_money: ['crush', 'money'],
  feel_career: ['feel', 'career'],
};
const menuSlotsFor = (uid) => {
  try { return MENU_SLOT_VARIANTS[variant(db, uid, 'menu_slots')] || MENU_SLOTS_DEFAULT; }
  catch { return MENU_SLOTS_DEFAULT; }
};

// «سؤال شخصی خودم» (پینِ منو) همیشه **آبی** است (تصمیمِ صریحِ مالک) — پرتکرارترین
// ورودیِ فال و تنها موضوعی که کاربر با کلماتِ خودش می‌نویسد.
const topicStyle = (key) => (key === MENU_PIN ? 'primary' : undefined);
const topicRow = (key) => {
  const t = TOPIC_BY_KEY[key];
  return t ? [styled(Markup.button.callback(L.buttons.topic(t), `topic:${t.key}`), topicStyle(key))] : null;
};

/** منوی کوتاهِ فال: پین + دو جایگاهِ آزمایشی + «همه‌ی فال‌ها». */
function falMenuKb(uid) {
  const keys = [MENU_PIN, ...menuSlotsFor(uid).filter(k => k !== MENU_PIN)].slice(0, 3);
  return [
    ...keys.map(topicRow).filter(Boolean),
    [Markup.button.callback(L.buttons.allSpreadsV2, 'catalog_go')],
  ];
}

/** لیستِ کاملِ موضوع‌ها، به همان ترتیبِ TOPICS_V3 (سؤالِ شخصی، بله/خیر، عاطفی، شغل و پول). */
// پسوندِ `:a` یعنی «کاربر از لیستِ کامل آمده» — تنها چیزی که صفحه‌ی بعدی لازم دارد تا دکمه‌ی
// بازگشتش **یک قدم** عقب برود و همین لیست را برگرداند، نه منوی کوتاه را (UX v2.3).
// حالت را در session نمی‌گذاریم چون showCatalog/nav:menu آن را پاک می‌کنند و دکمه‌ی کهنه
// هم باید سال‌ها بعد درست کار کند؛ callback_data تنها جای مطمئن است (سقف ۶۴ بایت، این ۱۶).
const allTopicsKb = () => [
  ...TOPICS_V3.map(t => [styled(Markup.button.callback(L.buttons.topic(t), `topic:${t.key}:a`), topicStyle(t.key))]),
  ...navMenuRow(),
];

// تک‌منبعِ «متن + کیبورد» هر صفحه‌ی ناوبری، تا showCatalog و دکمه‌های بازگشت دقیقاً یک چیز
// را رندر کنند (همان الگوی cat_guide/cat_back که از قبل در همین فایل هست).
const falMenuScreen = (uid) => [L.reading.catalogV3, Markup.inlineKeyboard(falMenuKb(uid))];
const allTopicsScreen = () => [L.reading.allTopics, Markup.inlineKeyboard(allTopicsKb())];
const topicMenuScreen = (uid, kind) => (kind === 'a' ? allTopicsScreen() : falMenuScreen(uid));

function catalogKb(uid) {
  if (uxV2For(uid)) return allTopicsKb();
  const v2 = coinsOn(uid);
  const cur = curOf(uid);
  // بَج‌های کوتاه روی دکمه‌ها: عشق و رابطه = محبوب‌ترین، صلیب سلتی = کامل‌ترین.
  const rows = spreadsFor(v2).map(s => [Markup.button.callback(
    L.buttons.spread(s, L.reading.catalogBadges[s.id], cur, faOf(s, v2)), `spread:${s.id}`)]);
  const kb = [];
  if (OPEN_TOPIC_ENABLED) kb.push([Markup.button.callback(L.buttons.openTopic(v2), 'opentopic')]);
  // کارت روزِ رایگان به‌عنوان اولین گزینه‌ی لیست (نقطه‌ی ورودِ بی‌هزینه).
  kb.push([Markup.button.callback(L.buttons.dailyInCatalog, 'daily_go')]);
  kb.push(...rows);
  kb.push([Markup.button.callback(L.buttons.spreadGuide, 'cat_guide')]);
  kb.push(...navMenuRow());
  return kb;
}
// `full=true` یعنی لیستِ کاملِ موضوع‌ها (دکمه‌ی «مشاهده همه فال‌ها»)؛ پیش‌فرض منوی کوتاه.
// در دنیای قبل از UX v2 هر دو یک چیزند (همان کاتالوگِ قدیمی)، پس رفتار عوض نمی‌شود.
// `edit=true` یعنی به‌جای پیامِ جدید، همین پیامِ دکمه‌خورده ادیت شود (دکمه‌ی «مشاهده همه
// فال‌ها»): کاربر یک صفحه جلو می‌رود، نه اینکه چت شلوغ‌تر شود. اگر ادیت نشد (پیامِ کهنه یا
// پاک‌شده) بی‌سروصدا به همان پیامِ جدیدِ همیشگی برمی‌گردیم.
async function showCatalog(ctx, full = false, edit = false) {
  const uid = ctx.from.id;
  upsertUser(ctx);
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx, INTENT.READING)) return;
  if (await blockDuringOpenReading(ctx, INTENT.READING)) return;
  if (await blockDuringOpenLucky(ctx, INTENT.READING)) return;
  // setSession(uid, null) پایین‌تر readingId را دور می‌ریزد؛ پس قبلش فالِ رزروشده باید گارد شود
  if (await blockDuringPendingReading(ctx)) return;
  setState(uid, 'choose_spread');
  setSession(uid, null);
  if (uxV2For(uid)) {
    const [text, kb] = full ? allTopicsScreen() : falMenuScreen(uid);
    if (edit) { try { return await ctx.editMessageText(text, kb); } catch {} }
    return ctx.reply(text, kb);
  }
  // پیام کوتاه: فقط دعوت به انتخاب؛ توضیح تک‌تک فال‌ها به «راهنمای انتخاب» منتقل شد.
  await ctx.reply(L.reading.catalog, Markup.inlineKeyboard(catalogKb(uid)));
}
bot.hears(L.buttons.reading, (ctx) => showCatalog(ctx));

// راهنمای انتخاب: همین پیام ادیت می‌شود به توضیحِ فال‌ها + دکمه‌ی بازگشت (بدون پیام جدید).
bot.action('cat_guide', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  const v2 = coinsOn(ctx.from.id);
  const cur = curOf(ctx.from.id);
  const lines = spreadsFor(v2)
    .map(s => L.reading.spreadLine(s, L.reading.badges[s.id], cur, faOf(s, v2))).join('\n\n');
  const guide = OPEN_TOPIC_ENABLED ? `${L.reading.openTopicHint(v2)}\n\n${lines}` : lines;
  try {
    await ctx.editMessageText(`${L.reading.guideTitle}\n\n${guide}`, Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.guideBack, 'cat_back')],
    ]));
  } catch {}
});
// بازگشت از راهنما به لیست انتخاب فال (همان پیام ادیت می‌شود).
bot.action('cat_back', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  try { await ctx.editMessageText(L.reading.catalog, Markup.inlineKeyboard(catalogKb(ctx.from.id))); } catch {}
});

// موضوع آزاد: انتخاب عمق (۳ یا ۵ کارت) — قیمت طبق قرارداد فقط در پی‌وال نشان داده می‌شود
bot.action('opentopic', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (!OPEN_TOPIC_ENABLED) return;
  upsertUser(ctx);
  if (await blockDuringOpenPay(ctx)) return;
  if (await blockDuringOpenReading(ctx)) return;
  if (await blockDuringPendingReading(ctx)) return;
  setState(uid, 'choose_spread');
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.reading.openDepthPrompt, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.openDepth3, 'odepth:open3')],
    [Markup.button.callback(L.buttons.openDepth5, 'odepth:open5')],
    ...navMenuRow(),
  ]));
});

bot.action(/^odepth:(open3|open5)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (!OPEN_TOPIC_ENABLED) return;
  upsertUser(ctx);
  const spread = SPREAD_BY_ID[ctx.match[1]];
  if (!spread) return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  // موضوعِ تایپ‌شده خودش حوزه است → مرحله‌ی «حول چی؟» رد می‌شود؛ مستقیم سراغ نوشتن موضوع
  patchSession(uid, { spreadId: spread.id, picks: [], focusKey: 'open' });
  setState(uid, 'await_question');
  await ctx.reply(L.reading.askTopic(toneV2For(uid)), { parse_mode: 'Markdown' });
});

/** کسرِ هزینه‌ی یک چیدمان در لحظه‌ی انتخابِ اندازه.
 *  خروجی true = پول کم شد و می‌شود ادامه داد؛ false = کم‌موجودی (پیامش همین‌جا رفت).
 *
 *  دو گاردِ **سینکرون قبل از اولین await** (الگوی `pick:` و `claimAmount`):
 *    ۱) `claimState` — دوبار-تپِ سریع روی دکمه‌ی اندازه نباید دو بار پول کم کند.
 *       `deduct` با شرطِ `balance >= ?` فقط جلوی اضافه‌برداشت را می‌گیرد، نه دوبار-خرید:
 *       کاربری با ۱۵ الماس که دو بار «۵ کارتی» را بزند از نظرِ SQL دو خریدِ معتبر دارد.
 *    ۲) `payForSpread` — کسر و ساختِ رکورد در یک تراکنش.
 *  هر دو **قبل از** اولین await اجرا می‌شوند، وگرنه دو تپ بینشان جا می‌شوند. */
async function chargeForSpread(ctx, uid, spread, focusKey) {
  // اگر تپِ دوم است، استیت از قبل await_question شده و ادعا شکست می‌خورد → بی‌صدا برگرد.
  if (stmts.claimState.run('await_question', uid, 'await_question').changes === 0) return false;
  const readingId = payForSpread(uid, spread, focusKey);
  if (!readingId) {
    // پول کم بود: استیت را برگردان (وگرنه کاربر در await_question گیر می‌کند) و پیامِ
    // کم‌موجودی را با همان سه دکمه‌ی ذخایر نشان بده.
    setState(uid, 'choose_spread');
    track(db, uid, EVENTS.PAYWALL_SHOWN, { spread: spread.id, price: spread.price, can_afford: false });
    const text = needBalanceText(uid, { type: spread.id, price: spread.price });
    const extra = { ...needBalanceExtra, ...Markup.inlineKeyboard(needBalanceRows(uid, null)) };
    try { await ctx.editMessageText(text, extra); }
    catch { await ctx.reply(text, extra).catch(() => {}); }
    return false;
  }
  patchSession(uid, { readingId });
  track(db, uid, 'reading_paid', { reading_id: readingId, spread: spread.id, price: spread.price });
  // تأییدِ کسر روی **همان** پیامِ «چند کارتی؟» می‌نشیند (نه پیامِ تازه).
  const paid = L.reading.paidForSpread(spread.size, spread.price, getBalance(uid), curOf(uid));
  try { await ctx.editMessageText(paid, { parse_mode: 'HTML' }); }
  catch { await ctx.reply(paid, { parse_mode: 'HTML' }).catch(() => {}); }
  await typing(ctx, PACE_S);
  return true;
}

bot.action(/^spread:(\w+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  const spread = SPREAD_BY_ID[ctx.match[1]];
  if (!spread) return;
  // دکمه‌ی «شروع فال» در پیام‌های زیادی هست (منو، بعد از تحویل، پوشِ milestone و…) و تا قبل از
  // این هیچ گاردی نداشت: کاربری که وسطِ پرداخت یا وسطِ یک فالِ باز بود، با یک تپ فلوی قبلی‌اش
  // را بی‌صدا از دست می‌داد. حالا مثل بقیه‌ی نقاطِ ورودِ منو گارد می‌شود (بند ۹ب).
  if (await blockDuringOpenPay(ctx)) return;
  if (await blockDuringOpenReading(ctx)) return;
  if (await blockDuringPendingReading(ctx)) return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  // propهای `topic` و `size` افزایشی‌اند (بند ۲ج/۳): `spread` دست‌نخورده می‌ماند تا
  // تحلیلِ تاریخی نشکند، ولی حالا می‌شود «کدام موضوع» را جدا از «چه عمقی» سنجید —
  // و همین ورودیِ آزمایشِ چرخشیِ جایگاه‌های منوست.
  track(db, uid, 'spread_selected', { spread: spread.id, topic: topicOf(spread.id) || '', size: spread.size });

  // 🪙 UX v2.6: کسرِ اعتبار **همین‌جا** (قبل از پرسیدنِ سؤال)، نه در پی‌والِ بعد از
  // انتخابِ کارت‌ها. اگر موفق شد، بقیه‌ی فلو دقیقاً مثل قبل ادامه می‌دهد ولی دیگر
  // هیچ پی‌والی جلوتر نمی‌آید؛ اگر موجودی کم بود، همین‌جا (و فقط همین‌جا) پیامِ
  // کم‌موجودی با همان سه دکمه‌ی ذخایر می‌آید.
  if (payAtSizeFor(uid)) {
    const focusKey = spread.open ? 'open'
      : (spread.focus || (spread.topic ? (getUser(uid)?.focus_area || 'question') : null));
    // سشن **قبل از** کسر نوشته می‌شود: اگر پروسه دقیقاً بینِ کسر و نوشتنِ سشن ری‌استارت
    // شود، فالِ پرداخت‌شده بدونِ spreadId می‌ماند و هیچ‌وقت به finishPicking نمی‌رسد.
    patchSession(uid, { spreadId: spread.id, picks: [], focusKey });
    if (!(await chargeForSpread(ctx, uid, spread, focusKey))) return;
    setState(uid, 'await_question');
    return ctx.reply(spread.open ? L.reading.askTopic(toneV2For(uid)) : L.reading.askQuestion(toneV2For(uid)),
      { parse_mode: 'Markdown' });
  }

  // نسل چهارم (UX v2.1): موضوع را کاربر **قبلاً** انتخاب کرده، پس مرحله‌ی «حول چه
  // موضوعی؟» در هیچ حالتی اجرا نمی‌شود. این شرط عمداً روی `spread.topic` است نه روی
  // `spread.focus`: «بله و خیر» و «دوراهی» حوزه‌ی تمرکز ندارند و بدونِ این شرط دقیقاً
  // به همان مرحله‌ی حذف‌شده می‌افتادند (یک باگِ خاموش که فقط در آن دو موضوع دیده می‌شد).
  if (spread.topic) {
    patchSession(uid, {
      spreadId: spread.id, picks: [],
      focusKey: spread.focus || getUser(uid)?.focus_area || 'question',
    });
    setState(uid, 'await_question');
    return ctx.reply(spread.open ? L.reading.askTopic(toneV2For(uid)) : L.reading.askQuestion(toneV2For(uid)),
      { parse_mode: 'Markdown' });
  }

  // فالِ `open` (کاتالوگِ نسل سومِ UX v2): سؤال را خودش می‌نویسد، پس هیچ مرحله‌ی موضوعی نیست.
  if (spread.open) {
    patchSession(uid, { spreadId: spread.id, picks: [], focusKey: 'open' });
    setState(uid, 'await_question');
    return ctx.reply(L.reading.askTopic(toneV2For(uid)), { parse_mode: 'Markdown' });
  }

  // فال موضوعی (عشق/کار/پول/…): حوزه همان موضوع فال است — مرحله‌ی «حول چی؟» حذف
  if (spread.focus) {
    patchSession(uid, { spreadId: spread.id, picks: [], focusKey: spread.focus });
    setState(uid, 'await_question');
    return ctx.reply(L.reading.askQuestion(toneV2For(uid)), { parse_mode: 'Markdown' });
  }

  // فال عمومی (گذشته/حال/آینده، آری/نه، دوراهی، سلتی): حوزه‌ی تمرکز
  patchSession(uid, { spreadId: spread.id, picks: [], focusKey: null });
  const user = getUser(uid);
  // اگر حوزه‌اش را داریم و کمتر از یک هفته از آخرین پرسش گذشته → همان را بی‌سؤال به‌کار می‌بریم
  // (سؤال «این خوانش حول فلان باشه؟» حذف شد؛ فقط اولین ورود + بازپرسیِ حداکثر هفته‌ای‌یک‌بار).
  const fresh = user.focus_area && (Date.now() / 1000 - (user.focus_asked_at || 0)) < FOCUS_REASK_DAYS * 86400;
  if (fresh) {
    patchSession(uid, { focusKey: user.focus_area });
    setState(uid, 'await_question');
    return ctx.reply(L.reading.askQuestion(toneV2For(uid)), { parse_mode: 'Markdown' });
  }
  // بازپرسیِ هفتگی (یا اولین بار): بدون مقدمه‌ی «بذار یه کم بشناسمت»
  setState(uid, 'confirm_focus');
  await ctx.reply(L.reading.askFocusAgain, Markup.inlineKeyboard(
    L.buttons.focusOptions.map(([key, label]) => [Markup.button.callback(label, `focus:${key}`)])
  ));
});

// دکمه‌ی «مشاهده همه فال‌ها» — همه‌جا (منوی فال، پایانِ فال، بعدِ کارتِ روز) همین یکی است.
// UX v2.3: همان پیام ادیت می‌شود («از کجا شروع کنیم؟» → «یکی از فال‌ها رو انتخاب کن»).
bot.action('catalog_go', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  return showCatalog(ctx, true, true);
});

/* ═══ انتخابِ موضوع → انتخابِ اندازه (UX v2.1) ═══
   دو انتخابِ جدا، چون قیمت فقط تابعِ **اندازه** است نه موضوع: هر موضوعی می‌تواند
   ۳ یا ۵ یا ۱۰ کارتی تفسیر شود و کاربر همان‌جا می‌بیند چقدر می‌دهد (هر کارت = ۱ الماس).
   خودِ دکمه‌ی اندازه یک `spread:<topic><size>` می‌زند، پس همه‌ی گاردها و مسیرِ موجود
   دست‌نخورده می‌ماند و هیچ شاخه‌ی جدیدی در فلوی فال ساخته نمی‌شود. */
// صفحه‌ی انتخابِ اندازه: متن + کیبورد در یک تابع، چون هم `topic:` آن را می‌سازد و هم
// (در صورتِ نیاز) هر نقطه‌ی دیگری که بخواهد همین صفحه را دوباره رندر کند.
// ⚠️ `parse_mode: 'HTML'` لازم است چون خطِ موجودی داخلِ باکسِ نقل‌قول می‌رود.
function pickSizeScreen(uid, t, from) {
  const cur = curOf(uid);
  return [L.reading.pickSize(getBalance(uid), cur), {
    parse_mode: 'HTML',
    ...Markup.inlineKeyboard([
      ...SIZES_V3.map((size) => {
        const sp = SPREAD_BY_ID[spreadIdOf(t.key, size)];
        // قیمت از خودِ رکوردِ چیدمان می‌آید (تک‌منبعِ قیمت)، نه از ضربِ دوباره‌ی اندازه.
        return [Markup.button.callback(L.buttons.topicSize(size, sp.price, cur), `spread:${sp.id}`)];
      }),
      // آخرین گزینه: بازگشتِ **یک قدمی** به همان منویی که کاربر از آن آمده.
      [Markup.button.callback(L.buttons.backToMenu, `tback:${from}`)],
    ]),
  }];
}

// پسوندِ اختیاریِ `:a` = «از لیستِ کامل آمده». `\w` دونقطه را نمی‌گیرد، پس گروهِ اول
// هیچ‌وقت پسوند را نمی‌بلعد و دکمه‌های کهنه‌ی بدونِ پسوند (که در چتِ کاربران مانده‌اند)
// دقیقاً مثل قبل کار می‌کنند و به منوی کوتاه برمی‌گردند (بند ۲ج/۶).
bot.action(/^topic:(\w+)(?::(a))?$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  const t = TOPIC_BY_KEY[ctx.match[1]];
  if (!t) return;
  if (await blockDuringOpenPay(ctx)) return;
  if (await blockDuringOpenReading(ctx)) return;
  if (await blockDuringPendingReading(ctx)) return;
  setState(uid, 'choose_spread');
  track(db, uid, 'topic_selected', { topic: t.key });
  // UX v2.3: به‌جای «کشتنِ کیبوردِ پیامِ قبلی + یک پیامِ جدید»، همین پیام به صفحه‌ی اندازه
  // ادیت می‌شود (الگوی cat_guide/cat_back). این تنها راهی است که دکمه‌ی بازگشت واقعاً
  // «یک قدم» باشد: همان پیام دوباره به منوی قبلی برمی‌گردد و چت شلوغ نمی‌شود.
  const [text, extra] = pickSizeScreen(uid, t, ctx.match[2] === 'a' ? 'a' : 'm');
  try { await ctx.editMessageText(text, extra); }
  catch {
    // مسیرِ کهنه: پیام قابلِ ادیت نبود (عکس، پیامِ خیلی قدیمی، پاک‌شده). دقیقاً مثل قبل
    // عمل می‌کنیم: کیبوردِ مبدأ کشته می‌شود تا دوباره‌زدنی نماند، بعد پیامِ جدید می‌رود.
    try { await ctx.editMessageReplyMarkup(undefined); } catch {}
    await ctx.reply(text, extra).catch(() => {});
  }
});

// ◀️ بازگشتِ یک‌قدمی از صفحه‌ی اندازه به همان منوی مبدأ (بدونِ پیامِ جدید، بدونِ ریست‌کردنِ
// کلِ فلو). در مسیرِ عادی استیت همان `choose_spread` است که `topic:` گذاشته، پس این فقط یک
// **رندرِ دوباره** است و عمداً هیچ استیتی نمی‌نویسد.
// ⚠️ ولی گاردها لازم‌اند: این دکمه در پیام‌های قدیمیِ چت می‌ماند و کاربری که حالا وسطِ
// پرداخت یا وسطِ یک فالِ باز است ممکن است بزندش. چون هر دو گارد روی **استیت** کار می‌کنند،
// نوشتنِ استیت این‌جا (یا حتی رد شدن بی‌گارد) فاکتور/فالِ باز را بی‌صدا یتیم می‌کرد.
bot.action(/^tback:([ma])$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (await blockDuringOpenPay(ctx)) return;
  if (await blockDuringOpenReading(ctx)) return;
  if (await blockDuringPendingReading(ctx)) return;
  const [text, kb] = topicMenuScreen(uid, ctx.match[1]);
  try { await ctx.editMessageText(text, kb); }
  catch { await ctx.reply(text, kb).catch(() => {}); }
});

// دکمه‌ی «همه فال‌ها» زیر پیام «یه قرار کوچیک» آنبوردینگ: معادلِ «فال بگیر» ولی به‌جای
// پیام جدید، همین پیام را به کاتالوگ ادیت می‌کند (بدونِ شلوغیِ چت). اگر ادیت نشد (پیام
// خیلی قدیمی/حذف‌شده)، به showCatalog برمی‌گردیم تا کاربر بن‌بست نخورد.
bot.action('onboard_allspreads', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  const uid = ctx.from.id;
  upsertUser(ctx);
  // ⚠️ این هندلر `setSession(uid, null)` می‌کند، پس **باید** همان سه گاردِ showCatalog را
  // داشته باشد؛ وگرنه یک فالِ در جریان (یا پول‌داده) را بی‌صدا یتیم می‌کند. تا v3.17.0
  // فقط گاردِ پرداخت را داشت.
  if (await blockDuringOpenPay(ctx, INTENT.READING)) return;
  if (await blockDuringOpenReading(ctx, INTENT.READING)) return;
  if (await blockDuringPendingReading(ctx)) return;
  if (await blockDuringDelivering(ctx)) return;
  if (await blockDuringOpenLucky(ctx)) return;
  setState(uid, 'choose_spread');
  setSession(uid, null);
  try {
    // `catalogKb()` بدونِ uid یعنی کاربرِ دنیای الماس کاتالوگِ تومانی می‌دید
    await ctx.editMessageText(L.reading.catalog, Markup.inlineKeyboard(catalogKb(uid)));
  } catch { return showCatalog(ctx); }
});

/* ---------- دریافت سؤال → فضاسازی → تنفس ---------- */
async function handleQuestion(ctx, question, audio = null) {
  const uid = ctx.from.id;
  const spread = SPREAD_BY_ID[getSession(uid).spreadId];
  if (!spread) { setState(uid, 'idle'); return ctx.reply(L.errors.stateLost, mainKeyboard(ctx.from.id)); }
  // هر دو فیلد **همیشه** با هم نوشته می‌شوند، حتی وقتی خالی‌اند. اگر فقط در شاخه‌ی ویس
  // ست می‌شدند، سشن merge می‌شود و ویسِ فالِ قبلی به فالِ بعدیِ متنی می‌چسبید — یعنی مدل
  // صدای یک سؤال را با متنِ سؤالِ دیگری می‌شنید. این تک‌نقطه جلوی آن را می‌گیرد.
  patchSession(uid, {
    question: question.slice(0, 1500),
    questionAudio: audio?.id || '',
    questionAudioFmt: audio?.fmt || '',
  });
  setState(uid, 'breathing');
  track(db, uid, 'question_submitted', { spread: spread.id, voice: !!(ctx.message?.voice || ctx.message?.audio) });
  await typing(ctx, PACE_S);
  // مشتری ثابت (۲+ فال کامل) آیین کوتاه‌تر می‌گیرد — مثل تاروت‌خوان واقعی با مشتری آشنا
  if (stmts.countDelivered.get(uid).c >= 2) {
    await ctx.reply(L.reading.atmosphereShort);
  } else {
    await ctx.reply(L.reading.atmosphere1);
    await typing(ctx, PACE_M);
    // «کارت‌ها قرار نیست بترسوننت» یک جمله‌ی دلداریِ اضافه است که در لحنِ جدید حذف می‌شود
    // (تصمیمِ مالک: این جمله‌ها در طولِ جرنی پراکنده‌اند و باید بروند).
    if (!toneV2For(uid)) await ctx.reply(L.reading.atmosphere2);
  }
  await typing(ctx, PACE_M);
  await ctx.reply(L.reading.breathing, Markup.inlineKeyboard([[Markup.button.callback(L.buttons.ready, 'ready_breath')]]));
}

/* ---------- بُر زدن با توقف کاربر ---------- */
bot.action('ready_breath', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (getState(uid) !== 'breathing') return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  setState(uid, 'shuffling');
  await typing(ctx, PACE_S, 'upload_photo');
  await sendCardPhoto(ctx, 'back', L.reading.shuffleCaption, { spoiler: false });
  const m = await ctx.reply(L.reading.shuffleFrames[0], Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.stopShuffle, 'shuffle_stop')],
  ]));
  patchSession(uid, { shuffleMsgId: m.message_id });
  // انیمیشن شافل: بُر زدن ادامه دارد تا خودِ کاربر «نگه‌دار» را بزند — هرگز خودکار جلو نمی‌رویم.
  // بعد از ~۲ دقیقه فقط ادیت‌کردن متوقف می‌شود (ریت‌لیمیت تلگرام) ولی دکمه سر جایش می‌ماند.
  (async () => {
    for (let i = 1; i < 90; i++) {
      await sleep(1300);
      if (getState(uid) !== 'shuffling' || getSession(uid).shuffleMsgId !== m.message_id) return;
      const frame = L.reading.shuffleFrames[i % L.reading.shuffleFrames.length];
      try {
        await ctx.telegram.editMessageText(ctx.chat.id, m.message_id, undefined, frame, {
          reply_markup: Markup.inlineKeyboard([[Markup.button.callback(L.buttons.stopShuffle, 'shuffle_stop')]]).reply_markup,
        });
      } catch {}
    }
  })().catch(e => logErr('shuffle anim:', e.message));
});

bot.action('shuffle_stop', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery('✋').catch(() => {});
  if (getState(uid) !== 'shuffling') return;
  await startPicking(ctx, uid, getSession(uid).shuffleMsgId);
});

function pickGridKb(picks) {
  const rows = [];
  for (let r = 0; r < 6; r++) {
    rows.push(Array.from({ length: 4 }, (_, c) => {
      const i = r * 4 + c;
      return Markup.button.callback(picks.includes(i) ? '✨' : '🂠', `pick:${i}`);
    }));
  }
  return Markup.inlineKeyboard(rows);
}

async function startPicking(ctx, uid, shuffleMsgId) {
  // seed قطعی: بعد از این لحظه شافل و جهت کارت‌ها ثابت است (حتی بعد از ری‌استارت)
  const seed = `r:${uid}:${shuffleMsgId}:${Date.now()}`;
  const spread = SPREAD_BY_ID[getSession(uid).spreadId];
  // UX v2: کاربر **همه‌ی** کارت‌ها را خودش می‌چیند (۳، ۵ یا ۱۰ تا)، نه سه‌تا و بقیه
  // خودکار. تصمیمِ صریحِ مالک: حسِ «خودم کارتم را کشیدم» بخشی از خودِ محصول است و
  // کارتِ خودکار آن را از بین می‌برد. گریدِ ۲۴تایی برای ۱۰ انتخاب هم جا دارد.
  // در دنیای قدیم مثل قبل: حداکثر سه‌تا (فالِ کوچک‌تر به اندازه‌ی خودش).
  const need = uxV2For(uid)
    ? (spread?.size || USER_PICKS)
    : Math.min(USER_PICKS, spread?.size || USER_PICKS);
  setState(uid, 'picking'); // قبل از هر await — گارد برابر دوباره‌کاری
  patchSession(uid, { seed, picks: [], need });
  if (shuffleMsgId) {
    try { await ctx.telegram.editMessageText(ctx.chat.id, shuffleMsgId, undefined, '🂠 ✋'); } catch {}
  }
  await ctx.reply(L.reading.pickPrompt(need), pickGridKb([]));
}

bot.action(/^pick:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  const i = parseInt(ctx.match[1], 10);
  if (getState(uid) !== 'picking') return ctx.answerCbQuery().catch(() => {});
  // ثبت همگام قبل از هر await — ضد race در کلیک‌های پشت‌سرهم
  const s = getSession(uid);
  const need = s.need || USER_PICKS;
  if (!s.picks || s.picks.includes(i) || s.picks.length >= need) {
    return ctx.answerCbQuery().catch(() => {});
  }
  s.picks.push(i);
  const done = s.picks.length >= need;
  if (done) setState(uid, 'confirm_pay'); // قفل فوری قبل از await
  setSession(uid, s);

  await ctx.answerCbQuery('✨').catch(() => {});
  try { await ctx.editMessageReplyMarkup(pickGridKb(s.picks).reply_markup); } catch {}
  if (!done) return;
  await finishPicking(ctx, uid, s);
});

async function finishPicking(ctx, uid, s) {
  const spread = SPREAD_BY_ID[s.spreadId];
  const user = getUser(uid);
  const cards = drawCards(s.seed, s.picks, spread.size);
  const focusArea = s.focusKey || user.focus_area || '';

  // 🪙 UX v2.6: اگر لحظه‌ی انتخابِ اندازه پول داده شده، رکورد از قبل هست و فقط کارت‌هایش
  // نوشته می‌شود (شرطِ `cards_json=''` جلوی کشیدنِ دوباره‌ی کارت‌های یک فالِ پرداخت‌شده
  // را می‌گیرد). وگرنه دقیقاً مثل قبل یک رکوردِ تازه ساخته می‌شود.
  const prepaid = payAtSizeFor(uid) && s.readingId
    && stmts.getReading.get(s.readingId)?.status === 'paid' ? s.readingId : 0;
  const readingId = prepaid || Number(stmts.insertReading.run(
    uid, spread.id, spread.price, focusArea, s.question || '', s.seed, JSON.stringify(cards),
    s.questionAudio || '', s.questionAudioFmt || ''
  ).lastInsertRowid);
  if (prepaid) {
    stmts.setReadingCards.run(s.seed, JSON.stringify(cards), focusArea, s.question || '',
      s.questionAudio || '', s.questionAudioFmt || '', readingId);
  }
  patchSession(uid, { readingId });
  track(db, uid, 'cards_picked', { spread: spread.id, reading_id: readingId });

  // فالِ از-پیش-پرداخت‌شده هیچ پی‌والی ندارد: مستقیم می‌رود سرِ افشا.
  if (prepaid) {
    if (spread.size > s.picks.length) await ctx.reply(L.reading.extraCardsNote(spread.size - s.picks.length));
    stmts.setReadingStatus.run('started', readingId);
    track(db, uid, 'reading_started', { reading_id: readingId, price: spread.price });
    setState(uid, 'revealing');
    patchSession(uid, { readingId, revealIdx: 0, fbDone: false });
    return startReveal(ctx, uid, readingId);
  }

  // ⚠️ اینجا عمداً هیچ فراخوانیِ LLM نیست. پیامِ بعدی پی‌وال است و کاربر هنوز تصمیم نگرفته
  // (بند ۹ ریشه، قاعده‌ی هزینه). خوانش فقط بعد از کسرِ اعتبار در `unlock:` شروع می‌شود.
  await typing(ctx, PACE_M);
  if (spread.size > s.picks.length) await ctx.reply(L.reading.extraCardsNote(spread.size - s.picks.length));

  const balance = getBalance(uid);
  track(db, uid, EVENTS.PAYWALL_SHOWN, { reading_id: readingId, price: spread.price, can_afford: balance >= spread.price });
  if (balance >= spread.price) {
    const reading = { type: spread.id, price: spread.price };
    const body = COVERED_PAYWALL_ENABLED ? coveredText(uid, reading) : L.reading.paywall(spread.price);
    await ctx.reply(body, Markup.inlineKeyboard([
      coveredRow(readingId, spread.price, uid),
      [Markup.button.callback(L.buttons.cancel, `rcancel:${readingId}`)],
    ]));
  } else {
    // یک پیامِ کوتاه و مستقیم (پیامِ اتمسفریکِ paywall این‌جا حذف شد تا کاربر دو پیام پشت‌سرهم نگیرد)
    await ctx.reply(needBalanceText(uid, { type: spread.id, price: spread.price }), {
      ...needBalanceExtra,
      ...Markup.inlineKeyboard([
        ...needBalanceRows(uid, { id: readingId, price: spread.price }),
        ...freeMenuRow(),
        [Markup.button.callback(L.buttons.cancel, `rcancel:${readingId}`)],
      ]),
    });
  }
}

bot.action(/^rcancel:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const readingId = parseInt(ctx.match[1], 10);
  // 🪙 فالِ پرداخت‌شده (paid) این‌جا **ریفاند** می‌شود، نه فقط canceled — وگرنه از v2.6
  // به بعد هر انصراف پولِ کاربر را می‌خورد.
  const back = cancelReading(uid, readingId);
  setState(uid, 'idle');
  setSession(uid, null);
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  if (back) await ctx.reply(L.reading.refundedOnCancel(back, curOf(uid))).catch(() => {});
  await replyCanceled(ctx, uid);
});

// 🧭 بازگشت به منوی اصلی از هر استیتِ میانی (قرارداد State Management). فالِ هنوز-پرداخت‌نشده لغو می‌شود؛
// فالِ started/delivered (پول‌داده) هرگز دست نمی‌خورد. همیشه ثبت می‌شود (حتی با گاردِ خاموش) تا دکمه‌ی
// کش‌شده خطا ندهد. اگر کاربر وسط پرداخت است، فاکتور را یتیم نمی‌کند؛ به‌جایش انصراف را پیشنهاد می‌دهد.
bot.action('nav:menu', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const pid = getSession(uid)?.paymentId;
  if (PAY_STATES.includes(getState(uid)) && pid) {
    return ctx.reply(L.errors.openInvoice, Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.cancel, `pay_cancel:${pid}`)],
    ]));
  }
  if (await blockDuringDelivering(ctx)) return;
  if (await blockDuringOpenLucky(ctx)) return;   // فالِ پول‌داده‌ی وسطِ افشا پاک نمی‌شود
  const s = getSession(uid);
  const back = s?.readingId ? cancelReading(uid, s.readingId) : 0;
  setState(uid, 'idle');
  setSession(uid, null);
  if (back) await ctx.reply(L.reading.refundedOnCancel(back, curOf(uid))).catch(() => {});
  // 🎹 **نقطه‌ی مجازِ ۱ برای صدورِ کیبورد** (قراردادِ مالک): «بازگشت تا رسیدن به منوی اصلی».
  // پس این‌جا پیامِ تأیید با `mainKeyboard` می‌رود، نه یک ادیت — ادیت نمی‌تواند کیبوردِ
  // reply را حمل کند (تلگرام در ادیت فقط inline می‌پذیرد) و کاربری که هنوز کیبورد نگرفته
  // این‌جا بن‌بست می‌خورد. کیبوردِ پیامِ مبدأ کشته می‌شود تا دوباره‌زدنی نماند.
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  stmts.setKbShown.run(uid);   // پنجره‌ی مهاجرتِ کیبورد را می‌بندد (KB_V2_EPOCH پایین)
  return ctx.reply(L.reading.backToMenu, mainKeyboard(uid));
});

// گاردِ «فالِ باز» — «اونو ادامه می‌دم»: همان پیامِ آخرِ فلو دوباره نشان داده می‌شود (کاربر سرِ کارش برمی‌گردد).
bot.action('reading:resume', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await resendCurrentStep(ctx, ctx.from.id);
});
// گاردِ «فالِ باز» — «انصراف»: فال لغو و بازگشت به منوی اصلی (همان‌جایی که قبل از شروع فال بود).
bot.action('reading:cancel', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (await blockDuringDelivering(ctx)) return;   // دکمه‌ی کهنه وسطِ افشا فال را نمی‌کُشد
  const s = getSession(uid);
  const back = s?.readingId ? cancelReading(uid, s.readingId) : 0;
  setState(uid, 'idle');
  setSession(uid, null);
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  if (back) await ctx.reply(L.reading.refundedOnCancel(back, curOf(uid))).catch(() => {});
  await replyCanceled(ctx, uid);
});

/* ---------- پی‌وال → کسر → افشای مرحله‌ای ---------- */
bot.action(/^unlock:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  const readingId = parseInt(ctx.match[1], 10);
  const r = stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid) return ctx.answerCbQuery().catch(() => {});
  if (r.status !== 'pending_payment') return ctx.answerCbQuery('✅').catch(() => {});
  // کسر اتمیک (WHERE balance >= price) — قبل از هر await وضعیت را قفل می‌کنیم
  if (r.price > 0) {
    const res = stmts.deduct.run(r.price, uid, r.price);
    if (res.changes === 0) {
      await ctx.answerCbQuery().catch(() => {});
      return ctx.reply(needBalanceText(uid, r), {
        ...needBalanceExtra,
        ...Markup.inlineKeyboard([
          ...needBalanceRows(uid, r),
          [Markup.button.callback(L.buttons.cancel, `rcancel:${r.id}`)],
        ]),
      });
    }
  }
  stmts.setReadingStatus.run('started', readingId);
  track(db, uid, 'reading_started', { reading_id: readingId, price: r.price });
  setState(uid, 'revealing');
  patchSession(uid, { readingId, revealIdx: 0, fbDone: false });
  await ctx.answerCbQuery('🔮').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await startReveal(ctx, uid, readingId);
});

// پیام لودینگ پویا تا آماده‌شدن LLM (اگر پیش‌فراخوانی هنوز نرسیده باشد)
async function waitLLMWithLoading(ctx, uid, readingId) {
  const r = stmts.getReading.get(readingId);
  if (r?.llm_json) { try { return JSON.parse(r.llm_json); } catch {} }
  const frame = loadingFrame(L.reading.loadingLabel);
  const msg = await ctx.reply(frame(0));
  let i = 1, done = false;
  const startedAt = Date.now();
  (async () => { // پیام لودینگ پویا؛ بدون await تا افشا معطل نماند
    // ⏱ ضرب‌آهنگ **متغیر** است، نه یک عددِ ثابت (جزئیاتِ کامل در `loading.js`):
    // ده ثانیه‌ی اول تند (کاربر همان‌جا تصمیم می‌گیرد «کار می‌کند یا خراب است»)، بعد
    // آرام. این تنها راهی بود که هم ایرادِ مالک («خیلی سریع‌تر، الان معلوم نیست ویتینگه»)
    // را جواب بدهد و هم برای انتظارِ ۶۰ ثانیه‌ای زیرِ سقفِ ~۱ ادیت-در-ثانیه‌ی تلگرام بماند.
    while (!done) {
      await sleep(pace(Date.now() - startedAt));
      if (done) break;
      try {
        await ctx.telegram.editMessageText(ctx.chat.id, msg.message_id, undefined, frame(i));
      } catch {}
      i++;
    }
  })().catch(() => {});
  const result = await awaitReadingLLM(uid, readingId);
  done = true;
  try { await ctx.telegram.deleteMessage(ctx.chat.id, msg.message_id); } catch {}
  return result;
}

async function startReveal(ctx, uid, readingId) {
  // نقشه‌ی راه **قبل از** پیام‌های انتظار: کاربر تازه پول داده و باید یک بار بداند مسیر
  // چیست (اول کارت‌ها دونه‌دونه، بعد جوابِ کامل). انتظارِ بدونِ نقشه طولانی‌تر حس می‌شود.
  if (v4For(uid)) {
    const rr = stmts.getReading.get(readingId);
    const n = rr ? JSON.parse(rr.cards_json).length : 0;
    if (n) await ctx.reply(L.reading.flowIntro());
  }
  const llm = await waitLLMWithLoading(ctx, uid, readingId);
  const r = stmts.getReading.get(readingId);
  if (!llm) {
    // شکست نهایی (بعد از ۳×Flash + ۲×فالبک) → برگشت کامل مبلغ + دکمه‌ی تلاش مجدد از همان نقطه
    if (r && r.status === 'started') {
      if (r.price > 0) stmts.credit.run(r.price, uid);
      stmts.setReadingStatus.run('refunded', readingId);
      track(db, uid, EVENTS.REFUND, { reading_id: readingId, amount: r.price });
    }
    setState(uid, 'idle');
    setSession(uid, null);
    return ctx.reply(L.reading.refunded(curOf(uid)), Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.retry, `retryr:${readingId}`)],
    ]));
  }
  await revealNext(ctx, uid, readingId);
}

// تلاش مجدد بعد از refund: همان کارت‌ها و همان سؤال — فقط فراخوانی LLM از نو
bot.action(/^retryr:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  const readingId = parseInt(ctx.match[1], 10);
  const r = stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid) return ctx.answerCbQuery().catch(() => {});
  if (r.status !== 'refunded') return ctx.answerCbQuery('✅').catch(() => {});
  // 🪙 گاردِ عمقی (UX v2.6): فالی که قبل از کشیدنِ کارت‌ها ریفاند شده `cards_json` خالی
  // دارد و `startReveal` رویش با JSON.parse('') کرش می‌کند. امروز هیچ دکمه‌ی retry برای
  // چنین رکوردی ساخته نمی‌شود، ولی این مسیر پول کم می‌کند پس گاردش این‌جا می‌ماند.
  if (!r.cards_json) return ctx.answerCbQuery('✅').catch(() => {});
  if (r.price > 0) {
    const res = stmts.deduct.run(r.price, uid, r.price);
    if (res.changes === 0) {
      await ctx.answerCbQuery().catch(() => {});
      return ctx.reply(needBalanceText(uid, r), {
        ...needBalanceExtra,
        ...Markup.inlineKeyboard([
          ...needBalanceRows(uid, r),
          [Markup.button.callback(L.buttons.cancel, `rcancel:${r.id}`)],
        ]),
      });
    }
  }
  stmts.setReadingStatus.run('started', readingId);
  track(db, uid, 'reading_started', { reading_id: readingId, price: r.price, retry: true });
  setState(uid, 'revealing');
  setSession(uid, { spreadId: r.type, readingId, revealIdx: 0, fbDone: false });
  await ctx.answerCbQuery('🔮').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await startReveal(ctx, uid, readingId);
});

async function revealNext(ctx, uid, readingId) {
  const r = stmts.getReading.get(readingId);
  if (!r || !r.llm_json) return;
  const llm = JSON.parse(r.llm_json);
  const cards = JSON.parse(r.cards_json);
  const spread = SPREAD_BY_ID[r.type];
  const s = getSession(uid);
  const idx = s.revealIdx || 0;
  if (idx >= cards.length) return finishReading(ctx, uid, readingId);

  const card = cards[idx];
  const info = CARD_BY_KEY[card.key];
  patchSession(uid, { revealIdx: idx + 1 }); // قبل از await — دکمه‌ی تکراری دوباره همین کارت را نفرستد

  await typing(ctx, PACE_S, 'upload_photo');
  // در v4 کپشن هم مثل متن، برچسبِ **ترتیبی** می‌گیرد نه نامِ جایگاه — وگرنه کاربر هم‌زمان
  // «کارت قلب تو» و «کارت اولت» را می‌بیند و تناقض حس می‌کند.
  await sendCardPhoto(ctx, card.key, v4For(uid)
    ? L.reading.revealCaptionV4(L.prompts.cardLabels(cards.length)[idx], info, card.reversed)
    : L.reading.revealCaption(spread.positions[idx]?.fa || `کارت ${idx + 1}`, info, card.reversed));
  await sleep(PACE_REVEAL);
  await typing(ctx, PACE_S);

  // v4: در مرحله‌ی افشا فقط یک تیزرِ کوتاه درباره‌ی خودِ کارت می‌آید تا تعلیق حفظ شود و
  // کاربر در ساختنِ روایت همراه شود. تحلیلِ کامل و جواب، در متنِ نهایی می‌آید.
  const v4 = v4For(uid);
  const interp = (v4 ? llm.cards[idx]?.teaser : llm.cards[idx]?.text) || '';
  const isLast = idx === cards.length - 1;
  const midIdx = Math.floor((cards.length - 1) / 2);
  // v4: هیچ بازخوردی وسطِ خوانش گرفته نمی‌شود (تعلیق را می‌شکست و چیزی را می‌سنجید که
  // هنوز تمام نشده بود). بازخورد به آخرِ کار منتقل شده — پایینِ finishReading.
  const askFeedback = !v4 && idx === midIdx && !s.fbDone && llm.confirmation_question;

  if (askFeedback) {
    await ctx.reply(esc(interp), { parse_mode: 'HTML' });
    await sleep(PACE_M);
    setState(uid, 'feedback');
    await ctx.reply(llm.confirmation_question, Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.fbYes, `fb:yes:${readingId}`)],
      [Markup.button.callback(L.buttons.fbSomewhat, `fb:some:${readingId}`)],
      [Markup.button.callback(L.buttons.fbNo, `fb:no:${readingId}`)],
    ]));
    return;
  }

  // v4: کارتِ آخر هم دکمه دارد. قبلاً بعد از آخرین تیزر، جمع‌بندی خودکار می‌آمد و کاربر
  // ناگهان با دیوارِ متن روبه‌رو می‌شد؛ حالا خودش لحظه‌ی جواب را انتخاب می‌کند و همان
  // انتخاب، اوجِ انتظار را می‌سازد.
  const lastRow = v4
    ? [[Markup.button.callback(L.buttons.finalAnswer, `final:${readingId}`)]]
    : null;
  await ctx.reply(esc(interp), {
    parse_mode: 'HTML',
    // دکمه شماره‌ی کارتِ بعدی را حمل می‌کند تا دابل‌تاچ/دکمه‌ی کهنه هرگز کارت تکراری یا پرشی نفرستد
    ...(isLast
      ? (lastRow ? Markup.inlineKeyboard(lastRow) : {})
      : Markup.inlineKeyboard([[Markup.button.callback(L.buttons.nextCard, `next:${readingId}:${idx + 1}`)]])),
  });
  if (isLast && !v4) await finishReading(ctx, uid, readingId);
}

bot.action(/^next:(\d+):(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery('🎴').catch(() => {});
  const readingId = parseInt(ctx.match[1], 10);
  const expectIdx = parseInt(ctx.match[2], 10);
  const s = getSession(uid);
  if (getState(uid) !== 'revealing' || s.readingId !== readingId || (s.revealIdx || 0) !== expectIdx) return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await revealNext(ctx, uid, readingId);
});

// دکمه‌ی «حالا جوابم رو بگو» زیرِ کارتِ آخر (v4). گاردِ دوبار-تپ **سینکرون و قبل از اولین
// await** است (الگوی `pick:`): بینِ شروعِ finishReading و لحظه‌ی delivered شدنِ رکورد چند
// ثانیه await هست و بدونِ این قفل، دو تپِ پشت‌سرهم کلِ جمع‌بندی را دو بار می‌فرستاد.
bot.action(/^final:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery('🔮').catch(() => {});
  const readingId = parseInt(ctx.match[1], 10);
  const s = getSession(uid);
  if (s.readingId !== readingId || s.finalDone) return;
  const r = stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid || r.status !== 'started') return;
  patchSession(uid, { finalDone: true }); // قفل قبل از هر await
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await finishReading(ctx, uid, readingId);
});

/* ---------- حلقه‌ی بازخورد وسط خوانش ---------- */
async function handleFeedback(ctx, uid, readingId, kind, freeText) {
  const r = stmts.getReading.get(readingId);
  if (!r) return;
  const llm = r.llm_json ? JSON.parse(r.llm_json) : null;
  stmts.setReadingFeedback.run(freeText ? `text: ${freeText.slice(0, 300)}` : kind, readingId);
  track(db, uid, EVENTS.FEEDBACK, { reading_id: readingId, kind: freeText ? 'text' : kind });
  patchSession(uid, { fbDone: true });
  setState(uid, 'revealing');

  if (kind === 'no' || freeText) {
    // مثل فالگیر واقعی: زاویه‌ی تفسیر با یک فراخوانی کوچک تصحیح می‌شود (فالبک: جمله‌ی همدلانه‌ی آماده)
    await typing(ctx, PACE_M);
    const s = getSession(uid);
    const midIdx = (s.revealIdx || 1) - 1;
    const cards = JSON.parse(r.cards_json);
    const recal = await orChatResilient(L.prompts.feedbackSystem, L.prompts.feedbackContext({
      confirmationQuestion: llm?.confirmation_question || '',
      userAnswer: freeText || 'نه دقیقاً',
      card: CARD_BY_KEY[cards[midIdx]?.key]?.fa || '',
      cardText: llm?.cards?.[midIdx]?.text || '',
      question: r.question,
    }), { maxTokens: 300 }, [FLASH, FALLBACK_MODEL])
      .then(res => res?.out || null).catch(e => { logErr('feedback LLM:', e.message); return null; });
    await ctx.reply(recal || L.reading.recalFallback);
  } else {
    const bridges = L.reading.positiveBridges;
    await ctx.reply(bridges[Math.floor((readingId + (kind === 'yes' ? 0 : 1)) % bridges.length)]);
  }
  await sleep(PACE_M);
  await revealNext(ctx, uid, readingId);
}

bot.action(/^fb:(yes|some|no):(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (getState(uid) !== 'feedback') return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await handleFeedback(ctx, uid, parseInt(ctx.match[2], 10), ctx.match[1], null);
});

/* ---------- پایان‌بندی + قلاب بازگشت ---------- */
// پیشنهاد شخصی‌سازی‌شده‌ی فال بعدی: بر اساس حوزه‌ی تمرکز کاربر + آنچه هنوز تجربه نکرده
// آی‌دی‌های هر دو نسلِ کاتالوگ با هم می‌آیند: `scoreSpreads` فقط روی چیدمان‌هایی کار می‌کند
// که در کاتالوگِ همان کاربر هستند، پس آی‌دیِ اضافه بی‌ضرر است و این‌طوری هیچ حوزه‌ای بعد از
// باز شدنِ کاتالوگِ جدید برای همه، بی‌پیشنهاد نمی‌ماند.
const FOCUS_SUGGEST = {
  love:      ['love', 'stayleave', 'crush', 'lovehate', 'commit', 'broken', 'family', 'choice', 'inner', 'celtic'],
  career:    ['career', 'money', 'migration', 'choice', 'celtic'],
  money:     ['money', 'career', 'choice', 'celtic'],
  inner:     ['inner', 'love', 'broken', 'three', 'celtic'],
  family:    ['family', 'love', 'inner', 'celtic'],
  migration: ['migration', 'choice', 'career', 'celtic'],
  question:  ['choice', 'yesno', 'love', 'celtic'],
};
/* ===== پیشنهاددهنده‌ی فال (v2.1.0 — امتیازیِ هاردکد، بدونِ LLM و بدونِ هیچ هزینه‌ای) =====
   قبلاً هرجا پیشنهاد می‌دادیم دو حالت بود: یا لیستِ ثابتِ حوزه، یا بدتر، دکمه‌ی هاردکدِ
   «گذشته، حال، آینده» زیرِ کارت روز — یعنی کاربری که همین الان همان فال را گرفته بود،
   دقیقه‌ای بعد دوباره همان را پیشنهاد می‌گرفت. حالا هر فال برای هر کاربر یک امتیاز دارد:

     امتیاز = ۱۰۰ + بونوسِ حوزه + بونوسِ اقبال عمومی − جریمه‌ی تازگی

   و مهم‌تر از امتیاز، یک **قفلِ سخت** هست: فالی که ظرفِ RECO_COOLDOWN_DAYS تحویل گرفته
   شده (و همیشه فالِ همین لحظه) اصلاً وارد رقابت نمی‌شود. این قانونِ نشکستنی است؛ حتی
   محبوب‌ترین فالِ ربات هم اگر تازه گرفته شده باشد نمایش داده نمی‌شود. */
const RECO_SLOTS = RECO.SLOTS;
let popCache = { at: 0, map: null };

// اقبال عمومی با کشِ ۱۰ دقیقه‌ای (کوئری روی کلِ readings است، نه per درخواست)
function popularity() {
  const now = Date.now();
  if (popCache.map && now - popCache.at < 600_000) return popCache.map;
  const map = new Map();
  try {
    const all = stmts.popByType.all();
    const max = Math.max(1, ...all.map(r => r.c));
    for (const r of all) map.set(r.type, r.c / max); // ۰..۱
  } catch (e) { logErr('popularity:', e.message); }
  popCache = { at: now, map };
  return map;
}

// جمع‌کردنِ دیتای کاربر و سپردنِ امتیازدهی به ماژولِ خالصِ reco.js
function recommendSpreads(uid, currentType, slots = RECO_SLOTS) {
  try {
    const focus = getUser(uid)?.focus_area || '';
    const lastByType = new Map();
    for (const r of stmts.lastByType.all(uid)) lastByType.set(r.type, r.last);
    return scoreSpreads(spreadsFor(coinsOn(uid)), {
      currentType, focus,
      focusIds: new Set(FOCUS_SUGGEST[focus] || []),
      popMap: popularity(),
      lastByType,
      nowS: Math.floor(Date.now() / 1000),
      slots,
    });
  } catch (e) {
    logErr('recommend:', e.message);
    // fail-safe: هرگز فالِ همین لحظه را برنگردان (قانونِ نشکستنیِ مالک)
    return spreadsFor(coinsOn(uid)).filter(s => s.id !== currentType).slice(0, slots);
  }
}

// پیشنهادِ **موضوع** (UX v2.1) — نه چیدمان. سابقه‌ی کاربر روی آی‌دیِ چیدمان ثبت شده
// (`love5`)، پس اول به موضوع تبدیل می‌شود تا قاعده‌ی «چیزی که تازه گرفته دوباره پیشنهاد
// نشود» روی موضوع کار کند، نه روی عمق: کسی که دیروز «عشق ۳ کارتی» گرفته، «عشق ۱۰ کارتی»
// هم برایش تکراری است.
function recommendTopics(uid, currentTopic, slots) {
  try {
    const focus = getUser(uid)?.focus_area || '';
    const lastByTopic = new Map();
    for (const r of stmts.lastByType.all(uid)) {
      const key = topicOf(r.type);
      if (!key) continue;
      lastByTopic.set(key, Math.max(lastByTopic.get(key) || 0, r.last));
    }
    const popMap = new Map();
    for (const [id, v] of popularity()) {
      const key = topicOf(id);
      if (key) popMap.set(key, Math.max(popMap.get(key) || 0, v));
    }
    return scoreSpreads(TOPICS_V3.map(t => ({ id: t.key, focus: t.focus })), {
      currentType: currentTopic, focus,
      focusIds: new Set(FOCUS_SUGGEST[focus] || []),
      popMap, lastByType: lastByTopic,
      nowS: Math.floor(Date.now() / 1000), slots,
    }).map(x => TOPIC_BY_KEY[x.id]).filter(Boolean);
  } catch (e) {
    logErr('recommendTopics:', e.message);
    return TOPICS_V3.filter(t => t.key !== currentTopic && t.key !== MENU_PIN).slice(0, slots);
  }
}

// ردیف‌های آماده‌ی پیشنهاد.
// UX v2.1 (تصمیمِ صریحِ مالک): «سؤال شخصی خودم» **همیشه** دکمه‌ی اول است، بعد دو
// پیشنهادِ داینامیک (با جریمه‌ی تازگی)، و آخر «مشاهده همه فال‌ها».
function recoRows(uid, currentType) {
  if (uxV2For(uid)) {
    const currentTopic = currentType ? topicOf(currentType) : null;
    const picks = recommendTopics(uid, currentTopic, 3)
      .filter(t => t.key !== MENU_PIN)   // پین جای خودش را دارد، دو بار نیاید
      .slice(0, 2);
    return [
      topicRow(MENU_PIN),
      ...picks.map(t => topicRow(t.key)),
      [Markup.button.callback(L.buttons.allSpreadsV2, 'catalog_go')],
    ].filter(Boolean);
  }
  const v2 = coinsOn(uid);
  const cur = curOf(uid);
  return [
    ...recommendSpreads(uid, currentType).map(sp => [Markup.button.callback(
      L.buttons.spread(sp, null, cur, faOf(sp, v2)), `spread:${sp.id}`)]),
    [Markup.button.callback(L.buttons.allSpreads, 'catalog_go')],
  ];
}

// پیامِ عمومیِ «ادامه‌ی کار با ربات» (UX v2.1، تصمیمِ صریحِ مالک): همان متن و دکمه‌هایی که
// بعد از تحویلِ فال نشان می‌دهیم («هر سؤال دیگه‌ای داری…» + recoRows + دعوت)، حالا هر
// جایی که یک فرآیند تمام یا لغو می‌شود هم می‌آید — به‌جای جمله‌ی صرفاً محاوره‌ایِ قدیمی
// («باشه، هر وقت آماده بودی همین‌جام»). کاربر باید همیشه یک قدمِ بعدیِ روشن جلوی چشمش
// داشته باشد، نه فقط تأییدِ اینکه فرآیند تمام شد.
// UX v2.3 (تصمیمِ صریحِ مالک): «منوی اصلی دقیقاً هم‌زمان با همین پیام باز شود» — چون این
// پیام دقیقاً همان لحظه‌ای می‌آید که یک شاخه‌ی اصلی تمام شده. یک پیام نمی‌تواند هم دکمه‌ی
// inline داشته باشد هم کیبوردِ ماندگار، پس `ensureMenu` (throttle‌دار) بلافاصله بعدش می‌آید
// و این‌جا تک‌نقطه‌ای می‌شود: هر نقطه‌ی «فرآیند تمام شد» خودکار کیبورد را هم تضمین می‌کند.
async function sendContinuePrompt(ctx, uid) {
  await ctx.reply(L.reading.nextOffersV3, Markup.inlineKeyboard([
    ...recoRows(uid, null),
    [Markup.button.url(L.buttons.share(referralBonusFor(uid), curOf(uid)), shareUrlFor(uid))],
  ]));
  await ensureMenu(ctx, uid);
}
// جایگزینِ نقاطِ لغوِ قدیمی (که قبلاً مستقیم L.reading.canceled را می‌فرستادند): در
// دنیای UX v2 پیامِ «ادامه» را می‌فرستد؛ در دنیای قدیم رفتار **دقیقاً** قبلی می‌ماند
// (رول‌بکِ یک‌خطی: uxV2For همیشه false → این تابع همیشه شاخه‌ی قدیم را می‌رود).
async function replyCanceled(ctx, uid) {
  // 🎯 اگر کاربر بابتِ رسیدن به چیزی انصراف داده بود، همان چیز می‌آید — نه پیامِ عمومی.
  // این تنها نقطه‌ی مصرف است، چون تک‌نقطه‌ی همه‌ی لغوهاست (قرارداد UX v2.2).
  if (await replayIntent(ctx, uid)) return;
  if (uxV2For(uid)) return sendContinuePrompt(ctx, uid);
  return ctx.reply(L.reading.canceled, mainKeyboard(uid));
}

// کیبوردِ منو نباید هیچ‌وقت گم شود: تلگرام کیبوردِ reply را تا جایگزینی نگه می‌دارد، ولی اگر
// کاربر آن را جمع کند و بعد فقط دکمه‌های inline ببیند، عملاً راهی برای تعامل ندارد. این تابع
// حداکثر هر KB_REFRESH_DAYS یک پیامِ کوتاه با کیبوردِ منو می‌فرستد (نه در آنبوردینگ).
const KB_REFRESH_DAYS = 3;
// 🚚 لحظه‌ی لانچِ UX v2 برای همه. مرزِ «کاربرِ قبل از لانچ» در پنجره‌ی یک‌باره‌ی مهاجرتِ
// کیبورد است (جزئیات داخلِ `ensureMenu`).
//
// ⚠️ چرا از DB خوانده می‌شود و **عددِ هاردکد نیست**: نسخه‌ی اول یک تایم‌استمپِ ثابت بود
// که لحظه‌ی نوشتنِ کد ست شد. بعد دیپلوی دو روز عقب افتاد (Actions خوابید) و آن عدد
// بی‌صدا غلط شد: `handleStart` در مسیرِ کاربرِ برگشته **بی‌قید** `setKbShown` می‌زند، پس
// هر کسی که در آن فاصله /start زد مهرِ «کیبورد گرفتم» خورد در حالی که کیبوردِ **تومانیِ
// قدیم** را گرفته بود. بعد از لانچ، گاردِ `kb_shown_at >= EPOCH` دقیقاً همان کوهورت را
// رد می‌کرد و آن‌ها برای همیشه بدونِ دکمه‌ی «کارت شانس» می‌ماندند — یعنی همان چیزی که
// این پنجره برای جلوگیری‌اش نوشته شده بود.
// حالا مرز، لحظه‌ی **اولین بوتِ همین نسخه** است و در خودِ دیتابیس مهر می‌شود، پس هر وقت
// دیپلوی انجام شود خودش را درست می‌کند و ری‌استارت هم عوضش نمی‌کند.
db.exec("CREATE TABLE IF NOT EXISTS migrations (key TEXT PRIMARY KEY, done_at INTEGER NOT NULL DEFAULT 0)");
db.prepare("INSERT OR IGNORE INTO migrations (key, done_at) VALUES ('ux_v2_launch', unixepoch())").run();
const KB_V2_EPOCH = db.prepare("SELECT done_at FROM migrations WHERE key='ux_v2_launch'").get()?.done_at || 0;
async function ensureMenu(ctx, uid) {
  try {
    // UX v2.4: در دنیای الماس این پیام اصلاً وجود ندارد (تصمیمِ صریحِ مالک: «نقشش اضافیه»).
    // آن‌جا کیبورد در دو نقطه‌ی قراردادِ v3.16.0 صادر می‌شود و تلگرام تا جایگزینی نگهش
    // می‌دارد. دنیای تومانی دست‌نخورده می‌ماند: آن‌جا این تابع تنها تورِ ایمنیِ کیبوردِ
    // گم‌شده است.
    //
    // 🚚 **استثنای یک‌باره‌ی لحظه‌ی لانچ (v3.25.0).** وقتی UX v2 برای همه باز شد، هر
    // کاربرِ فعلی هنوز کیبوردِ **تومانیِ** قدیمی را روی گوشی‌اش دارد و تلگرام آن را تا
    // اولین جایگزینی نگه می‌دارد. برچسب‌های قدیمی همه هنوز کار می‌کنند (`DAILY_LABELS`,
    // `WALLET_LABELS`, `INVITE_LABELS`, و `reading` که در هر دو دنیا یک برچسب است)، پس
    // هیچ دکمه‌ای نمی‌میرد — ولی **«کارت شانس» اصلاً در آن کیبورد نیست**، یعنی
    // مهم‌ترین فیچرِ این آپدیت از منوی پایین در دسترسشان نیست. و چون دو نقطه‌ی
    // قرارداد (بازگشت به منو، و تشکرِ بعد از نمره‌ی فال) ممکن است هفته‌ها بعد برسند،
    // بدونِ این پنجره کاربر مدت‌ها منوی نسل قبل را می‌دید.
    // قراردادِ دو-نقطه‌ای برای حالتِ **پایدار** درست است؛ لحظه‌ی مهاجرت حالتِ پایدار نیست.
    // این پنجره **دقیقاً یک بار per کاربر** باز می‌شود و فقط برای کسی که قبل از لانچ
    // ساخته شده؛ کاربرِ جدید مسیرِ طراحی‌شده‌ی خودش را می‌رود.
    if (uxV2For(uid)) {
      const u2 = getUser(uid);
      if (!u2?.welcomed || ONBOARDING_STATES.includes(getState(uid))) return;
      if ((u2.created_at || 0) >= KB_V2_EPOCH) return;    // بعد از لانچ آمده
      if ((u2.kb_shown_at || 0) >= KB_V2_EPOCH) return;   // کیبوردِ نسل جدید را گرفته
      stmts.setKbShown.run(uid);
      await ctx.reply(L.onboarding.keyboardReveal, mainKeyboard(uid)).catch(() => {});
      return;
    }
    const u = getUser(uid);
    if (!u?.welcomed || ONBOARDING_STATES.includes(getState(uid))) return;
    const shown = u.kb_shown_at || 0;
    if (Date.now() / 1000 - shown < KB_REFRESH_DAYS * 86400) return;
    stmts.setKbShown.run(uid);
    await ctx.reply(L.onboarding.keyboardReveal, mainKeyboard(uid)).catch(() => {});
  } catch (e) { logErr('ensureMenu:', e.message); }
}
// پیامِ «جوابِ قاطع» برای فال‌های تصمیم‌محور. کاملاً fail-safe: هر مشکلی پیش بیاید
// (پرچم خاموش، فالِ غیرتصمیمی، جوابِ مبهمِ مدل، خطای تلگرام) خوانش بدونِ این بخش و
// دقیقاً مثلِ قبل ادامه می‌دهد. متنِ داینامیک از LLM می‌آید → esc() + HTML.
async function sendVerdict(ctx, llm, spread) {
  try {
    if (!DECISIVE_VERDICT_ENABLED) return;
    const toneV2 = toneV2For(ctx.from.id);
    const mode = decisiveMode(spread, toneV2);
    if (!mode) return;
    const v = normalizeVerdict(llm?.verdict, mode, { choiceLabels: spread?.choiceLabels });
    if (!v) return;
    await sleep(PACE_M);
    await typing(ctx, PACE_S);
    const body = L.reading.verdictBody({
      answer: esc(v.answer),
      sign: esc(v.sign),
      because: v.because ? esc(v.because) : '',
      nuance: v.nuance ? esc(v.nuance) : '',
    }, toneV2);
    await ctx.reply(`${L.reading.verdictHeader(toneV2)}\n\n${body}`, { parse_mode: 'HTML' });
  } catch (e) { logErr('verdict:', e.message); }
}

async function finishReading(ctx, uid, readingId) {
  const r = stmts.getReading.get(readingId);
  if (!r || r.status !== 'started') return;
  const llm = JSON.parse(r.llm_json);
  const cards = JSON.parse(r.cards_json);

  if (v4For(uid)) {
    // ── متنِ نهایی v4: جواب اول، بعد دلیل ──────────────────────────────────
    // ساختِ متن در `renderV4` (reading-core.js) است تا آزمایشگاهِ آفلاین دقیقاً همان
    // چیزی را بسازد که کاربر می‌بیند. این‌جا فقط ریتمِ ارسال است: سه پیامِ جدا با مکث.
    // بدونِ parse_mode: خروجیِ v4 عمداً هیچ قالب‌بندی‌ای ندارد (نه بولد، نه تیتر)، و
    // متنِ خام یعنی تلگرام هیچ نشانه‌گذاری‌ای را تفسیر نمی‌کند — پس نه escape لازم است
    // نه ریسکِ خرابیِ قالب. (replyLong هم extra را فقط به تکه‌ی آخر می‌دهد.)
    const { headline, body, closing } = renderV4(llm, cards, L.prompts.cardLabels(cards.length),
    { name: uxV2For(r.user_id) ? dispName(getUser(r.user_id)) : '' });
    await typing(ctx, PACE_M);
    if (headline) await ctx.reply(headline);
    if (body) { await sleep(PACE_M); await replyLong(ctx, body); }
    if (closing) { await sleep(PACE_M); await replyLong(ctx, closing); }
  } else {
    // روایت پیوندی
    await typing(ctx, PACE_M);
    await replyLong(ctx, `🧵 ${llm.narrative}`);

    // جوابِ قاطعِ فال‌های تصمیم‌محور — بعد از روایت (روایت پرونده را می‌سازد، این حکم را
    // می‌دهد) و قبل از قدم‌های عملی. پیامِ جدا تا گم نشود؛ همان چیزی که کاربر گفت کم بود.
    await sendVerdict(ctx, llm, SPREAD_BY_ID[r.type]);
  }

  // «سه قدم عملی» در لحنِ جدید حذف شد (تصمیمِ مالک): تاروت‌خوانِ واقعی لیستِ کار نمی‌دهد،
  // و این بخش خوانش را به لحنِ کوچینگ می‌برد — دقیقاً همان چیزی که قرار بود از آن دور شویم.
  // در لحنِ قدیم (کاربرِ زنده) دست‌نخورده می‌ماند.
  if (!toneV2For(uid)) {
    await sleep(PACE_M);
    const items = (llm.action_items || []).slice(0, 3).map((a, i) => `${fmt(i + 1)}. ${a}`).join('\n');
    await ctx.reply(`${L.reading.actionHeader}\n\n${items}`);
  }
  // شعارِ پایانی («کارت‌ها آینه‌ان، نه قفس») فقط در لحنِ قدیم می‌ماند. در لحنِ جدید حذف است:
  // یک شعارِ توانمندسازِ عمومی، آخرین چیزی که کاربر می‌خواند، کلِ قاطعیتِ خوانش را آب می‌کند
  // (STYLE.md بند ۵ — بازخوردِ صریحِ مالک درباره‌ی لوس‌کردنِ کاربر).
  if (!toneV2For(uid)) {
    await sleep(PACE_M);
    await ctx.reply(L.reading.empowerClose);
  }

  stmts.setReadingStatus.run('delivered', readingId);
  track(db, uid, EVENTS.PRODUCT_DELIVERED, { type: r.type, price: r.price, reading_id: readingId });
  trackOnce(db, uid, EVENTS.FIRST_VALUE, { via: 'reading' });
  // حافظه‌ی انباشتی: مدل در همان فراخوانی اصلی نسخه‌ی به‌روز حافظه را برگردانده (هزینه‌ی اضافه: صفر)
  if (typeof llm.memory === 'string' && llm.memory.trim()) {
    stmts.setMemory.run(llm.memory.trim().slice(0, 1200), uid);
  }
  setState(uid, 'idle');
  setSession(uid, null);

  // پاداش رفرال: فقط بعد از اولین فال کاملِ دعوت‌شده (نه لحظه‌ی ورود).
  // ⚠️ پاداش **فقط به دعوت‌کننده** می‌رسد (تصمیمِ صریحِ مالک ۱۴۰۵/۰۵/۲۹). دعوت‌شده از
  // بابتِ دعوت‌شدن هیچ چیزی نمی‌گیرد؛ هدیه‌ی خوش‌آمدِ او همان لحظه‌ی /start واریز شده و
  // کاملاً مستقل است (کاربرِ ارگانیک هم دقیقاً همان را می‌گیرد). نسخه‌ی قبلی به هر دو طرف
  // واریز می‌کرد و متن‌ها هم همین را وعده می‌دادند؛ هر دو با هم اصلاح شدند.
  try {
    const ref = stmts.getReferralByReferee.get(uid);
    if (ref && !ref.rewarded && stmts.countDelivered.get(uid).c === 1) {
      stmts.setReferralRewarded.run(ref.id);
      // پاداش طبق اقتصادِ **دعوت‌کننده** حساب می‌شود، چون تنها اوست که چیزی می‌گیرد.
      const refAmt = referralBonusFor(ref.referrer_id);
      stmts.credit.run(refAmt, ref.referrer_id);
      track(db, ref.referrer_id, 'credit_granted', { amount: refAmt, kind: 'referral' });
      const referee = getUser(uid);
      await bot.telegram.sendMessage(ref.referrer_id, L.share.referralReward(dispName(referee), refAmt, curOf(ref.referrer_id))).catch(() => {});
    }
  } catch (e) { logErr('referral reward:', e.message); }

  // یادگاری: مدیاگروپ کارت‌ها (file_id کش‌شده) با خلاصه
  await typing(ctx, PACE_M, 'upload_photo');
  try {
    const media = cards.map((c, i) => ({
      type: 'photo',
      media: stmts.getCardFile.get(c.key)?.file_id || { source: `./assets/cards/${CARD_BY_KEY[c.key].file}` },
      ...(i === 0 ? { caption: L.reading.deliverableCaption(llm.summary || '') } : {}),
    }));
    await ctx.replyWithMediaGroup(media);
  } catch (e) { logErr('media group:', e.message); }

  // milestone ۱۴روزه بی‌صدا ذخیره می‌شود (فقط برای قلاب /start و پوش چک‌این) —
  // پیام «بعداً برگرد» ضد ریتنشن فوری است؛ به‌جایش پیشنهاد شخصی‌سازی‌شده‌ی فال بعدی:
  await sleep(PACE_M);
  const days = Math.min(Math.max(parseInt(llm.next_milestone?.days, 10) || MILESTONE_DAYS, 7), 90);
  stmts.setMilestone.run(Math.floor(Date.now() / 1000) + days * 86400, uid);
  if (!BOT_USERNAME) { try { BOT_USERNAME = (await bot.telegram.getMe()).username; } catch {} }
  // اولین فالِ کاملِ این کاربر (شمارش بعد از setReadingStatus بالا، پس همین فال را هم
  // می‌شمارد — همان قراردادی که پاداشِ رفرال بالاتر استفاده کرد).
  const isFirstReading = stmts.countDelivered.get(uid).c === 1;
  // UX v2.1 (تصمیمِ صریحِ مالک): برای **اولین** فالِ کاربر، پیشنهادِ فالِ جدید این‌جا
  // نمی‌آید؛ به‌جایش بعد از نمره‌دادن به همین فال، تبلیغِ کارتِ شانس می‌آید (پایین‌تر در
  // `fbr:`) و دعوت به فالِ بعدی به بعد از کشیدنِ آن کارت موکول می‌شود. برای فال‌های
  // بعدی و برای دنیای قدیم، رفتار دقیقاً همان قبلی است.
  // 🐛 باگِ ترتیب (گزارشِ مالک): تا امروز پیامِ «ادامه» **قبل از** نظرسنجی می‌آمد و گاهی
  // کاربر CTA را زودتر از سؤالِ نمره می‌دید. قرارداد این است: اول نمره، بعد تشکر، بعد
  // قدمِ بعدی. پس وقتی نظرسنجی پرسیده می‌شود (v4)، پیامِ «ادامه» به `fbr:` موکول می‌شود.
  // در دنیای بدونِ نظرسنجی رفتار دقیقاً همان قبلی می‌ماند.
  if (!v4For(uid)) {
    // CTA بعد از فالِ **پولی** (UX v2.1 — متنِ خودِ مالک). عمداً با متنِ بعد از کارتِ روز
    // فرق دارد: این‌جا کاربر یک جوابِ کامل گرفته، آن‌جا فقط یک تکه.
    const nextText = uxV2For(uid) ? L.reading.nextOffersV3
      : OPEN_TOPIC_ENABLED ? L.reading.nextOffersOpen : L.reading.nextOffers;
    await ctx.reply(nextText, Markup.inlineKeyboard([
      ...recoRows(uid, r.type),
      [Markup.button.url(L.buttons.share(referralBonusFor(uid), curOf(uid)), shareUrlFor(uid))],
    ]));
    await ensureMenu(ctx, uid);
  }

  // v4: بازخورد در **آخرِ آخر**، بعد از تمام‌شدنِ کامل خوانش. مقیاسِ ۱ تا ۵ و سؤال درباره‌ی
  // **رضایت** است نه انطباق با واقعیت: چیزی که می‌خواهیم بدانیم این است که کاربر راضی
  // بیرون رفت یا نه، چون همان است که تعیین می‌کند برمی‌گردد یا نه.
  // بدونِ state: دکمه‌ها readingId را حمل می‌کنند، پس فلوی بعدیِ کاربر بلاک نمی‌شود.
  if (v4For(uid)) {
    await sleep(PACE_M);
    await ctx.reply(L.reading.rateAsk, Markup.inlineKeyboard([
      [1, 2, 3, 4, 5].map((n) => Markup.button.callback(L.buttons.rate(n), `fbr:${n}:${readingId}`)),
    ]));
  }
}

// بازخوردِ ۱ تا ۵ (v4). گاردها: مالکیتِ رکورد، و ثبتِ یک‌باره تا دوبار-تپ دو رویداد نسازد.
bot.action(/^fbr:([1-5]):(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery('🙏').catch(() => {});
  const score = parseInt(ctx.match[1], 10);
  const readingId = parseInt(ctx.match[2], 10);
  const r = stmts.getReading.get(readingId);
  if (!r || r.user_id !== uid) return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  if (r.feedback) return; // قبلاً ثبت شده
  // مقدار با پیشوندِ `rate:` ذخیره می‌شود تا از مقادیرِ قدیمیِ yes/some/no قابلِ تفکیک
  // بماند و تحلیلِ تاریخی نشکند (بند ۲ج/۳: فقط اضافه کن، معنیِ داده‌ی قبلی را عوض نکن).
  stmts.setReadingFeedback.run(`rate:${score}`, readingId);
  track(db, uid, EVENTS.FEEDBACK, { reading_id: readingId, score, scale: 5 });
  // UX v2.1 (تصمیمِ صریحِ مالک): درست بعد از نمره‌دادن به **اولین** فالِ کاربر، به‌جای
  // تشکرِ صرف، تبلیغِ کارتِ شانس می‌آید — این‌جا و نه هرجای دیگر، چون کاربر همین الان
  // یک تجربه‌ی کاملِ مثبت گرفته و بهترین لحظه برای معرفیِ آیینِ روزانه‌ی بعدی است.
  // اگر همان روز کارت شانسش را قبلاً کشیده (نادر، ولی ممکن)، همان تشکرِ همیشگی می‌ماند.
  const isFirstReading = stmts.countDelivered.get(uid).c === 1;
  const luckyAvailable = getUser(uid)?.lucky_date !== tehranToday();
  // تشکر **همیشه** اول می‌آید، و کیبوردِ اصلی روی همین پیام سوار می‌شود: این تنها پیامِ
  // این نقطه است که کیبوردِ inline ندارد، پس تنها چیزی است که می‌تواند حاملش باشد —
  // و دقیقاً همان لحظه‌ای است که مالک خواست منو صادر شود (هم‌زمان با قدمِ بعدی).
  if (uxV2For(uid)) stmts.setKbShown.run(uid);   // پنجره‌ی مهاجرتِ کیبورد را می‌بندد
  await ctx.reply(L.reading.rateThanks, uxV2For(uid) ? mainKeyboard(uid) : undefined).catch(() => {});
  // 🐛 باگِ گزارش‌شده: قبلاً فقط **اولین فالِ همراه با کارتِ شانسِ باز** قدمِ بعدی می‌گرفت.
  // کاربری که کارتِ شانسش را قبلاً کشیده بود (یا فالِ اولش در آنبوردینگ نبود) بعد از
  // تشکر به بن‌بست می‌خورد. حالا آن شرط فقط تعیین می‌کند **کدام** قدمِ بعدی بیاید، نه اینکه
  // قدمِ بعدی بیاید یا نه.
  if (uxV2For(uid) && isFirstReading && luckyAvailable) {
    // آشناسازی با کارتِ شانس = آخرین قدمِ آنبوردینگ. دعوت به فالِ بعدی بعد از کشیدنِ آن
    // می‌آید (پایانِ `lpick:`)، وگرنه کاربر هم‌زمان دو دعوتِ رقیب می‌گیرد.
    await ctx.reply(L.lucky.promo(dispName(getUser(uid))), Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.luckyDraw(LUCKY_PICKS, curOf(uid)), 'lucky_go')],
    ])).catch(() => {});
    return;
  }
  if (uxV2For(uid)) await sendContinuePrompt(ctx, uid);
});

/* ---------- کیف پول و شارژ (کارت‌به‌کارت + تأیید ادمین) ---------- */
// سه راهِ پرکردنِ کیف، به‌ترتیبِ هزینه برای کاربر: خرید، معرفی، و کارت شانسِ رایگان.
// دکمه‌ی کارت شانس فقط وقتی می‌آید که سهمیه‌ی امروز مصرف نشده باشد — دکمه‌ای که به
// «امروز استفاده کردی» ختم شود یک بن‌بستِ کوچک است (بند ۹ب ریشه).
function walletRows(uid) {
  const rows = [[rechargeBtn(uid)]];
  if (!uxV2For(uid)) return rows;
  const cur = curOf(uid);
  rows.push([Markup.button.callback(L.buttons.inviteWithBonus(referralBonusFor(uid), cur), 'invite_go')]);
  if (getUser(uid)?.lucky_date !== tehranToday()) {
    rows.push([Markup.button.callback(L.buttons.luckyDraw(LUCKY_PICKS, cur), 'lucky_go')]);
  }
  return rows;
}

// تک‌منبعِ «متن + دکمه‌ها»ی صفحه‌ی کیف، تا هم showWallet و هم دکمه‌ی بازگشتِ صفحه‌ی بسته‌ها
// دقیقاً یک چیز را رندر کنند (همان الگوی falMenuScreen/allTopicsScreen).
const walletScreen = (uid) => [L.wallet.info(getBalance(uid), curOf(uid)), {
  parse_mode: 'Markdown',
  ...Markup.inlineKeyboard(walletRows(uid)),
}];

async function showWallet(ctx) {
  upsertUser(ctx);
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx, INTENT.WALLET)) return;
  if (await blockDuringOpenReading(ctx, INTENT.WALLET)) return;
  if (await blockDuringOpenLucky(ctx, INTENT.WALLET)) return;
  const [text, extra] = walletScreen(ctx.from.id);
  await ctx.reply(text, extra);
}
bot.hears(L.buttons.wallet, showWallet);
// همان قاعده: «💎 کیف الماس» (و «💎 الماس فروشی»ِ نسلِ قبل) هنوز match می‌شوند.
const WALLET_LABELS = [L.buttons.coinShop, '💎 کیف الماس', '💎 الماس فروشی'];
bot.hears(WALLET_LABELS, showWallet);   // UX v2: همان صفحه، نامِ تازه

// لینک اشتراک‌گذاری استاندارد تلگرام: با یک تاچ، پیام آماده + لینک دعوت در چت انتخابی گذاشته می‌شود.
// (switch_inline_query حذف شد: اگر کاربر روی نتیجه‌ی اینلاین تپ نمی‌کرد فقط @botname ارسال می‌شد)
function shareUrlFor(uid) {
  const link = `https://t.me/${BOT_USERNAME}?start=ref_${uid}`;
  return `https://t.me/share/url?url=${encodeURIComponent(link)}&text=${encodeURIComponent(L.share.shareText())}`;
}

// دعوت دوستان: لینک اختصاصی قابل کپی + دکمه‌ی ارسال مستقیم به دوستان. یک تابع، دو ورودی
// (کیبورد اصلی + دکمه‌ی اینلاینِ «معرفی دوستان» زیرِ صفحه‌ی کیف الماس) تا رفتار یکی بماند.
async function showInvite(ctx) {
  const uid = ctx.from.id;
  upsertUser(ctx);
  if (await blockDuringOnboarding(ctx)) return;
  if (await blockDuringOpenPay(ctx, INTENT.INVITE)) return;
  if (await blockDuringOpenReading(ctx, INTENT.INVITE)) return;
  if (await blockDuringOpenLucky(ctx, INTENT.INVITE)) return;
  if (!BOT_USERNAME) { try { BOT_USERNAME = (await bot.telegram.getMe()).username; } catch {} }
  await ctx.reply(L.share.invitePrompt(BOT_USERNAME, uid, referralBonusFor(uid), curOf(uid)), {
    parse_mode: 'Markdown',
    reply_markup: Markup.inlineKeyboard([[Markup.button.url(L.buttons.share(referralBonusFor(uid), curOf(uid)), shareUrlFor(uid))]]).reply_markup,
  });
}
// برچسبِ این دکمه در v3.9.2 به «معرفی دوستان» رفت و در v2.3 به «دعوت دوستان» برگشت. کیبوردِ
// reply روی گوشیِ کاربر تا اولین جایگزینی می‌ماند، پس کاربری که کیبوردش هنوز برچسبِ میانی را
// دارد با یک تپ متنی می‌فرستد که دیگر هیچ hears ای نمی‌گیردش (بند ۲ج/۶: دکمه‌ی کهنه نباید
// بمیرد). همان الگوی دکمه‌ی ریست: هر دو برچسب match می‌شوند.
const INVITE_LABELS = [L.buttons.inviteMain, '📤 معرفی دوستان'];
bot.hears(INVITE_LABELS, showInvite);
bot.action('invite_go', async (ctx) => { await ctx.answerCbQuery().catch(() => {}); return showInvite(ctx); });

// «تخفیف می‌خوام» — شاخه‌ی اختیاریِ کنارِ مسیر اصلی؛ استیت را دست نمی‌زند تا فالِ رزروشده
// و پرداختِ در جریان سالم بمانند. اولین شارژ → کدِ شخصیِ ۵۰٪ (دستی وارد می‌شود، هرگز خودکار)؛
// بعد از آن → مسیر دعوت دوستان. هر دو پیام دکمه‌ی «افزایش موجودی» دارند تا برگشت به مسیر اصلی یک تاچ باشد.
// «پرداختِ هزینه‌ی همین فال» — مستقیم فاکتور، بدونِ مرحله‌ی انتخابِ مبلغ
bot.action(/^payr:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  if (await blockDuringOpenPay(ctx)) return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await invoiceForReading(ctx, uid, parseInt(ctx.match[1], 10), false);
});

// «تخفیف می‌خوام» — دقیقاً مثل payr، فقط با یک پیامِ اطلاع‌رسانیِ کوتاه قبل از فاکتور.
// هیچ کدی کپی نمی‌شود و هیچ دکمه‌ی میانی‌ای وسط راه نیست؛ کاربری که تخفیف می‌خواهد یعنی
// می‌خواهد کمتر بپردازد، پس یک قدم بعد باید فاکتورش جلویش باشد.
bot.action(/^wdisc:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  if (await blockDuringOpenPay(ctx)) return;
  const avail = firstDiscountAvailable(uid);
  track(db, uid, 'discount_requested', { first: !hasRecharged(uid), avail });
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await invoiceForReading(ctx, uid, parseInt(ctx.match[1], 10), true);
});

// دکمه‌ی کهنه‌ی داخلِ چتِ کاربران (قرارداد «callbackهای قدیمی نمی‌میرند»): دیگر کد نمی‌دهد،
// چون تخفیف حالا فقط روی فالِ رزروشده و از مسیرِ wdisc اعمال می‌شود.
bot.action('want_discount', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  if (await offerPendingReading(ctx, uid)) return;
  return ctx.reply(L.wallet.discountHeld, Markup.inlineKeyboard([
    [rechargeBtn(uid)],
  ]));
});

bot.action('recharge', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  upsertUser(ctx);
  const paymentId = Number(stmts.insertPayment.run(uid).lastInsertRowid);
  track(db, uid, EVENTS.RECHARGE_STARTED, { payment_id: paymentId });
  setState(uid, 'pay_amount');
  patchSession(uid, { paymentId });
  // اقتصادِ سکه: هیچ عددی وارد نمی‌شود و هیچ مرحله‌ی میانی نیست — سه بسته، و تپِ بعدی فاکتور است.
  if (coinsOn(uid)) {
    const cur = curOf(uid);
    // UX v2.3: صفحه‌ی بسته‌ها **روی همان پیامِ کیف** ادیت می‌شود (زیرمنو، نه پیامِ تازه) و
    // دکمه‌ی پایینش «بازگشت» است نه «انصراف» — چون این خروج از یک فلوی اصلی نیست و نباید
    // پیامِ «ادامه» بیاورد. اگر ادیت نشد (ورودِ غیرِ دکمه‌ای یا پیامِ کهنه) پیامِ جدید می‌رود.
    const text = L.wallet.coinPacks(cur);
    const extra = Markup.inlineKeyboard([
      ...COIN_PACKAGES.map(p => [styled(Markup.button.callback(L.buttons.coinPack(p, cur), `pkg:${p.key}`), PACK_STYLE[p.key])]),
      [Markup.button.callback(L.buttons.backOneStep, `pay_back:${paymentId}`)],
    ]);
    try { return await ctx.editMessageText(text, extra); } catch {}
    return ctx.reply(text, extra);
  }
  // مبلغِ پیشنهادیِ «دقیقاً کسریِ فال» حذف شد (v2.0.0): آن کار را حالا دکمه‌ی «پرداختِ هزینه‌ی
  // همین فال» بهتر انجام می‌دهد. این‌جا فقط نردبانِ قیمتِ کیف‌پول است.
  const amounts = QUICK_AMOUNTS;
  await ctx.reply(L.wallet.askAmount(), Markup.inlineKeyboard([
    ...amounts.map(a => [Markup.button.callback(L.buttons.rechargeAmount(a, bonusFor(a)), `ramt:${a}`)]),
    [Markup.button.callback(L.buttons.customAmount, 'rcustom')],
    [Markup.button.callback(L.buttons.cancel, `pay_cancel:${paymentId}`)],
  ]));
});

async function setRechargeAmount(ctx, uid, amount) {
  const s = getSession(uid);
  if (!s.paymentId) return ctx.reply(L.errors.stateLost, mainKeyboard(ctx.from.id));
  // حداقلِ مبلغ: کاربری «۸» نوشت و سیستم جدی گرفت، کدِ تخفیفِ ۱۰۰٬۰۰۰ رویش خرج شد و
  // ۸ تومان اعتبار داد (۱۴۰۵/۰۵/۰۹). عددی که آشکارا اشتباهِ تایپی است نباید فاکتور بسازد.
  if (amount < MIN_RECHARGE) return ctx.reply(L.wallet.amountTooLow(MIN_RECHARGE));
  // ادعای اتمیک قبل از هر await؛ اگر تپِ دیگری قبلاً مبلغ را ست کرده (changes=0) بی‌صدا برگرد
  if (stmts.claimAmount.run(amount, s.paymentId).changes === 0) return;

  // هیچ تخفیفی خودکار اعمال نمی‌شود: کاربر یا کدش را از دکمه‌ی «تخفیف می‌خوام» گرفته و
  // این‌جا با «🎟️ کد تخفیف دارم» واردش می‌کند، یا مبلغ کامل را می‌پردازد.
  const payAmount = amount;

  setState(uid, 'pay_receipt');
  await ctx.reply(L.wallet.invoice(payAmount, CARD_NUMBER, CARD_OWNER), {
    parse_mode: 'Markdown',
    reply_markup: Markup.inlineKeyboard([
      cardCopyRow(),
      [Markup.button.callback(L.buttons.discountHave, `disc:${s.paymentId}`)],
      [Markup.button.callback(L.buttons.cancel, `pay_cancel:${s.paymentId}`)],
    ]).reply_markup,
  });
}

// خریدِ بسته‌ی الماس: مبلغِ پرداخت = قیمتِ بسته (تومانِ واقعی)، اعتباری که بعد از تأیید داده
// می‌شود = ارزشِ الماس‌های بسته. دقیقاً همان ریاضیِ جاافتاده‌ی تخفیف (`original_amount` اعتبار
// می‌گیرد، `amount` پرداخت می‌شود)، پس هیچ منطقِ پولِ جدیدی ساخته نشد.
// ستونِ `pkg` دو کارِ حیاتی می‌کند: (۱) هدیه‌ی شارژِ ۲۰۰k به بسته نمی‌چسبد (وگرنه بسته‌ی
// جادویی با اعتبارِ یک‌میلیونی، ۵۰k هدیه‌ی بی‌دلیل هم می‌گرفت)، (۲) اصلاحِ خودکارِ
// «پرداختِ کمتر» روی بسته اجرا نمی‌شود چون وعده‌ی بسته را می‌شکند → تصمیمِ انسانی.
bot.action(/^pkg:([a-z]+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (!coinsOn(uid)) return;
  if (getState(uid) !== 'pay_amount') return;
  const pack = PACKAGE_BY_KEY[ctx.match[1]];
  if (!pack) return;
  const s = getSession(uid);
  if (!s.paymentId) return ctx.reply(L.errors.stateLost, mainKeyboard(uid));
  // ادعای اتمیک قبل از هر await (ضدِ دوبار-تپ روی دو بسته‌ی متفاوت)
  if (stmts.claimAmount.run(pack.coins * COIN_VALUE, s.paymentId).changes === 0) return;
  stmts.setPaymentPackage.run(pack.key, pack.toman, s.paymentId);
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  setState(uid, 'pay_receipt');
  await ctx.reply(L.wallet.coinPackChosen(pack, curOf(uid)), { parse_mode: 'Markdown' });
  await ctx.reply(L.wallet.invoice(pack.toman, CARD_NUMBER, CARD_OWNER), {
    parse_mode: 'Markdown',
    reply_markup: Markup.inlineKeyboard([
      cardCopyRow(),
      [Markup.button.callback(L.buttons.cancel, `pay_cancel:${s.paymentId}`)],
    ]).reply_markup,
  });
});

bot.action(/^ramt:(\d+)$/, async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (getState(ctx.from.id) !== 'pay_amount') return;
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await setRechargeAmount(ctx, ctx.from.id, parseInt(ctx.match[1], 10));
});
bot.action('rcustom', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  if (getState(ctx.from.id) !== 'pay_amount') return;
  await ctx.reply(L.wallet.askAmount());
});
bot.action(/^disc:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (getState(uid) !== 'pay_receipt') return;
  setState(uid, 'pay_discount');
  // بازگشت به فاکتور (نه منو) چون کاربر هنوز وسط پرداخت است — پول یتیم نمی‌شود
  await ctx.reply(L.wallet.askDiscount, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.backToInvoice, `disc_back:${ctx.match[1]}`)],
  ]));
});
// انصراف از واردکردن کد تخفیف → برگشت به مرحله‌ی رسید (فاکتور همان‌طور باز می‌ماند)
bot.action(/^disc_back:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  if (getState(uid) !== 'pay_discount') return;
  setState(uid, 'pay_receipt');
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.wallet.discountSkipped, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.cancel, `pay_cancel:${ctx.match[1]}`)],
  ]));
});
bot.action(/^pay_cancel:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const pid = parseInt(ctx.match[1], 10);
  const p = stmts.getPayment.get(pid);
  if (p && p.user_id === uid && ['pending'].includes(p.status)) stmts.setPaymentStatus.run('canceled', p.id);
  // همان قاعده‌ی pay_back (باگِ از قبل موجود): تپِ یک دکمه‌ی انصرافِ کهنه نباید فاکتورِ
  // زنده‌ی فعلی را از سشن جدا کند. در مسیرِ عادی (p.id === s.paymentId) رفتار عوض نمی‌شود.
  const s = getSession(uid);
  if (s.paymentId === pid) {
    delete s.paymentId;
    setSession(uid, s);
    setState(uid, s.readingId ? 'confirm_pay' : 'idle');
  }
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await replyCanceled(ctx, uid);
  // اگر فال رزروشده‌ای منتظر است، دکمه‌هایش را دوباره جلوی کاربر بگذار تا سرگردان نماند
  await offerPendingReading(ctx, uid);
});

// ◀️ بازگشتِ یک‌قدمی از صفحه‌ی بسته‌ها به خودِ کیف. دقیقاً همان پاک‌سازیِ pay_cancel را
// می‌کند (فاکتورِ خالی نباید باز بماند وگرنه blockDuringOpenPay کاربر را قفل می‌کند)، ولی
// **پیامِ «ادامه» را نمی‌فرستد**: این خروج از فلو نیست، فقط یک قدم عقب در همان زیرمنوست.
bot.action(/^pay_back:(\d+)$/, async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  const pid = parseInt(ctx.match[1], 10);
  const p = stmts.getPayment.get(pid);
  if (p && p.user_id === uid && p.status === 'pending') stmts.setPaymentStatus.run('canceled', p.id);
  // ⚠️ استیت/سشن فقط وقتی دست بخورد که این دکمه به **همان** فاکتوری اشاره کند که کاربر
  // الان درگیرش است. دکمه‌ی کهنه‌ی یک فاکتورِ رهاشده نباید فاکتورِ زنده‌ی فعلی را از سشن
  // جدا کند، وگرنه رسیدی که کاربر بعداً می‌فرستد بی‌صاحب می‌شود و پولِ واریزشده گم می‌ماند.
  const s = getSession(uid);
  if (s.paymentId === pid) {
    delete s.paymentId;
    setSession(uid, s);
    setState(uid, s.readingId ? 'confirm_pay' : 'idle');
  }
  const [text, extra] = walletScreen(uid);
  try { await ctx.editMessageText(text, extra); }
  catch { await ctx.reply(text, extra).catch(() => {}); }
  // فالِ رزروشده نباید سرگردان بماند (همان کاری که pay_cancel می‌کند).
  await offerPendingReading(ctx, uid);
});

// reason: 'unknown' (نبود/منقضی/مالِ کسِ دیگر) یا 'used' (قبلاً خرج شده یا روی فاکتورِ
// در انتظارِ تأیید است) — پیامِ کاربر بر همین اساس فرق می‌کند تا سردرگم نشود.
function validateDiscount(code, userId, amount, currentPaymentId = 0) {
  const dc = stmts.getDiscountCode.get(normalizeDigits(code).trim().toUpperCase());
  if (!dc) return { ok: false, reason: 'unknown' };
  if (dc.expires_at && dc.expires_at < Date.now() / 1000) return { ok: false, reason: 'unknown' };
  if (dc.only_user_id && dc.only_user_id !== userId) return { ok: false, reason: 'unknown' };
  // کدِ «اولین شارژ» فقط تا قبل از اولین شارژِ تأییدشده معتبر است (وگرنه کاربری که بارِ اول
  // بدون کد پرداخت کرده بود، می‌توانست همان کد را روی شارژِ دومش خرج کند).
  if (dc.code === firstCodeFor(userId) && hasRecharged(userId)) return { ok: false, reason: 'used' };
  const uses = stmts.getUserDiscountUses.get(dc.id, userId).c
    + stmts.countPendingDiscount.get(dc.id, userId, currentPaymentId).c;
  if (uses >= dc.max_uses_per_user) return { ok: false, reason: 'used' };
  let disc = Math.round(amount * dc.discount_percent / 100);
  if (dc.max_discount_amount != null && disc > dc.max_discount_amount) disc = dc.max_discount_amount;
  return { ok: true, dc, finalAmount: Math.max(0, amount - disc) };
}

// آیا این متن دقیقاً یک کدِ تخفیفِ فعالِ موجود در DB است؟ (تک‌کلمه و کوتاه — رسیدِ واقعی
// هیچ‌وقت این شکل نیست). گاردِ «کد را جای اشتباه فرستادم».
function looksLikeDiscountCode(text) {
  const t = normalizeDigits(String(text ?? '')).trim().toUpperCase();
  if (!t || t.length > 32 || /\s/.test(t)) return false;
  try { return !!stmts.getDiscountCode.get(t); } catch { return false; }
}

async function applyDiscount(ctx, uid, codeText) {
  const s = getSession(uid);
  const p = s.paymentId && stmts.getPayment.get(s.paymentId);
  if (!p) { setState(uid, 'idle'); return ctx.reply(L.errors.stateLost, mainKeyboard(ctx.from.id)); }
  const v = validateDiscount(codeText, uid, p.original_amount || p.amount, p.id);
  if (!v.ok) {
    // کدِ اشتباه کاربر را از مرحله‌ی کد بیرون نمی‌اندازد. قبلاً state به pay_receipt برمی‌گشت و
    // تلاشِ دومِ کاربر به‌عنوان «رسیدِ متنی» بلعیده می‌شد → پرداختی که هرگز انجام نشده بود به
    // ادمین می‌رفت و ساعت‌ها بعد «تأیید نشد» می‌گرفت (اتفاقِ واقعیِ ۱۴۰۵/۰۵/۰۹).
    return ctx.reply(v.reason === 'used' ? L.wallet.usedDiscount : L.wallet.badDiscount, Markup.inlineKeyboard([
      [Markup.button.callback(L.buttons.backToInvoice, `disc_back:${p.id}`)],
    ]));
  }
  stmts.setPaymentDiscount.run(v.dc.id, v.finalAmount, p.id);
  setState(uid, 'pay_receipt');
  await ctx.reply(L.wallet.invoiceDiscounted(p.original_amount || p.amount, v.finalAmount, v.dc.code), { parse_mode: 'Markdown' });
  if (v.finalAmount === 0) {
    // کد ۱۰۰٪ → تأیید خودکار بدون رسید
    await approvePayment(p.id, null);
    await ctx.reply(L.wallet.freeApproved);
    await afterApproval(uid);
  } else {
    await ctx.reply(L.wallet.invoice(v.finalAmount, CARD_NUMBER, CARD_OWNER), {
      parse_mode: 'Markdown',
      reply_markup: Markup.inlineKeyboard([cardCopyRow()]).reply_markup,
    });
  }
}

// note: هشدارِ اختیاری بالای رسید (مثلاً «مبلغ ممکن است ریال باشد») تا ادمین کورکورانه
// تأیید نکند. بدونِ آن، بازبینیِ انسانی همان خطای مدل را تکرار می‌کند.
async function sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody, note = '') {
  const user = getUser(uid);
  const p = stmts.getPayment.get(paymentId);
  const caption = (note ? `${note}\n\n` : '')
    + L.wallet.adminNotify(p, user) + (textBody ? `\n\n📋 ${textBody.slice(0, 500)}` : '');
  const kb = Markup.inlineKeyboard([[
    Markup.button.callback(L.buttons.approve(paymentId), `approve:${paymentId}`),
    Markup.button.callback(L.buttons.reject(paymentId), `reject:${paymentId}`),
  ]]).reply_markup;
  let adminMsg;
  for (const adminId of ADMIN_IDS) {
    try {
      const sent = photoFileId
        ? await ctx.telegram.sendPhoto(adminId, photoFileId, { caption, reply_markup: kb })
        : await ctx.telegram.sendMessage(adminId, caption, { reply_markup: kb });
      if (!adminMsg) adminMsg = sent;
    } catch {}
  }
  stmts.setPaymentReceipt.run(photoFileId || null, adminMsg?.message_id || null, 'waiting_review', paymentId);
}

// ورودیِ همه‌ی رسیدها (عکس/متن): داوریِ ایجنتِ کارت‌به‌کارت، سپس مسیر:
//   approve  → اعتبار + پیام به کاربر + اطلاع به ادمین با دکمه‌ی «پیامکش نیومده» (شبکه‌ی ایمنی)
//   reject   → رد + پیام با دلیل (مگر «اصلاً رسید نیست» که فقط راهنمایی و پرداخت باز می‌ماند)
//   review   → کلِ رسید با دکمه‌های تأیید/رد به ادمین (تصمیمِ انسانی)
// auto-approve خاموش (کلید سراسری) یا کاربرِ بی‌اعتماد → همیشه review (بدونِ خرجِ ایجنت).
async function processReceipt(ctx, uid, paymentId, photoFileId, textBody, recovered) {
  const p = stmts.getPayment.get(paymentId);
  if (!p) { setState(uid, 'idle'); return ctx.reply(L.errors.stateLost, mainKeyboard(ctx.from.id)); }
  const s = getSession(uid);
  const nextState = s?.readingId ? 'confirm_pay' : 'idle';
  track(db, uid, EVENTS.RECEIPT_SUBMITTED, { payment_id: paymentId, amount: p.amount });
  // رسیدِ خام را همان اول ذخیره کن (برای بازبینی/برگشت) بدونِ تغییرِ وضعیت
  if (photoFileId) stmts.saveReceiptFile.run(photoFileId, paymentId);

  // پیامِ انسانی: رسید برای بررسی/تأیید فرستاده شد (هیچ اشاره‌ای به بررسیِ خودکار نیست)
  await ctx.reply(L.wallet.receiptSent).catch(() => {});

  // کلیدِ خاموشی یا کاربرِ بی‌اعتماد → مستقیم به ادمینِ واقعی (بدونِ تصمیمِ خودکار و بدونِ تأخیرِ ساختگی)
  if (!RECEIPT_AI_AUTO_APPROVE || isDistrusted(uid)) {
    await sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody);
    return setState(uid, nextState);
  }

  // دانلودِ عکس برای ایجنت (fail-safe: هر خطا → بدونِ عکس؛ ایجنت آن را به review می‌برد)
  let imageBuffer = null;
  if (photoFileId) {
    try {
      const link = await ctx.telegram.getFileLink(photoFileId);
      const res = await fetch(link.href);
      imageBuffer = Buffer.from(await res.arrayBuffer());
    } catch (e) { logErr('receipt download:', e.message); }
  }
  // مبلغِ موردِانتظارِ رسید = **همان عددی که روی فاکتور به کاربر نشان دادیم** یعنی `p.amount`
  // (بعد از تخفیف). قبلاً این‌جا `original_amount` بود و فاجعه ساخت: کاربری که ۵۰k را با
  // ۲۰٪ تخفیف ۴۰k پرداخت کرده بود، رسیدِ درستش «مبلغ کم» تشخیص داده و رد می‌شد.
  // `original_amount` فقط تعیین می‌کند بعد از تأیید چقدر **اعتبار** داده شود؛ ربطی به رسید ندارد.
  const amountToman = p.amount;
  // اگر به هر دلیلی مبلغِ فاکتور صفر/نامعتبر باشد، تصمیمِ خودکار نمی‌گیریم (تصمیمِ انسانی)
  if (!(amountToman > 0)) {
    logErr(`receipt: payment #${paymentId} مبلغِ نامعتبر (${p.amount}) → بازبینیِ انسانی`);
    await sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody);
    return setState(uid, nextState);
  }
  let decision;
  try {
    const verdict = await analyzeReceipt({
      apiKey: OPENROUTER_API_KEY, model: RECEIPT_MODEL,
      expected: { amount_toman: amountToman, recipient: CARD_RECIPIENT_NAME, dest_last4: CARD_DEST_LAST4 },
      imageBuffer, imageMime: 'image/jpeg', text: textBody,
    });
    decision = decideReceipt(verdict, amountToman); // گاردِ قطعیِ مبلغ (پرداختِ بیشتر → تأیید)
  } catch (e) {
    logErr('receipt agent:', e.message);
    decision = { action: 'review', reason_fa: '', overpaid: 0 };
  }

  // تأخیرِ انسانیِ ۳ تا ۱۰ ثانیه (حسِ «ادمین دارد اپِ بانکی را چک می‌کند») — فقط مسیرِ خودکار
  await sleep(3000 + Math.floor(Math.random() * 7000));

  const reasonFa = decision.reason_fa || 'نامشخص';
  try {
    // سیاست: فقط دو نتیجه‌ی خودکار — approve (پرداختِ کافی و واقعی) و reject (فقط مبلغِ اکیداً کمتر).
    // بقیه (not_a_receipt/بی‌کیفیت/مشکوک) → تصمیمِ انسانیِ ادمین. کاربر همیشه فقط یکی از دو
    // پیامِ نهایی را می‌گیرد: «تأیید شد» یا «تأیید نشد + پشتیبانی» (هیچ «این رسید نیست» یا دلیلی).
    if (decision.action === 'approve') {
      const done = approvePayment(paymentId);
      if (!done) return setState(uid, nextState); // ضدِ دوبار (قبلاً نهایی شده)
      await ctx.reply(approvedMsg(uid, done.creditAmount, done.bonus)).catch(() => {});
      await notifyAdminAutoApproved(stmts.getPayment.get(paymentId), getUser(uid), reasonFa, decision.overpaid, amountToman);
      return await afterApproval(uid); // فالِ رزروشده خودکار ادامه پیدا می‌کند (state را خودش می‌زند)
    }
    // پرداختِ کمتر از فاکتور: رسید واقعی است و پول رسیده، فقط کمتر. لغوِ کاملش هم به کاربر
    // ظلم است هم پولِ رسیده را از درآمد حذف می‌کند. پس فاکتور به همان مبلغِ واقعی **اصلاح**
    // می‌شود و کاربر دقیقاً همان‌قدر اعتبار می‌گیرد.
    // گاردِ صریح: اگر پای تخفیف وسط باشد، خودکار تصمیم نمی‌گیریم — چون اختلافِ مبلغ در آن
    // حالت می‌تواند باگِ تطبیق باشد نه اشتباهِ کاربر (همان فاجعه‌ی ۱۴۰۵/۰۵/۰۹). → ادمین.
    if (decision.action === 'underpaid') {
      const paid = Number(decision.paid) || 0;
      const safe = !p.discount_code_id && !p.pkg && paid >= MIN_RECHARGE && paid < amountToman;
      if (safe && stmts.adjustPaymentAmount.run(paid, paid, 'اصلاح به دلیل پرداخت کمتر', paymentId).changes) {
        track(db, uid, 'payment_adjusted',
          { payment_id: paymentId, from: amountToman, to: paid, reason: 'underpaid' });
        const done = approvePayment(paymentId);
        if (!done) return setState(uid, nextState);
        await ctx.reply(L.wallet.underpaidApproved(paid, getBalance(uid))).catch(() => {});
        await notifyAdminAuto(stmts.getPayment.get(paymentId), getUser(uid),
          `✏️ فاکتور اصلاح شد: ${amountToman} ← ${paid} (پرداختِ کمتر) و تأیید شد`, photoFileId);
        return await afterApproval(uid);
      }
      // ناامن (تخفیف داشت، یا مبلغ خیلی کم بود) → تصمیمِ انسانی
      await sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody);
      return setState(uid, nextState);
    }
    if (decision.action === 'reject') {
      rejectPaymentAI(paymentId);
      setState(uid, nextState);
      await notifyAdminAuto(p, getUser(uid), `❌ auto-reject: ${reasonFa}`, photoFileId);
      return ctx.reply(L.wallet.rejected).catch(() => {}); // پیامِ یکپارچه، بدونِ دلیل
    }
    // not_a_receipt یا review → تصمیمِ انسانیِ ادمین (پیامِ receiptSent قبلاً رفته)
    await sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody,
      L.wallet.adminAmountNote(decision.reason_code, amountToman, decision.paid));
    setState(uid, nextState);
  } catch (e) {
    // شبکه‌ی ایمنیِ نهایی: کاربر هرگز بی‌جواب نماند و پول در هوا نماند → به ادمینِ انسانی بسپار
    logErr('processReceipt terminal:', e.message);
    try { await sendReceiptToAdmin(ctx, uid, paymentId, photoFileId, textBody); } catch {}
    setState(uid, nextState);
  }
}

// اطلاع به ادمین‌ها بعد از تأییدِ خودکار + دکمه‌ی «پیامکش نیومده» (تنها راهِ برگشتِ رسیدِ فیک)
// overpaid>0 یعنی کاربر بیشتر واریز کرده → یادداشتِ اضافه برای اعتبارِ دستیِ اختلاف.
async function notifyAdminAutoApproved(p, user, reasonFa, overpaid = 0, expectedToman = 0) {
  let caption = L.wallet.adminAutoApproved(p, user, reasonFa);
  if (overpaid > 0) caption += `\n\n⚠️ ${L.wallet.overpaidNote(expectedToman || (p.original_amount || p.amount), overpaid)}`;
  const kb = Markup.inlineKeyboard([[
    Markup.button.callback(L.buttons.smsNotArrived, `cardsms:${p.id}`),
  ]]).reply_markup;
  for (const adminId of ADMIN_IDS) {
    try {
      if (p.receipt_file_id) await bot.telegram.sendPhoto(adminId, p.receipt_file_id, { caption, reply_markup: kb });
      else await bot.telegram.sendMessage(adminId, caption, { reply_markup: kb });
    } catch {}
  }
}
// یادداشتِ ساده به ادمین‌ها (بدونِ دکمه) — مثلِ اطلاعِ auto-reject. user ممکن است null باشد (گاردِ ??).
async function notifyAdminAuto(p, user, note, photoFileId) {
  const caption = `${note}\n\n${L.wallet.adminNotify(p, user || { name: '-', username: '' })}`;
  for (const adminId of ADMIN_IDS) {
    try {
      if (photoFileId) await bot.telegram.sendPhoto(adminId, photoFileId, { caption });
      else await bot.telegram.sendMessage(adminId, caption);
    } catch {}
  }
}
// ردِ خودکارِ ایجنت — از pending هم مجاز (قبل از waiting_review)؛ ضدِ دوبار با گاردِ status
function rejectPaymentAI(paymentId) {
  const p = stmts.getPayment.get(paymentId);
  if (!p || !['pending', 'waiting_review'].includes(p.status)) return null;
  stmts.setPaymentStatus.run('rejected', p.id);
  track(db, p.user_id, EVENTS.PAYMENT_REJECTED, { payment_id: p.id, amount: p.amount, via: 'ai' });
  return p;
}
// برگشتِ پرداختِ فیک: کسرِ اعتبارِ ناشی از این پرداخت (کفِ صفر) + بی‌اعتمادکردنِ کاربر.
// ضدِ دوبار با گذارِ اتمیکِ approved→reversed. null یعنی قبلاً برگشت خورده/approved نبوده.
async function reversePayment(paymentId) {
  if (stmts.markPaymentReversed.run(paymentId).changes === 0) return null;
  const p = stmts.getPayment.get(paymentId);
  const creditAmount = p.original_amount || p.amount;
  const back = creditAmount + (p.pkg ? 0 : bonusFor(creditAmount)); // دقیقاً همان که approve اعتبار داد
  stmts.clawback.run(back, p.user_id);
  stmts.setDistrust.run(p.user_id);
  track(db, p.user_id, 'payment_reversed', { payment_id: paymentId, amount: p.amount, clawed: back });
  return { p, back };
}

// allowRejected فقط از مسیرِ پشتیبانی می‌آید: پرداختی که ایجنت اشتباهاً رد کرده بود باید
// بتواند برگردد. مسیرِ خودکار هرگز این را نمی‌فرستد، پس رفتارِ عادی دست‌نخورده می‌ماند.
function approvePayment(paymentId, allowRejected = false) {
  const p = stmts.getPayment.get(paymentId);
  const okStates = allowRejected ? ['pending', 'waiting_review', 'rejected'] : ['pending', 'waiting_review'];
  if (!p || !okStates.includes(p.status)) return null;
  const creditAmount = p.original_amount || p.amount;
  // بسته‌ی الماس خودش تخفیفِ ذاتی دارد؛ هدیه‌ی شارژِ ۲۰۰k رویش اعمال نمی‌شود (وگرنه بسته‌ی
  // بزرگ دو بار تخفیف می‌گرفت و نردبانِ قیمت بی‌معنی می‌شد).
  const bonus = p.pkg ? 0 : bonusFor(creditAmount);
  stmts.setPaymentStatus.run('approved', paymentId);
  stmts.credit.run(creditAmount + bonus, p.user_id);
  track(db, p.user_id, EVENTS.PAYMENT_APPROVED, { payment_id: paymentId, amount: p.amount, credited: creditAmount + bonus });
  if (p.discount_code_id) {
    stmts.incDiscountUses.run(p.discount_code_id);
    stmts.insertDiscountUse.run(p.discount_code_id, p.user_id, paymentId, (p.original_amount || p.amount) - p.amount);
  }
  return { p, creditAmount, bonus };
}

// پیشنهاد دوباره‌ی فال رزروشده (بعد از انصراف پرداخت، پیام متنی وسط پی‌وال و…)
async function offerPendingReading(ctx, uid) {
  const s = getSession(uid);
  const r = s.readingId && stmts.getReading.get(s.readingId);
  if (!r || r.status !== 'pending_payment') return false;
  const balance = getBalance(uid);
  if (balance >= r.price) {
    const body = COVERED_PAYWALL_ENABLED ? coveredText(uid, r) : L.reading.paywall(r.price);
    await ctx.reply(body, Markup.inlineKeyboard([
      coveredRow(r.id, r.price, uid),
      [Markup.button.callback(L.buttons.cancel, `rcancel:${r.id}`)],
    ]));
  } else {
    await ctx.reply(needBalanceText(uid, r), {
      ...needBalanceExtra,
      ...Markup.inlineKeyboard([
        ...needBalanceRows(uid, r),
        [Markup.button.callback(L.buttons.cancel, `rcancel:${r.id}`)],
      ]),
    });
  }
  return true;
}

// مهم‌ترین اهرم کانورژن: بعد از تأیید شارژ، فالِ رزروشده خودکار ادامه پیدا می‌کند
async function afterApproval(uid) {
  const s = getSession(uid);
  delete s.paymentId;
  setSession(uid, s);
  if (s.readingId) {
    const r = stmts.getReading.get(s.readingId);
    if (r && r.status === 'pending_payment') {
      setState(uid, 'confirm_pay');
      await bot.telegram.sendMessage(uid, L.reading.resumeAfterRecharge, {
        reply_markup: Markup.inlineKeyboard([coveredRow(r.id, r.price, uid)]).reply_markup,
      }).catch(() => {});
      return;
    }
  }
  setState(uid, 'idle');
}

bot.action(/^approve:(\d+)$/, async (ctx) => {
  if (!isAdmin(ctx.from.id)) return ctx.answerCbQuery('🔒').catch(() => {});
  const done = approvePayment(parseInt(ctx.match[1], 10));
  if (!done) return ctx.answerCbQuery('قبلاً پردازش شده').catch(() => {});
  await ctx.answerCbQuery('✅').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  const { p, creditAmount, bonus } = done;
  await bot.telegram.sendMessage(p.user_id, approvedMsg(p.user_id, creditAmount, bonus)).catch(() => {});
  await afterApproval(p.user_id);
});
bot.action(/^reject:(\d+)$/, async (ctx) => {
  if (!isAdmin(ctx.from.id)) return ctx.answerCbQuery('🔒').catch(() => {});
  const p = rejectPaymentDb(parseInt(ctx.match[1], 10));
  if (!p) return ctx.answerCbQuery('قبلاً پردازش شده').catch(() => {});
  await ctx.answerCbQuery('❌').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await bot.telegram.sendMessage(p.user_id, L.wallet.rejected).catch(() => {});
});

/* ── شبکه‌ی ایمنیِ auto-approve: «پیامکش نیومده» → تأیید دوم → برگشت + بی‌اعتمادی ── */
bot.action(/^cardsms:(\d+)$/, async (ctx) => {
  if (!isAdmin(ctx.from.id)) return ctx.answerCbQuery('🔒').catch(() => {});
  await ctx.answerCbQuery().catch(() => {});
  const pid = parseInt(ctx.match[1], 10);
  await ctx.reply(L.wallet.confirmReverse(pid), Markup.inlineKeyboard([[
    Markup.button.callback(L.buttons.reverseYes, `cardrev:${pid}`),
    Markup.button.callback(L.buttons.reverseNo, `cardrevno:${pid}`),
  ]])).catch(() => {});
});
bot.action(/^cardrev:(\d+)$/, async (ctx) => {
  if (!isAdmin(ctx.from.id)) return ctx.answerCbQuery('🔒').catch(() => {});
  await ctx.answerCbQuery('در حال برگشت…').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  const done = await reversePayment(parseInt(ctx.match[1], 10));
  if (!done) return ctx.reply(L.wallet.reverseAlready).catch(() => {});
  await bot.telegram.sendMessage(done.p.user_id, L.wallet.reversedUser(curOf(done.p.user_id))).catch(() => {});
  await ctx.reply(L.wallet.adminReversed(done.p.id, done.p.user_id, done.back)).catch(() => {});
});
bot.action(/^cardrevno:(\d+)$/, async (ctx) => {
  if (!isAdmin(ctx.from.id)) return ctx.answerCbQuery('🔒').catch(() => {});
  await ctx.answerCbQuery('بی‌خیال شد').catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.wallet.reverseCancelled(parseInt(ctx.match[1], 10))).catch(() => {});
});

/* ── رد پرداخت (DB جدا از ctx) + یادآوری/صف داشبورد (مثل voice2text) ── */
function rejectPaymentDb(paymentId) {
  const p = stmts.getPayment.get(paymentId);
  if (!p || p.status !== 'waiting_review') return null;
  stmts.setPaymentStatus.run('rejected', p.id);
  track(db, p.user_id, EVENTS.PAYMENT_REJECTED, { payment_id: p.id, amount: p.amount });
  return p;
}
// ارسال دوباره‌ی رسیدِ معطل به ادمین‌ها با همان دکمه‌های تأیید/رد
async function resendReceiptToAdmins(p) {
  const u = getUser(p.user_id);
  const caption = `⏳ یادآوری: رسید منتظر تأیید (بیش از ۲ ساعت)\n\n👤 ${dispName(u) || u?.name || '-'}\n🆔 ${p.user_id}\n💰 ${(p.original_amount || p.amount).toLocaleString('fa-IR')} تومان\n🔢 پرداخت #${p.id}\n\nهمین‌جا تأیید/رد کن (یا از داشبورد):`;
  const kb = Markup.inlineKeyboard([[
    Markup.button.callback('✅ تایید', `approve:${p.id}`),
    Markup.button.callback('❌ رد', `reject:${p.id}`),
  ]]).reply_markup;
  for (const adminId of ADMIN_IDS) {
    try {
      if (p.receipt_file_id) await bot.telegram.sendPhoto(adminId, p.receipt_file_id, { caption, reply_markup: kb });
      else await bot.telegram.sendMessage(adminId, caption, { reply_markup: kb });
    } catch {}
  }
  stmts.setReminded.run(p.id);
}
// sweep پرداخت (۶۰ ثانیه): درین صف اکشن داشبورد + یادآوری رسیدهای معطل — همه fail-safe
setInterval(async () => {
  try {
    for (const act of stmts.pendingActions.all()) {
      try {
        if (act.action === 'approve' || act.action === 'force_approve') {
          const done = approvePayment(act.payment_id, act.action === 'force_approve');
          if (done) { await bot.telegram.sendMessage(done.p.user_id, approvedMsg(done.p.user_id, done.creditAmount, done.bonus)).catch(() => {}); await afterApproval(done.p.user_id); }
        } else if (act.action === 'reject') {
          const p = rejectPaymentDb(act.payment_id);
          if (p) await bot.telegram.sendMessage(p.user_id, L.wallet.rejected).catch(() => {});
        } else if (act.action === 'approve_accounting') {
          // «فقط حسابداری»: پولی که واقعاً رسیده ولی کاربر ارزشش را از راهِ دیگری گرفته
          // (جبرانِ دستی، کدِ هدیه). وضعیت به approved می‌رود تا SUM(amount) درآمدِ واقعی را
          // نشان دهد، ولی **هیچ اعتباری داده نمی‌شود و هیچ پیامی به کاربر نمی‌رود**.
          const p2 = stmts.getPayment.get(act.payment_id);
          if (p2 && ['pending', 'waiting_review', 'rejected', 'canceled'].includes(p2.status)) {
            stmts.setPaymentStatus.run('approved', p2.id);
            track(db, p2.user_id, EVENTS.PAYMENT_APPROVED,
              { payment_id: p2.id, amount: p2.amount, credited: 0, accounting: 1 });
          }
        } else if (act.action === 'debit') {
          // کسرِ اعتبار (اصلاحِ حساب توسط پشتیبانی) — کفِ صفر، بی‌صدا برای کاربر
          const uid2 = act.user_id, amt = act.amount;
          if (uid2 && amt > 0 && getUser(uid2)) {
            const take = Math.min(amt, getBalance(uid2));
            if (take > 0) stmts.credit.run(-take, uid2);
            track(db, uid2, 'credit_adjusted', { amount: -take, kind: 'support' });
          }
        } else if (act.action === 'credit') {
          // شارژِ دستیِ پشتیبانی — بدونِ کدِ تخفیف و بدونِ ردیفِ payments (هدیه است نه درآمد)
          const uid2 = act.user_id, amt = act.amount;
          if (uid2 && amt > 0 && getUser(uid2)) {
            stmts.credit.run(amt, uid2);
            track(db, uid2, 'credit_granted', { amount: amt, kind: 'support' });
            await bot.telegram.sendMessage(uid2, L.wallet.supportCredited(amt, getBalance(uid2), curOf(uid2))).catch(() => {});
            await afterApproval(uid2); // اگر فالِ رزروشده دارد، خودکار ادامه پیدا کند
          }
        } else if (act.action === 'unlock_reading') {
          // بازکردنِ دستیِ یک فالِ رزروشده: قیمتش اعتبار داده می‌شود و خودِ کاربر با دکمه‌ی
          // همیشگی بازش می‌کند — یعنی هیچ مسیرِ کسرِ جدیدی ساخته نمی‌شود (ریلِ پول تک‌منبع).
          const r = stmts.getReading.get(act.ref_id);
          if (r && r.status === 'pending_payment') {
            stmts.credit.run(r.price, r.user_id);
            track(db, r.user_id, 'credit_granted', { amount: r.price, kind: 'support_reading', reading_id: r.id });
            await bot.telegram.sendMessage(r.user_id, L.wallet.supportUnlocked, {
              reply_markup: Markup.inlineKeyboard([coveredRow(r.id, r.price, r.user_id)]).reply_markup,
            }).catch(() => {});
          }
        }
      } catch (e) { logErr('admin_action exec:', act.id, e.message); }
      stmts.markActionDone.run(act.id);
    }
    for (const p of stmts.staleReceipts.all()) await resendReceiptToAdmins(p);
  } catch (e) { logErr('payment sweep:', e.message); }
}, 60_000);

/* ---------- ادمین: /stats و /newcode ---------- */
bot.command('stats', (ctx) => {
  if (!isAdmin(ctx.from.id)) return;
  const types = stmts.readingsByType.all().map(t => `  ${t.type}: ${fmt(t.c)} فال / ${fmt(t.s)} تومان`).join('\n') || '  —';
  // قیف کانورژن: pending_payment باقی‌مانده = رهاشده در پی‌وال؛ delivered/کل = نرخ تکمیل
  const funnel = stmts.readingsByStatus.all().map(x => `  ${x.status}: ${fmt(x.c)}`).join('\n') || '  —';
  return ctx.reply(
    `📊 آمار\n\n👥 کاربران: ${fmt(stmts.countUsers.get().c)}\n` +
    `💰 درآمد ۲۴س: ${fmt(stmts.dailyRevenue.get().s)}\n💰 درآمد ۳۰روز: ${fmt(stmts.monthlyRevenue.get().s)}\n💰 کل: ${fmt(stmts.totalRevenue.get().s)}\n\n🔮 فال‌های کامل:\n${types}\n\n📈 قیف (وضعیت همه‌ی فال‌ها):\n${funnel}`
  );
});
// /newcode CODE PERCENT DAYS [USER_ID]
bot.command('newcode', (ctx) => {
  if (!isAdmin(ctx.from.id)) return;
  const parts = ctx.message.text.trim().split(/\s+/).slice(1);
  const [code, percent, days, onlyUser] = parts;
  const pct = parseInt(normalizeDigits(percent || ''), 10);
  const d = parseInt(normalizeDigits(days || ''), 10);
  if (!code || !pct || !d) return ctx.reply('فرمت: /newcode CODE PERCENT DAYS [USER_ID]');
  try {
    stmts.insertDiscountCode.run(code.toUpperCase(), pct, null, Math.floor(Date.now() / 1000) + d * 86400,
      1, onlyUser ? parseInt(normalizeDigits(onlyUser), 10) : null, ctx.from.id);
    return ctx.reply(`✅ کد ${code.toUpperCase()} (${pct}٪، ${d} روز) ساخته شد.`);
  } catch (e) { return ctx.reply(`❌ ${e.message}`); }
});

// 🎬 /reel [mystic|nature|minimal] — ساختِ ویدیوی ریلز از سوالِ بعدیِ صفِ Notion.
// عمداً بعد از /newcode و بیرون از ناحیه‌هایی است که چک‌های سورس‌خوانِ تاروت روی آن‌ها
// ادعا دارند. ورک‌فلو خودش ویدیو را به همین چت می‌فرستد، پس این‌جا فقط «شروع شد» گفته می‌شود.
bot.command('reel', async (ctx) => {
  if (!VIDEO_REEL_ENABLED || !isAdmin(ctx.from.id)) return; // returnِ بی‌صدا، الگوی /stats
  const token = process.env.VIDEO_DISPATCH_TOKEN;
  if (!token) return ctx.reply(L.reel.noToken);
  const arg = (ctx.message.text || '').trim().split(/\s+/)[1];
  const bg = VIDEO_BACKGROUNDS.includes(arg) ? arg : '';
  // تایم‌اوتِ صریح: بدونش یک شبکه‌ی کند هندلر را تا ابد باز نگه می‌دارد و ادمین
  // هیچ جوابی نمی‌گیرد، پس دوباره می‌زند و دو ران هم‌زمان می‌سازد.
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 15000);
  try {
    const res = await fetch(
      `https://api.github.com/repos/${VIDEO_DISPATCH_REPO}/actions/workflows/tarot-video.yml/dispatches`,
      {
        method: 'POST',
        signal: ctrl.signal,
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: 'application/vnd.github+json',
          'X-GitHub-Api-Version': '2022-11-28',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ ref: 'main', inputs: bg ? { background: bg } : {} }),
      },
    );
    // گیت‌هاب برای dispatchِ موفق ۲۰۴ و بدنه‌ی خالی می‌دهد؛ هر چیز دیگری یعنی نشد.
    if (res.status === 204) return ctx.reply(L.reel.started);
    return ctx.reply(L.reel.failed(String(res.status)));
  } catch (e) {
    return ctx.reply(L.reel.failed(e.name === 'AbortError' ? 'timeout' : String(e.message || e)));
  } finally {
    clearTimeout(timer);
  }
});

/* ---------- اشتراک‌گذاری (inline mode) ---------- */
bot.on('inline_query', async (ctx) => {
  const uid = ctx.from.id;
  try {
    await ctx.answerInlineQuery([{
      type: 'article',
      id: 'invite',
      title: L.share.inlineTitle,
      description: L.share.inlineDesc,
      input_message_content: { message_text: L.share.message(BOT_USERNAME, uid) },
    }], { cache_time: 0, is_personal: true });
  } catch (e) { logErr('inline query:', e.message); }
});

/* ---------- ریست تست (قرارداد ریپو §۶ب — فاز تست: همه‌ی کاربران) ---------- */
// ابزارِ مدیریتیِ فقط-ادمین (دو آی‌دیِ ADMIN_IDS)، همیشه فعال — حتی خارج از فاز تست.
// فقط دیتای خودِ همان ادمین را پاک می‌کند و او را مثل یک کاربرِ کاملاً جدید از نو معرفی می‌کند
// (برای تستِ فلوها بدون انتظار). هیچ کاربر دیگری این را نمی‌بیند و در هیچ فلویی دخالت نمی‌کند.
async function doReset(ctx) {
  if (!isTester(ctx.from.id)) return; // گاردِ اصلی — دکمه فقط به ادمین/تستر نشان داده می‌شود، این لایه‌ی دوم است
  wipeUser(ctx.from.id);
  track(db, ctx.from.id, EVENTS.RESET, {});
  await ctx.reply(L.reset.done, mainKeyboard(ctx.from.id));
  return handleStart(ctx); // مثل کاربر تازه: آنبوردینگ از نو (upsertUser → isNew=true)
}
// هم برچسبِ جدید، هم برچسبِ قدیمیِ فاز تست (برای دکمه‌ی کش‌شده‌ی احتمالی) — doReset خودش isAdmin را چک می‌کند
bot.hears([L.buttons.resetTest, '🔄 ریست ربات (تست)'], doReset);
/* 🧪 `/loading` — نمایشِ زنده‌ی پنج طرحِ نشانگرِ انتظار، داخلِ خودِ تلگرام.
   خواسته‌ی صریحِ مالک: «یه دستور موقت باشه که بزنم و ببینمشون». عرضِ اموجی، رندرِ RTL و
   «حسِ» سرعت را نمی‌شود از روی کد قضاوت کرد؛ باید روی کلاینتِ واقعی دید.

   • **فقط تستر/ادمین** (`isTester`)، پس هیچ کاربرِ واقعی‌ای نمی‌بیندش.
   • با **همان `pace()`ِ خودِ ربات** اجرا می‌شود، نه یک سرعتِ ساختگی — وگرنه چیزی که
     می‌بینی با چیزی که کاربر می‌بیند فرق دارد.
   • `429` را **گزارش** می‌کند، چون نکته‌ی اصلیِ همین آزمایش این است که بفهمیم ضرب‌آهنگ
     به سقفِ تلگرام می‌خورد یا نه.
   • `/loading moon` فقط یک طرح را نشان می‌دهد.
   ⚠️ موقت است: `LOADING_LAB = false` کاملاً خاموشش می‌کند (یک خط). */
const LOADING_LAB = true;
const LAB_PLAY_MS = 12_000;

bot.command('loading', async (ctx) => {
  const uid = ctx.from.id;
  if (!LOADING_LAB || !isTester(uid)) return;
  const arg = (ctx.message.text.split(/\s+/)[1] || '').trim();
  const names = arg && LOADERS[arg] ? [arg] : Object.keys(LOADERS);
  const label = L.reading.loadingLabel;
  let rate = 0;

  await ctx.reply(`🧪 ${names.length} طرح، هر کدام ${LAB_PLAY_MS / 1000} ثانیه، با همان ضرب‌آهنگِ واقعیِ ربات.`);
  for (const name of names) {
    const def = LOADERS[name];
    const tag = `${def.fa}${name === ACTIVE ? '  ← الان فعال است' : ''}${def.keepsLabel ? '' : '  ⚠️ متن را عوض می‌کند'}`;
    await ctx.reply(tag).catch(() => {});
    const frame = def.frames(label);
    const m = await ctx.reply(frame(0)).catch(() => null);
    if (!m) continue;
    const startedAt = Date.now();
    let i = 1, edits = 0;
    while (Date.now() - startedAt < LAB_PLAY_MS) {
      await sleep(pace(Date.now() - startedAt));
      try {
        await ctx.telegram.editMessageText(ctx.chat.id, m.message_id, undefined, frame(i));
        edits++;
      } catch (e) {
        if (/429|Too Many Requests/i.test(e.message || '')) rate++;
      }
      i++;
    }
    await ctx.reply(`↑ ${name} · ${edits} ادیت در ${LAB_PLAY_MS / 1000} ثانیه`).catch(() => {});
    await sleep(900);
  }
  await ctx.reply(rate
    ? `⚠️ ${rate} بار 429 گرفتیم. ضرب‌آهنگ باید آرام‌تر شود (FAST_MS در bots/tarot/loading.js).`
    : `✅ هیچ 429ای نگرفتیم؛ ضرب‌آهنگِ فعلی امن است.\n\nطرحِ فعال: ${ACTIVE}. برای عوض کردنش اسمش را به من بگو.`);
});

bot.command('reset', doReset);

// 💬 پشتیبانی: عمداً هیچ گاردی جلویش نیست (راهِ فرارِ کاربرِ گیرکرده باید همیشه باز باشد و
// چون فقط یک پیامِ اطلاعاتی است، هیچ فلو/فاکتوری را یتیم نمی‌کند). ولی چون قبل از bot.on('text')
// ثبت می‌شود، متنِ دکمه دیگر به‌عنوان «نام» یا «مبلغ» بلعیده نمی‌شود؛ بعدش هم قدمِ فعلیِ کاربر
// دوباره یادآوری می‌شود تا سرگردان نماند (قرارداد ۹ب).
registerSupport(bot, {
  botCode: 'TRT',
  texts: L.support,
  // 🎯 دقیقاً باگی که مالک گزارش کرد: کاربر وسطِ فاکتور پشتیبانی را زد، گارد گفت انصراف
  // بده، انصراف داد و پیامِ عمومیِ «همیشه اینجام» گرفت به‌جای پشتیبانی. حالا هر دو گارد
  // نیتِ SUPPORT را ثبت می‌کنند و `replyCanceled` بعد از انصراف همین صفحه را برمی‌گرداند.
  after: async (ctx) => {
    if (await blockDuringOnboarding(ctx)) return;
    if (await blockDuringOpenReading(ctx, INTENT.SUPPORT)) return;
    await blockDuringOpenPay(ctx, INTENT.SUPPORT);
  },
});

/* ---------- هندلر متن (state machine) ---------- */
bot.on('text', async (ctx) => {
  const uid = ctx.from.id;
  upsertUser(ctx);
  const text = ctx.message.text;
  if (text.startsWith('/')) return;
  const state = getState(uid);
  try {
    if (state === 'onboard_name') return await finishNameOnboarding(ctx, text);
    // در مرحله‌ی حوزه‌ی تمرکز، ورودی متنی را نمی‌گیریم؛ کاربر باید از دکمه‌ها انتخاب کند (نه رد کردن مرحله).
    if (state === 'onboard_focus') {
      return ctx.reply(L.onboarding.askFocus, Markup.inlineKeyboard(
        L.buttons.focusOptions.map(([key, label]) => [Markup.button.callback(label, `focus:${key}`)])
      ));
    }
    if (state === 'await_question') return await handleQuestion(ctx, text.trim());
    if (state === 'pay_amount') {
      const amount = parseInt(normalizeDigits(text).replace(/[^\d]/g, ''), 10);
      if (!amount || amount <= 0) return ctx.reply(L.wallet.invalidAmount());
      return await setRechargeAmount(ctx, uid, amount);
    }
    if (state === 'pay_discount') return await applyDiscount(ctx, uid, text);
    if (state === 'pay_receipt') {
      // رسید متنی
      const s = getSession(uid);
      if (!s.paymentId) return ctx.reply(L.errors.stateLost, mainKeyboard(ctx.from.id));
      // اگر متن خودش یک کدِ تخفیفِ موجود است، رسید نیست: کاربر کدش را یک قدم دیرتر فرستاده.
      // ثبتش به‌عنوان رسید یعنی پرداختِ ناموجود در صفِ ادمین و در نهایت پیامِ «تأیید نشد» به
      // کاربری که اصلاً پولی نفرستاده بود. به‌جایش مثل کد تخفیف رفتارش می‌کنیم.
      if (looksLikeDiscountCode(text)) {
        setState(uid, 'pay_discount');
        return await applyDiscount(ctx, uid, text);
      }
      return await processReceipt(ctx, uid, s.paymentId, null, text, false);
    }
    if (state === 'feedback') {
      const s = getSession(uid);
      if (s.readingId) return await handleFeedback(ctx, uid, s.readingId, 'text', text.trim());
    }
    // وسط فلوی فال: به‌جای پیام خوش‌آمدِ گیج‌کننده، نرم به دکمه‌ها برگردان
    if (state === 'confirm_pay') {
      if (await offerPendingReading(ctx, uid)) return;
    }
    // ⚖️ **یک استاندارد، نه دو تا** (ایرادِ صریحِ مالک): تا قبل از v3.17.0 این‌جا پیامِ
    // دومی به نامِ `useButtons` می‌آمد («فالت هنوز بازه، از دکمه‌های همین گفتگو استفاده
    // کن») که فقط دکمه‌ی بازگشت داشت، در حالی که هر جای دیگرِ ربات برای همین موقعیت
    // پیامِ «یه فالِ باز داری» با دو دکمه‌ی ادامه/انصراف را می‌داد. حالا هر دو مسیر از
    // همان یک گارد رد می‌شوند.
    if (await blockDuringOpenReading(ctx)) return;
    // `choose_spread` فلوی باز **نیست**: فقط کاتالوگ روی صفحه است و هیچ فالی رزرو نشده،
    // پس نه گارد لازم دارد نه پیامِ خطا. کاتالوگ دوباره نشان داده می‌شود تا کاربر به‌جای
    // یک تذکر، همان چیزی را ببیند که می‌خواست انتخاب کند.
    if (state === 'choose_spread') return showCatalog(ctx);
    // 🂠 استیت‌های **گریدی** (کارتِ روز و کارتِ شانس). تا v3.17.0 این‌ها هیچ شاخه‌ای
    // نداشتند و به پیش‌فرضِ پایین می‌افتادند، یعنی کاربری که وسطِ گرید چیزی تایپ می‌کرد
    // پیامِ «خوش اومدی» می‌گرفت **و کیبوردِ ماندگار دوباره صادر می‌شد** — یک نقطه‌ی سومِ
    // پنهان که قراردادِ دو-نقطه‌ای را می‌شکست. حالا همان گرید دوباره جلوی کاربر می‌آید.
    if (state === 'daily_pick') return dailyCard(ctx);   // چیدمان قطعی است، پس بازسازی بی‌ضرر
    if (state === 'lucky_shuffle' || state === 'lucky_pick') {
      const h = openLuckyHand(uid);
      if (h) return resumeLuckyHand(ctx, uid, h);
      setState(uid, 'idle');   // دستی برای ادامه نیست؛ کاربر را در استیتِ مرده نگه ندار
      return sendContinuePrompt(ctx, uid);
    }
    // پیش‌فرض: کاربر جدید → آنبوردینگ؛ بقیه → منوی اصلی
    if (!getUser(uid).welcomed) return handleStart(ctx);
    return ctx.reply(uxV2For(uid)
      ? L.returning.greetingV2(dispName(getUser(uid)))
      : L.returning.greeting(dispName(getUser(uid)), getBalance(uid), curOf(uid)), mainKeyboard(ctx.from.id));
  } catch (e) {
    logErr('text handler:', e.message);
    return ctx.reply(L.errors.generic).catch(() => {});
  }
});

/* ---------- ویس (سؤال فال با ویس) ---------- */
bot.on(['voice', 'audio'], async (ctx) => {
  const uid = ctx.from.id;
  upsertUser(ctx);
  // در مرحله‌ی نام، ویس نمی‌گیریم (نام را تایپی می‌خواهیم) — راهنمای نرم به‌جای سکوت
  if (getState(uid) === 'onboard_name') return ctx.reply(L.onboarding.askNameRetry);
  if (getState(uid) !== 'await_question') return;
  try {
    const media = ctx.message.voice || ctx.message.audio;
    // سقف طول/حجم: خودِ فایل به مدل می‌رود، پس این سقف مستقیماً سقفِ توکنِ ورودی است.
    if ((media.duration && media.duration > MAX_VOICE_SEC) || (media.file_size && media.file_size > MAX_VOICE_BYTES)) {
      return ctx.reply(L.errors.voiceTooLong(MAX_VOICE_SEC));
    }
    // ⚠️ اینجا هیچ فراخوانیِ OpenRouter نیست (v3.4.0). قبلاً همین‌جا ویس رونویسی می‌شد،
    // یعنی برای کاربری که هیچ‌وقت پرداخت نمی‌کرد هم هزینه می‌دادیم. حالا فقط ارجاعِ فایل
    // نگه داشته می‌شود و خودِ فایل موقعِ خوانش (بعد از کسرِ اعتبار) به مدل داده می‌شود.
    const mime = media.mime_type || 'audio/ogg';
    await typing(ctx, PACE_S);
    // متنِ سؤال خالی می‌ماند؛ بعد از خوانش از `question_text` خودِ مدل پر می‌شود.
    return await handleQuestion(ctx, '', { id: media.file_id, fmt: /wav/i.test(mime) ? 'wav' : 'mp3' });
  } catch (e) {
    logErr('voice handler:', e.message);
    return ctx.reply(L.errors.generic).catch(() => {});
  }
});

/* ---------- عکس (رسید پرداخت) ---------- */
bot.on('photo', async (ctx) => {
  const uid = ctx.from.id;
  upsertUser(ctx);
  const s = getSession(uid);
  // مسیر عادی: وسط فلوی رسید. مسیر بازیابی: state گم شده (کاربر بعد از فاکتور /start زده) ولی
  // پرداختِ منتظرِ رسید در DB هست → عکس را به همان وصل کن تا پول واقعی در سیاه‌چاله نیفتد.
  let paymentId = (getState(uid) === 'pay_receipt' && s?.paymentId) ? s.paymentId : null;
  let recovered = false;
  if (!paymentId) {
    const pend = stmts.pendingReceiptPayment.get(uid);
    if (!pend) return; // عکسِ بی‌ربط به پرداخت — نادیده
    paymentId = pend.id; recovered = true;
  }
  const fileId = ctx.message.photo[ctx.message.photo.length - 1].file_id;
  await processReceipt(ctx, uid, paymentId, fileId, null, recovered);
});

/* ---------- یادآوریِ کارت روز: **حذف شد** (تصمیمِ صریحِ مالک ۱۴۰۵/۰۵/۲۹) ----------
   تا امروز این یادآوری opt-**out** بود: هر شب ساعت ۲۲ به هر کسی که کارتِ روزش را نگرفته
   بود می‌رفت، مگر اینکه خودش انصراف داده باشد. از v3.9.0 برای دنیای الماس خاموش شده بود
   و فقط کاربرانِ تومانی می‌گرفتندش؛ حالا کاملاً برداشته شد.
   چرا حذف و نه یک پرچم: تنها یادآوریِ شبانه‌ی ربات از این به بعد کارتِ شانس است که
   opt-**in** است. نگه‌داشتنِ یک جاروی خاموش یعنی کدِ مرده‌ای که هر بار باید توضیح داده
   شود (بند ۹/۰ ریشه). برگرداندنش = revert همین کامیت.
   ⚠️ هندلرهای `dailyoff*` عمداً **می‌مانند**: دکمه‌ی «🔕 دیگه یادآوری نکن» در چتِ
   کاربرانی که این پیام را گرفته‌اند زنده است و نباید بی‌جواب بماند (بند ۲ج/۶). */

/* 🍀 یادآوریِ کارت شانس — ساعت ۲۲ تهران و **تنها یادآوریِ شبانه‌ی ربات**. کاملاً
   opt-in: شرطِ `lucky_reminder_on=1` در خودِ کوئری است، پس کسی که هرگز دکمه‌ی «فردا
   یادآوری کن» را نزده هیچ‌وقت پیامی نمی‌گیرد (پیش‌فرضِ ستون صفر است). همان گاردِ
   ۱۸ساعته ضدِ پیامِ تکراری بعد از ری‌استارت. */
const REMINDER_HOUR = 22;
setInterval(async () => {
  try {
    const hour = parseInt(new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Tehran', hour: '2-digit', hour12: false,
    }).format(new Date()), 10);
    if (hour !== REMINDER_HOUR) return;
    const today = tehranToday();
    for (const { telegram_id } of stmts.dueLuckyReminder.all(today)) {
      if (!uxV2For(telegram_id)) continue;
      stmts.setLuckyReminded.run(telegram_id);
      const ok = await bot.telegram.sendMessage(telegram_id, L.lucky.reminder, {
        reply_markup: Markup.inlineKeyboard([
          [Markup.button.callback(L.buttons.luckyStart, 'lucky_go')],
          [Markup.button.callback(L.buttons.luckyRemindOff, 'lremind:0')],
        ]).reply_markup,
      }).then(() => true).catch(() => false);
      if (ok) track(db, telegram_id, 'lucky_reminder_sent', {});
      await sleep(300);
    }
  } catch (e) { logErr('lucky reminder sweep:', e.message); }
}, 15 * 60 * 1000);

// انصراف از یادآوری — تأییدِ دومرحله‌ای تا با یک تپِ اشتباه قلاب بازگشت را از دست ندهیم
bot.action('dailyoff', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  await ctx.reply(L.daily.reminderOffConfirm, Markup.inlineKeyboard([
    [Markup.button.callback(L.buttons.dailyReminderOffYes, 'dailyoff_yes')],
    [Markup.button.callback(L.buttons.cancel, 'dailyoff_no')],
  ]));
});
bot.action('dailyoff_yes', async (ctx) => {
  const uid = ctx.from.id;
  await ctx.answerCbQuery().catch(() => {});
  stmts.setDailyReminderOff.run(uid);
  track(db, uid, 'daily_reminder_off', {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.daily.reminderOffDone, mainKeyboard(uid));
});
bot.action('dailyoff_no', async (ctx) => {
  await ctx.answerCbQuery().catch(() => {});
  try { await ctx.editMessageReplyMarkup(undefined); } catch {}
  await ctx.reply(L.daily.reminderOffCanceled, mainKeyboard(ctx.from.id));
});

/* ===== Launch ===== */
if (!existsSync('./assets/cards/back.jpg')) logErr('⚠️ assets/cards ناقص است — تصاویر کارت‌ها را کامیت/دانلود کن');
function launch() {
  bot.launch({ dropPendingUpdates: true })
    .then(() => {
      log(`✅ tarot bot started (long polling, locale=${LOCALE})`);
      recoverOrphanReadings();
      refundAbandonedPaidReadings();
      // و هر شش ساعت یک بار، تا کاربری که همان روز رها کرد تا بوتِ بعدی منتظر نماند.
      setInterval(refundAbandonedPaidReadings, 6 * 3600 * 1000);
    })
    .catch((err) => { logErr('❌ launch error, retrying in 5s:', err.message); setTimeout(launch, 5000); });
}
bot.telegram.getMe().then(me => { BOT_USERNAME = me.username; }).catch(() => {});
launch();
registerGlobalErrorHandlers('tarot');
process.once('SIGINT',  () => { try { bot.stop('SIGINT'); } catch {} });
process.once('SIGTERM', () => { try { bot.stop('SIGTERM'); } catch {} });
